insert into public.courses (id, title, native_lang, target_lang, spec, published) values ('en-for-ta', 'English for Tamil Speakers', 'ta', 'en', $json${"id":"en-for-ta","title":"English for Tamil Speakers","flag":"🇬🇧","native":{"code":"ta","name":"Tamil","tts":"ta-IN"},"target":{"code":"en","name":"English","tts":"en-US","stt":"en-IN"},"persona":{"name":"Lily","emoji":"👩🏽‍🏫","color":"#FF9600","role":"English tutor"},"units":[{"title":"Hello, English!","subtitle":"Greetings, names, family, numbers, colors","section":"Section 1: Getting Started","theme":"green","intro":"Start with the words you use every day. Tamil and English work differently, so each tip shows the gap and how to close it.","tips":[{"title":"Greetings change with the time of day","body":"Tamil வணக்கம் works all day. English has a different greeting for each part of the day. Good morning is used until about noon.","examples":[{"t":"Good morning","n":"காலை வணக்கம்"},{"t":"Good night","n":"இனிய இரவு"}]},{"title":"Never skip am / is / are","body":"Tamil sentences like நான் ரவி have no word for \"am\". English always needs one. I am, you are, he/she/it is.","examples":[{"t":"I am Ravi","n":"நான் ரவி"},{"t":"She is a teacher","n":"அவள் ஒரு ஆசிரியர்"}]},{"title":"Add -s for more than one","body":"When you talk about two or more things, add -s to the noun. Tamil adds கள் instead.","examples":[{"t":"one book","n":"ஒரு புத்தகம்"},{"t":"two books","n":"இரண்டு புத்தகங்கள்"}]}],"lessons":[{"title":"Greetings","icon":"👋","tip":"English has a different greeting for each time of day: Good morning (until noon), Good afternoon, Good evening, and Good night (when you leave or go to bed). Tamil வணக்கம் works all day.","v":[["Hello","வணக்கம்","👋"],["Good morning","காலை வணக்கம்","🌅"],["Good night","இனிய இரவு","🌙"],["Thank you","நன்றி","🙏"],["Please","தயவுசெய்து"]],"s":[["Hello, how are you?","வணக்கம், நீங்கள் எப்படி இருக்கிறீர்கள்?","\"How are you?\" is the normal way to start a chat. Answer with \"I am fine.\""],["I am fine, thank you","நான் நலமாக இருக்கிறேன், நன்றி"],["Good morning, teacher","காலை வணக்கம், ஆசிரியரே"],["Please sit down","தயவுசெய்து உட்காருங்கள்"]],"fill":{"before":"Good","after":", teacher!","opts":["morning","night","evening"],"ans":0,"tr":"காலை வணக்கம், ஆசிரியரே!"},"dlg":{"lines":["Hello, how are you?"],"opts":["I am fine, thank you.","Good night.","Please sit down."],"ans":0,"tr":"வணக்கம், நீங்கள் எப்படி இருக்கிறீர்கள்?"}},{"title":"Introductions","icon":"🙋","tip":"Tamil often leaves out \"am / is / are\". English never does: \"I am Ravi\", \"She is a teacher\".","v":[["I","நான்"],["you","நீ / நீங்கள்"],["name","பெயர்","🏷️"],["friend","நண்பன்","🧑‍🤝‍🧑"],["teacher","ஆசிரியர்","👩‍🏫"]],"s":[["My name is Ravi","என் பெயர் ரவி","Tamil says என் பெயர் ரவி with no word for \"is\". English needs it: My name is Ravi."],["What is your name?","உங்கள் பெயர் என்ன?"],["Nice to meet you","உங்களை சந்தித்ததில் மகிழ்ச்சி"],["He is my friend","அவன் என் நண்பன்"]],"fill":{"before":"I","after":" Ravi.","opts":["am","is","are"],"ans":0,"tr":"நான் ரவி.","note":"Use \"am\" only with \"I\"."},"dlg":{"lines":["What is your name?"],"opts":["My name is Ravi.","I am fine.","Good night."],"ans":0,"tr":"உங்கள் பெயர் என்ன?"}},{"title":"Family","icon":"👨‍👩‍👧","tip":"\"A\" has no exact Tamil word (ஒரு is close). Use \"a\" before one thing: a brother, a doctor. Use \"an\" before a vowel sound: an apple.","v":[["mother","அம்மா","👩"],["father","அப்பா","👨"],["brother","சகோதரன்","👦"],["sister","சகோதரி","👧"],["family","குடும்பம்","👨‍👩‍👧‍👦"]],"s":[["This is my mother","இது என் அம்மா"],["I have a brother","எனக்கு ஒரு சகோதரன் இருக்கிறான்","Use \"a\" before one singular thing: a brother, a sister. Tamil uses ஒரு."],["My father is a doctor","என் அப்பா ஒரு மருத்துவர்","Jobs need \"a\": He is a doctor. Not \"He is doctor.\""],["She is my sister","அவள் என் சகோதரி"]],"fill":{"before":"She is my","after":".","opts":["sister","brother","father"],"ans":0,"tr":"அவள் என் சகோதரி.","note":"\"She\" is a girl, so the family word is a girl too: sister."},"dlg":{"lines":["Who is she?"],"opts":["She is my sister.","He is my brother.","I am fine."],"ans":0,"tr":"அவள் யார்?"}},{"title":"Numbers 1 to 5","icon":"🔢","tip":"Add -s to make a noun plural after any number bigger than one: one book, two books.","v":[["one","ஒன்று","1️⃣"],["two","இரண்டு","2️⃣"],["three","மூன்று","3️⃣"],["four","நான்கு","4️⃣"],["five","ஐந்து","5️⃣"]],"s":[["I have two books","என்னிடம் இரண்டு புத்தகங்கள் உள்ளன","After two, three, four... the noun takes -s: two books."],["There are five people","ஐந்து பேர் இருக்கிறார்கள்"],["I am ten years old","எனக்கு பத்து வயது","English says \"I am ten years old\". Tamil says \"to me ten age\"."],["Three apples, please","மூன்று ஆப்பிள்கள் தயவுசெய்து"]],"fill":{"before":"I have two","after":".","opts":["book","books","a book"],"ans":1,"tr":"என்னிடம் இரண்டு புத்தகங்கள் உள்ளன."},"dlg":{"lines":["How many books do you have?"],"opts":["I have two books.","I am fine.","My name is Ravi."],"ans":0,"tr":"உங்களிடம் எத்தனை புத்தகங்கள் உள்ளன?"}},{"title":"Colors","icon":"🎨","tip":"Colors come before the noun: a red apple, a black bag. Tamil does the same, so this one is easy.","v":[["red","சிவப்பு","🔴"],["blue","நீலம்","🔵"],["green","பச்சை","🟢"],["yellow","மஞ்சள்","🟡"],["black","கருப்பு","⚫"]],"s":[["The apple is red","ஆப்பிள் சிவப்பு","Use \"the\" for a specific thing both people know about: the apple."],["I like blue","எனக்கு நீலம் பிடிக்கும்"],["The sky is blue","வானம் நீலம்"],["My bag is black","என் பை கருப்பு"]],"fill":{"before":"The sky is","after":".","opts":["blue","red","black"],"ans":0,"tr":"வானம் நீலம்."},"dlg":{"lines":["What color is your bag?"],"opts":["My bag is black.","I have two books.","Good morning."],"ans":0,"tr":"உங்கள் பையின் நிறம் என்ன?"}}],"story":{"title":"Meeting a New Friend","cast":[{"id":"raj","name":"Raj","emoji":"🧑"},{"id":"priya","name":"Priya","emoji":"👩"},{"id":"arun","name":"Arun","emoji":"👦"}],"parts":[["raj","Hello! My name is Raj.","வணக்கம்! என் பெயர் ராஜ்."],["priya","Hi Raj! I am Priya.","வணக்கம் ராஜ்! நான் பிரியா."],["raj","Nice to meet you, Priya.","உங்களை சந்தித்ததில் மகிழ்ச்சி, பிரியா."],["priya","Nice to meet you too. This is my brother, Arun.","எனக்கும் மகிழ்ச்சி. இது என் சகோதரன், அருண்."],["arun","Hello! How are you?","வணக்கம்! நீங்கள் எப்படி இருக்கிறீர்கள்?"],["raj","I am fine, thank you.","நான் நலமாக இருக்கிறேன், நன்றி."]],"questions":[{"after":1,"q":"What is the girl's name?","opts":["Priya","Raj","Arun"],"ans":0},{"after":4,"q":"Who is Arun?","opts":["Priya's brother","Raj's teacher","Priya's father"],"ans":0}]},"roleplays":["coffee","doctor"]},{"title":"Daily Life","subtitle":"Food, home, routine, days, shopping","section":"Section 2: Everyday Life","theme":"blue","intro":"Now build real sentences. The biggest change from Tamil: in English the verb sits in the middle of the sentence, not at the end.","tips":[{"title":"Subject, Verb, Object","body":"Tamil puts the verb last. English puts it second: Subject + Verb + Object.","examples":[{"t":"I eat rice","n":"நான் சாதம் சாப்பிடுகிறேன்"}]},{"title":"He / she / it adds -s","body":"With I, you, we, they the verb stays the same. With he, she or it, add -s (or -es after go).","examples":[{"t":"She drinks tea","n":"அவள் தேநீர் குடிக்கிறாள்"},{"t":"He goes to school","n":"அவன் பள்ளிக்குச் செல்கிறான்"}]},{"title":"In, on, at","body":"Tamil adds an ending to the word (-இல், -க்கு). English puts a small word before it. at + clock time, on + day, in + morning.","examples":[{"t":"at six","n":"ஆறு மணிக்கு"},{"t":"on Monday","n":"திங்கள்கிழமை"},{"t":"in the morning","n":"காலையில்"}]}],"lessons":[{"title":"Food and Drink","icon":"🍚","tip":"English word order is Subject + Verb + Object (I eat rice). In Tamil the verb comes last. With he, she or it, add -s to the verb: she drinks.","v":[["rice","சாதம்","🍚"],["water","தண்ணீர்","💧"],["tea","தேநீர்","🍵"],["milk","பால்","🥛"],["bread","ரொட்டி","🍞"]],"s":[["I eat rice","நான் சாதம் சாப்பிடுகிறேன்","Subject (I) + verb (eat) + object (rice). The verb is in the middle, not at the end like Tamil."],["I drink water","நான் தண்ணீர் குடிக்கிறேன்"],["She drinks tea","அவள் தேநீர் குடிக்கிறாள்","With he / she / it, add -s to the verb: she drinks, he eats."],["We eat bread","நாங்கள் ரொட்டி சாப்பிடுகிறோம்"]],"fill":{"before":"She","after":" tea.","opts":["drinks","drink","drinking"],"ans":0,"tr":"அவள் தேநீர் குடிக்கிறாள்."},"dlg":{"lines":["What do you drink in the morning?"],"opts":["I drink tea.","I eat a chair.","She is my sister."],"ans":0,"tr":"நீங்கள் காலையில் என்ன குடிக்கிறீர்கள்?"}},{"title":"Home","icon":"🏠","tip":"Place words come after in / on / at in English: in the kitchen, on the table. Tamil adds endings like -இல் to the end of the word.","v":[["house","வீடு","🏠"],["door","கதவு","🚪"],["table","மேசை"],["chair","நாற்காலி","🪑"],["kitchen","சமையலறை","🍳"]],"s":[["My house is big","என் வீடு பெரியது"],["The table is in the kitchen","மேசை சமையலறையில் உள்ளது","Tamil adds -இல் to the place word. English puts \"in\" before it: in the kitchen."],["Open the door","கதவைத் திற"],["There is a chair here","இங்கே ஒரு நாற்காலி உள்ளது"]],"fill":{"before":"The table is","after":" the kitchen.","opts":["in","on","for"],"ans":0,"tr":"மேசை சமையலறையில் உள்ளது."},"dlg":{"lines":["Where is the table?"],"opts":["It is in the kitchen.","I am fine.","It is red."],"ans":0,"tr":"மேசை எங்கே?"}},{"title":"Daily Routine","icon":"⏰","tip":"Use \"at\" for clock time (at six, at ten). With he / she / it the verb gets -s or -es: he goes, she studies.","v":[["wake up","எழுந்திரு","⏰"],["eat","சாப்பிடு","🍽️"],["go","போ","🚶"],["study","படி","📚"],["sleep","தூங்கு","😴"]],"s":[["I wake up at six","நான் ஆறு மணிக்கு எழுந்திருக்கிறேன்","Use \"at\" before a clock time: at six. Tamil puts மணிக்கு after the time."],["He goes to school","அவன் பள்ளிக்குச் செல்கிறான்"],["We study English","நாங்கள் ஆங்கிலம் படிக்கிறோம்"],["I sleep at night","நான் இரவில் தூங்குகிறேன்"]],"fill":{"before":"He","after":" to school.","opts":["goes","go","going"],"ans":0,"tr":"அவன் பள்ளிக்குச் செல்கிறான்."},"dlg":{"lines":["When do you wake up?"],"opts":["I wake up at six.","I have two books.","He is my friend."],"ans":0,"tr":"நீங்கள் எப்போது எழுந்திருக்கிறீர்கள்?"}},{"title":"Time and Days","icon":"📅","tip":"Use \"on\" with days (on Monday), \"in\" with parts of the day (in the morning) and \"at\" with night (at night).","v":[["today","இன்று","📅"],["tomorrow","நாளை"],["Monday","திங்கள்"],["morning","காலை","🌅"],["night","இரவு","🌃"]],"s":[["I am busy today","நான் இன்று பிஸியாக இருக்கிறேன்"],["See you tomorrow","நாளை சந்திப்போம்"],["School starts on Monday","பள்ளி திங்கள்கிழமை தொடங்குகிறது","Use \"on\" with days: on Monday. Use \"in\" with morning or evening: in the morning."],["I work in the morning","நான் காலையில் வேலை செய்கிறேன்"]],"fill":{"before":"School starts","after":" Monday.","opts":["on","in","at"],"ans":0,"tr":"பள்ளி திங்கள்கிழமை தொடங்குகிறது."},"dlg":{"lines":["See you tomorrow!"],"opts":["See you!","I am ten years old.","The table is red."],"ans":0,"tr":"நாளை சந்திப்போம்!"}},{"title":"Shopping","icon":"🛍️","tip":"To ask a yes/no question, start with \"Do\" or \"Does\": \"Do you have a bag?\" Tamil adds ஆ at the end instead.","v":[["shop","கடை","🏪"],["money","பணம்","💰"],["cheap","மலிவு"],["expensive","விலை அதிகம்"],["buy","வாங்கு","🛒"]],"s":[["How much is this?","இது எவ்வளவு?"],["I want to buy a shirt","நான் ஒரு சட்டை வாங்க விரும்புகிறேன்","After \"want\" use \"to\" + verb: want to buy."],["It is too expensive","இது மிகவும் விலை அதிகம்"],["Do you have a bag?","உங்களிடம் பை இருக்கிறதா?","Start yes/no questions with Do/Does: Do you have a bag? Tamil adds -ஆ at the end."]],"fill":{"before":"","after":" you have a bag?","opts":["Do","Does","Are"],"ans":0,"tr":"உங்களிடம் பை இருக்கிறதா?","note":"Use \"Do\" with you, I, we, they. Use \"Does\" with he, she, it."},"dlg":{"lines":["How much is this shirt?"],"opts":["It is two hundred rupees.","I wake up at six.","My name is Ravi."],"ans":0,"tr":"இந்த சட்டை எவ்வளவு?"}}],"story":{"title":"At the Shop","cast":[{"id":"meena","name":"Meena","emoji":"👩"},{"id":"kumar","name":"Mr. Kumar","emoji":"🧔"}],"parts":[["meena","Good morning! How much is this bag?","காலை வணக்கம்! இந்த பை எவ்வளவு?"],["kumar","It is two hundred rupees.","இது இருநூறு ரூபாய்."],["meena","That is expensive. Do you have a cheaper bag?","அது விலை அதிகம். மலிவான பை இருக்கிறதா?"],["kumar","Yes. This blue bag is one hundred rupees.","ஆம். இந்த நீலப் பை நூறு ரூபாய்."],["meena","Great! I want to buy it.","அருமை! நான் அதை வாங்க விரும்புகிறேன்."],["kumar","Thank you!","நன்றி!"]],"questions":[{"after":3,"q":"How much is the blue bag?","opts":["One hundred rupees","Two hundred rupees","Five rupees"],"ans":0},{"after":4,"q":"What does Meena want to do?","opts":["Buy the blue bag","Sell a shirt","Drink tea"],"ans":0}]},"roleplays":[]},{"title":"Out and About","subtitle":"Directions, transport, weather, health, work","section":"Section 3: The Real World","theme":"purple","intro":"Time to use English outside: asking the way, taking a bus, seeing a doctor and talking about work.","tips":[{"title":"Always give a subject","body":"Tamil can say மழை பெய்கிறது with no subject. English needs \"It\": It is raining.","examples":[{"t":"It is hot today","n":"இன்று வெப்பமாக இருக்கிறது"},{"t":"It is raining","n":"மழை பெய்கிறது"}]},{"title":"Questions with do / does","body":"Put Do or Does first. After does, the verb has no -s.","examples":[{"t":"Do you have a bag?","n":"உங்களிடம் பை இருக்கிறதா?"},{"t":"When does the train leave?","n":"ரயில் எப்போது புறப்படும்?"}]},{"title":"The future with will","body":"Use will + base verb. Never add -s after will.","examples":[{"t":"I will send an email","n":"நான் ஒரு மின்னஞ்சல் அனுப்புவேன்"}]}],"lessons":[{"title":"Directions","icon":"🧭","tip":"For directions, start with the verb: \"Turn left\", \"Go straight\". Use \"the\" before places: the bus stop, the station.","v":[["left","இடது","⬅️"],["right","வலது","➡️"],["straight","நேராக","⬆️"],["near","அருகில்"],["far","தூரம்"]],"s":[["Turn left","இடதுபுறம் திரும்புங்கள்","Give directions with the verb first: Turn left, Go straight."],["Where is the bus stop?","பேருந்து நிறுத்தம் எங்கே?"],["Go straight","நேராகச் செல்லுங்கள்"],["It is near the station","அது நிலையத்திற்கு அருகில் உள்ளது"]],"fill":{"before":"Turn","after":" at the corner.","opts":["left","near","far"],"ans":0,"tr":"முனையில் இடதுபுறம் திரும்புங்கள்."},"dlg":{"lines":["Excuse me, where is the station?"],"opts":["Go straight, then turn left.","I am fine.","It is red."],"ans":0,"tr":"மன்னிக்கவும், நிலையம் எங்கே?"}},{"title":"Transport","icon":"🚌","tip":"Use \"take the bus\" or \"go by bus\". In questions with \"does\", the verb stays simple: \"When does the train leave?\" (not \"leaves\").","v":[["bus","பேருந்து","🚌"],["train","ரயில்","🚆"],["ticket","பயணச்சீட்டு","🎫"],["station","நிலையம்","🚉"],["airport","விமான நிலையம்","✈️"]],"s":[["I take the bus to work","நான் வேலைக்குப் பேருந்தில் செல்கிறேன்"],["One ticket, please","ஒரு பயணச்சீட்டு தயவுசெய்து"],["The train is late","ரயில் தாமதமாக உள்ளது"],["When does the train leave?","ரயில் எப்போது புறப்படும்?","After \"does\" the verb has no -s: When does the train leave (not leaves)."]],"fill":{"before":"When does the train","after":"?","opts":["leave","leaves","leaving"],"ans":0,"tr":"ரயில் எப்போது புறப்படும்?"},"dlg":{"lines":["Where do you want to go?"],"opts":["I want to go to the airport.","I am ten years old.","She drinks tea."],"ans":0,"tr":"நீங்கள் எங்கே செல்ல விரும்புகிறீர்கள்?"}},{"title":"Weather","icon":"🌦️","tip":"English always needs a subject. For weather we use \"It\": \"It is hot\", \"It is raining\". Tamil has no such word.","v":[["hot","வெப்பம்","🥵"],["rain","மழை","🌧️"],["cold","குளிர்","🥶"],["sun","சூரியன்","☀️"],["wind","காற்று","💨"]],"s":[["It is hot today","இன்று வெப்பமாக இருக்கிறது","English needs \"It\" here. It has no meaning, but every English sentence needs a subject."],["It is raining","மழை பெய்கிறது"],["The weather is nice","வானிலை நன்றாக உள்ளது"],["I like the rain","எனக்கு மழை பிடிக்கும்"]],"fill":{"before":"","after":" is raining.","opts":["It","He","They"],"ans":0,"tr":"மழை பெய்கிறது."},"dlg":{"lines":["How is the weather?"],"opts":["It is hot today.","I want to buy a shirt.","My father is a doctor."],"ans":0,"tr":"வானிலை எப்படி?"}},{"title":"Health","icon":"🩺","tip":"For illness say \"I have a ...\" (I have a fever). For body pain say \"My ... hurts\" (My head hurts). Tamil uses எனக்கு (to me) instead.","v":[["doctor","மருத்துவர்","🩺"],["medicine","மருந்து","💊"],["fever","காய்ச்சல்","🤒"],["head","தலை"],["pain","வலி","😣"]],"s":[["I have a fever","எனக்கு காய்ச்சல் உள்ளது","English says \"I have a fever\". Tamil uses எனக்கு (to me)."],["I need a doctor","எனக்கு ஒரு மருத்துவர் தேவை"],["My head hurts","என் தலை வலிக்கிறது"],["Take this medicine","இந்த மருந்தை எடுத்துக்கொள்ளுங்கள்"]],"fill":{"before":"I","after":" a fever.","opts":["have","am","has"],"ans":0,"tr":"எனக்கு காய்ச்சல் உள்ளது."},"dlg":{"lines":["What is the problem?"],"opts":["I have a fever.","The bus is late.","It is blue."],"ans":0,"tr":"என்ன பிரச்சனை?"}},{"title":"Work","icon":"💼","tip":"Use \"will\" + base verb for the future: \"I will send an email\" (not \"I will sends\"). Use \"an\" before vowel sounds: an office, an email.","v":[["office","அலுவலகம்","🏢"],["job","வேலை","💼"],["boss","மேலாளர்"],["meeting","கூட்டம்","🗓️"],["email","மின்னஞ்சல்","📧"]],"s":[["I work in an office","நான் ஒரு அலுவலகத்தில் வேலை செய்கிறேன்","Use \"an\" before a vowel sound: an office, an email."],["I have a meeting at ten","எனக்கு பத்து மணிக்கு ஒரு கூட்டம் உள்ளது"],["I will send an email","நான் ஒரு மின்னஞ்சல் அனுப்புவேன்","Will + base verb. No -s after will."],["My boss is very kind","என் மேலாளர் மிகவும் அன்பானவர்"]],"fill":{"before":"I will","after":" an email.","opts":["send","sends","sending"],"ans":0,"tr":"நான் ஒரு மின்னஞ்சல் அனுப்புவேன்."},"dlg":{"lines":["What do you do?"],"opts":["I work in an office.","I am very cold.","Turn left."],"ans":0,"tr":"நீங்கள் என்ன வேலை செய்கிறீர்கள்?"}}],"story":{"title":"Late for the Bus","cast":[{"id":"sam","name":"Sam","emoji":"🧑"},{"id":"anu","name":"Anu","emoji":"👩"}],"parts":[["sam","Excuse me, where is the bus stop?","மன்னிக்கவும், பேருந்து நிறுத்தம் எங்கே?"],["anu","Go straight and turn left. It is near the station.","நேராகச் சென்று இடதுபுறம் திரும்புங்கள். அது நிலையத்திற்கு அருகில் உள்ளது."],["sam","Thank you! Is the bus late today?","நன்றி! இன்று பேருந்து தாமதமா?"],["anu","Yes. It is raining and the bus is late.","ஆம். மழை பெய்கிறது, பேருந்து தாமதமாக உள்ளது."],["sam","Oh no. I have a meeting at ten.","ஐயோ. எனக்கு பத்து மணிக்கு கூட்டம் உள்ளது."],["anu","Take a taxi, then. Good luck!","அப்படியானால் டாக்ஸியில் செல்லுங்கள். வாழ்த்துகள்!"]],"questions":[{"after":1,"q":"Where is the bus stop?","opts":["Near the station","Far from the shop","In the kitchen"],"ans":0},{"after":4,"q":"Why is Sam worried?","opts":["He has a meeting at ten","He has no money","He is sick"],"ans":0}]},"roleplays":["bus","hotel","interview"]}],"roleplays":[{"id":"en-for-ta.rp.coffee","title":"Order coffee and snacks","emoji":"☕","level":"Beginner","setting":"You are at Bean Corner café. Order a drink and something to eat.","persona":{"name":"Sara","role":"Barista","emoji":"👩‍🍳"},"goals":[{"id":"greet","text":"Greet politely"},{"id":"order","text":"Order a drink"},{"id":"price","text":"Ask the price"},{"id":"snack","text":"Order something to eat"},{"id":"confirm","text":"Confirm your order"}],"opener":{"text":"Hello! Welcome to Bean Corner. What would you like?","tr":"வணக்கம்! பீன் கார்னருக்கு வரவேற்கிறோம். உங்களுக்கு என்ன வேண்டும்?"},"steps":[{"goal":"greet","keys":["hello","hi","hey","good morning","good afternoon","good evening"],"reply":"Hello! How can I help you today?","tr":"வணக்கம்! நான் உங்களுக்கு எப்படி உதவலாம்?","better":"Good morning! Could I get a coffee, please?"},{"goal":"order","keys":["coffee","tea","latte","cappuccino","juice","would like","i want","can i have","could i have","i will have"],"reply":"Great choice! Would you like something to eat with that?","tr":"நல்ல தேர்வு! அதனுடன் சாப்பிட ஏதாவது வேண்டுமா?","better":"I would like a coffee, please."},{"goal":"price","keys":["how much","price","cost"],"reply":"The coffee is three dollars. A sandwich is four dollars.","tr":"காபி மூன்று டாலர். சாண்ட்விச் நான்கு டாலர்.","better":"How much is the coffee?"},{"goal":"snack","keys":["sandwich","cake","cookie","snack","muffin","bread","biscuit","something to eat"],"reply":"Good choice! That is seven dollars in total. Is that all?","tr":"நல்ல தேர்வு! மொத்தம் ஏழு டாலர். அவ்வளவுதானா?","better":"I will also have a sandwich, please."},{"goal":"confirm","keys":["yes","that is all","thats all","thats it","that is it","okay","ok","sure","correct","confirm"],"reply":"Here you go. Enjoy your meal!","tr":"இதோ. சாப்பிட்டு மகிழுங்கள்!","better":"Yes, that is all. Thank you."},{"keys":["thank","thanks","bye","goodbye","see you"],"reply":"You are welcome! Have a nice day.","tr":"நன்றி! இனிய நாள் அமையட்டும்."}],"fallbacks":[{"text":"Sorry, I did not understand. Could you say that again?","tr":"மன்னிக்கவும், புரியவில்லை. மீண்டும் சொல்ல முடியுமா?"},{"text":"Could you say it a simple way? For example: I would like a coffee.","tr":"எளிமையாகச் சொல்ல முடியுமா? எ.கா: I would like a coffee."}],"hints":["Good morning!","I would like a coffee, please.","How much is the coffee?","I will have a sandwich.","Yes, that is all. Thank you."],"closing":{"text":"Thank you for visiting Bean Corner! See you again.","tr":"பீன் கார்னருக்கு வந்ததற்கு நன்றி! மீண்டும் சந்திப்போம்."}},{"id":"en-for-ta.rp.bus","title":"Ask for bus directions","emoji":"🚌","level":"Beginner","setting":"You are lost in town. Ask a local person how to reach the bus stop.","persona":{"name":"Mr. Das","role":"Local resident","emoji":"🧑‍🦱"},"goals":[{"id":"attention","text":"Get attention politely"},{"id":"where","text":"Ask where the bus stop is"},{"id":"repeat","text":"Repeat the directions"},{"id":"far","text":"Ask if it is far"},{"id":"thanks","text":"Say thank you"}],"opener":{"text":"Hello there. You look lost. Can I help?","tr":"வணக்கம். நீங்கள் வழி தவறியது போல் தெரிகிறது. நான் உதவலாமா?"},"steps":[{"goal":"attention","keys":["excuse me","sorry","pardon","hello","hi"],"reply":"Yes? How can I help you?","tr":"ஆம்? நான் எப்படி உதவலாம்?","better":"Excuse me, can you help me?"},{"goal":"where","keys":["where","bus stop","station","how do i get","how can i get"],"reply":"Go straight, then turn left at the shop. The bus stop is near the station.","tr":"நேராகச் சென்று, கடையில் இடதுபுறம் திரும்புங்கள். பேருந்து நிறுத்தம் நிலையத்திற்கு அருகில் உள்ளது.","better":"Excuse me, where is the bus stop?"},{"goal":"repeat","keys":["left","straight","turn","shop","so i go","so i turn"],"reply":"Yes, that is right. Go straight and turn left.","tr":"ஆம், சரி. நேராகச் சென்று இடதுபுறம் திரும்புங்கள்.","better":"So I go straight and turn left?"},{"goal":"far","keys":["far","how long","minutes","how many minutes","close"],"reply":"No, it is not far. It is only five minutes on foot.","tr":"இல்லை, தூரம் இல்லை. நடந்தால் ஐந்து நிமிடம் தான்.","better":"Is it far from here?"},{"goal":"thanks","keys":["thank","thanks"],"reply":"You are welcome! Have a safe trip.","tr":"பரவாயில்லை! பாதுகாப்பான பயணம் அமையட்டும்.","better":"Thank you very much for your help."}],"fallbacks":[{"text":"Sorry, can you say that again? Slowly, please.","tr":"மன்னிக்கவும், மெதுவாக மீண்டும் சொல்ல முடியுமா?"},{"text":"Try asking: Where is the bus stop?","tr":"இப்படிக் கேளுங்கள்: Where is the bus stop?"}],"hints":["Excuse me, can you help me?","Where is the bus stop?","So I go straight and turn left?","Is it far?","Thank you very much."],"closing":{"text":"Good luck! I hope you catch your bus.","tr":"வாழ்த்துகள்! உங்கள் பேருந்தைப் பிடிப்பீர்கள் என்று நம்புகிறேன்."}},{"id":"en-for-ta.rp.hotel","title":"Check into a hotel","emoji":"🏨","level":"Elementary","setting":"You arrive at Sunrise Hotel late in the evening. Check in.","persona":{"name":"Nina","role":"Receptionist","emoji":"🧑‍💼"},"goals":[{"id":"greet","text":"Greet the receptionist"},{"id":"booking","text":"Say you have a booking"},{"id":"name","text":"Give your name"},{"id":"breakfast","text":"Ask about breakfast"},{"id":"key","text":"Ask for the key or Wi-Fi"}],"opener":{"text":"Good evening! Welcome to Sunrise Hotel.","tr":"மாலை வணக்கம்! சன்ரைஸ் ஹோட்டலுக்கு வரவேற்கிறோம்."},"steps":[{"goal":"greet","keys":["hello","hi","good evening","good afternoon","good morning"],"reply":"Hello! Do you have a booking?","tr":"வணக்கம்! முன்பதிவு செய்துள்ளீர்களா?","better":"Good evening! I have a booking."},{"goal":"booking","keys":["booking","reservation","reserved","i booked","i have a room"],"reply":"Great. May I have your name, please?","tr":"நல்லது. உங்கள் பெயரைச் சொல்லுங்கள்.","better":"Yes, I have a booking for tonight."},{"goal":"name","keys":["my name","name is","i am","this is"],"reply":"Thank you. Your room is 204, on the second floor.","tr":"நன்றி. உங்கள் அறை 204, இரண்டாவது மாடியில்.","better":"My name is Ravi Kumar."},{"goal":"breakfast","keys":["breakfast","morning meal"],"reply":"Breakfast is from seven to ten in the restaurant.","tr":"காலை உணவு ஏழு முதல் பத்து மணி வரை உணவகத்தில்.","better":"What time is breakfast?"},{"goal":"key","keys":["key","wifi","wi fi","password","card","internet"],"reply":"Here is your key card. The Wi-Fi password is on the card.","tr":"இதோ உங்கள் சாவி அட்டை. வைஃபை கடவுச்சொல் அட்டையில் உள்ளது.","better":"Can I have the key, please?"},{"keys":["thank","thanks","bye","good night"],"reply":"You are welcome. Enjoy your stay!","tr":"பரவாயில்லை. உங்கள் தங்குதல் இனிமையாக இருக்கட்டும்!"}],"fallbacks":[{"text":"I am sorry, could you repeat that?","tr":"மன்னிக்கவும், மீண்டும் சொல்ல முடியுமா?"},{"text":"Try: I have a booking. My name is ...","tr":"முயற்சி செய்யுங்கள்: I have a booking. My name is ..."}],"hints":["Good evening!","I have a booking.","My name is Ravi Kumar.","What time is breakfast?","Can I have the key, please?"],"closing":{"text":"Have a good night!","tr":"இனிய இரவு!"}},{"id":"en-for-ta.rp.doctor","title":"Visit a doctor","emoji":"🩺","level":"Elementary","setting":"You feel sick. Tell the doctor what is wrong.","persona":{"name":"Dr. Mehta","role":"Doctor","emoji":"🧑‍⚕️"},"goals":[{"id":"greet","text":"Greet the doctor"},{"id":"problem","text":"Say what hurts"},{"id":"duration","text":"Say how long"},{"id":"medicine","text":"Ask about medicine"},{"id":"thanks","text":"Thank the doctor"}],"opener":{"text":"Hello. Please sit down. What is the problem?","tr":"வணக்கம். உட்காருங்கள். என்ன பிரச்சனை?"},"steps":[{"goal":"greet","keys":["hello","hi","good morning","good afternoon","good evening"],"reply":"Please tell me what is wrong.","tr":"என்ன பிரச்சனை என்று சொல்லுங்கள்.","better":"Good morning, doctor."},{"goal":"problem","keys":["fever","headache","head","pain","cough","stomach","sick","hurts","cold","throat","ill"],"reply":"I am sorry to hear that. How long have you had it?","tr":"அதைக் கேட்க வருந்துகிறேன். எவ்வளவு நாளாக இருக்கிறது?","better":"I have a fever and my head hurts."},{"goal":"duration","keys":["day","days","since","yesterday","week","hours","long"],"reply":"I see. You need rest and a lot of water. I will give you medicine.","tr":"சரி. உங்களுக்கு ஓய்வும் நிறைய தண்ணீரும் தேவை. நான் மருந்து தருகிறேன்.","better":"I have been sick for two days."},{"goal":"medicine","keys":["medicine","tablet","tablets","pill","pills","what should i take","how many"],"reply":"Take one tablet in the morning and one at night. Drink a lot of water.","tr":"காலையில் ஒரு மாத்திரை, இரவில் ஒரு மாத்திரை எடுங்கள். நிறைய தண்ணீர் குடியுங்கள்.","better":"How should I take the medicine?"},{"goal":"thanks","keys":["thank","thanks","bye"],"reply":"Take care! Come back if you are not better.","tr":"கவனமாக இருங்கள்! குணமாகவில்லை என்றால் மீண்டும் வாருங்கள்.","better":"Thank you, doctor."}],"fallbacks":[{"text":"Sorry, I did not catch that. Where does it hurt?","tr":"மன்னிக்கவும், புரியவில்லை. எங்கே வலிக்கிறது?"},{"text":"Try: I have a fever. My head hurts.","tr":"முயற்சி செய்யுங்கள்: I have a fever. My head hurts."}],"hints":["Good morning, doctor.","I have a fever and my head hurts.","For two days.","How should I take the medicine?","Thank you, doctor."],"closing":{"text":"Get well soon!","tr":"விரைவில் குணமாகுங்கள்!"}},{"id":"en-for-ta.rp.interview","title":"Job interview intro","emoji":"💼","level":"Intermediate","setting":"You are at an interview for a shop assistant job.","persona":{"name":"Ms. Rao","role":"Interviewer","emoji":"👩‍💼"},"goals":[{"id":"greet","text":"Greet the interviewer"},{"id":"intro","text":"Introduce yourself"},{"id":"skills","text":"Say what you can do"},{"id":"why","text":"Say why you want the job"},{"id":"thanks","text":"Thank the interviewer"}],"opener":{"text":"Good morning. Please have a seat. Tell me about yourself.","tr":"காலை வணக்கம். உட்காருங்கள். உங்களைப் பற்றி சொல்லுங்கள்."},"steps":[{"goal":"greet","keys":["hello","hi","good morning","good afternoon"],"reply":"Nice to meet you. Please tell me your name.","tr":"உங்களை சந்தித்ததில் மகிழ்ச்சி. உங்கள் பெயரைச் சொல்லுங்கள்.","better":"Good morning. Thank you for seeing me."},{"goal":"intro","keys":["my name","i am","name is","i live","years old","i have"],"reply":"Thank you. What can you do? What are your skills?","tr":"நன்றி. உங்களால் என்ன செய்ய முடியும்? உங்கள் திறமைகள் என்ன?","better":"My name is Ravi. I am twenty-five years old."},{"goal":"skills","keys":["can","skill","skills","good at","experience","speak","worked","able","learn"],"reply":"That is good. Why do you want this job?","tr":"நல்லது. நீங்கள் ஏன் இந்த வேலையை விரும்புகிறீர்கள்?","better":"I can speak English and Tamil. I am good with customers."},{"goal":"why","keys":["because","want","like","need","team","interested"],"reply":"Great. Thank you for coming. We will call you soon.","tr":"அருமை. வந்ததற்கு நன்றி. விரைவில் அழைப்போம்.","better":"I want this job because I like to help people."},{"goal":"thanks","keys":["thank","thanks","bye","goodbye"],"reply":"You are welcome. Goodbye!","tr":"பரவாயில்லை. வணக்கம்!","better":"Thank you for your time."}],"fallbacks":[{"text":"Could you tell me a little more?","tr":"இன்னும் கொஞ்சம் சொல்ல முடியுமா?"},{"text":"Try: My name is ... I can ...","tr":"முயற்சி செய்யுங்கள்: My name is ... I can ..."}],"hints":["Good morning. Thank you for seeing me.","My name is Ravi.","I can speak English and Tamil.","I want this job because I like people.","Thank you for your time."],"closing":{"text":"Good luck with everything!","tr":"எல்லாவற்றிற்கும் வாழ்த்துகள்!"}}],"tutor":{"openers":[{"t":"Hi! I am Lily, your English tutor. How are you today?","n":"வணக்கம்! நான் லில்லி, உங்கள் ஆங்கில ஆசிரியர். இன்று எப்படி இருக்கிறீர்கள்?"}],"topics":[{"keys":["bye","goodbye","see you","good night","talk later"],"replies":[{"t":"Goodbye! You spoke very well today. See you soon!","n":"போய் வருகிறேன்! இன்று நீங்கள் நன்றாகப் பேசினீர்கள். விரைவில் சந்திப்போம்!"}]},{"keys":["hello","hi","hey","good morning","good evening","good afternoon"],"replies":[{"t":"Hello! It is so nice to talk with you. How are you today?","n":"வணக்கம்! உங்களுடன் பேசுவது மகிழ்ச்சி. இன்று எப்படி இருக்கிறீர்கள்?"}]},{"keys":["my name","name is","call me"],"replies":[{"t":"Nice to meet you! Where are you from?","n":"உங்களை சந்தித்ததில் மகிழ்ச்சி! நீங்கள் எங்கிருந்து வருகிறீர்கள்?"}]},{"keys":["fine","good","great","happy","tired","sad","okay","ok","well","not bad","sleepy"],"replies":[{"t":"I am glad to hear that! What did you do today?","n":"அதைக் கேட்க மகிழ்ச்சி! இன்று என்ன செய்தீர்கள்?"},{"t":"I see. Tell me more about your day.","n":"சரி. உங்கள் நாளைப் பற்றி இன்னும் சொல்லுங்கள்."}]},{"keys":["india","tamil","chennai","madurai","coimbatore","from","live","village","city"],"replies":[{"t":"That sounds wonderful! Tell me about your family.","n":"அது அருமை! உங்கள் குடும்பத்தைப் பற்றி சொல்லுங்கள்."}]},{"keys":["mother","father","brother","sister","family","parents","wife","husband","son","daughter","amma","appa"],"replies":[{"t":"Family is important. What do they do?","n":"குடும்பம் முக்கியம். அவர்கள் என்ன வேலை செய்கிறார்கள்?"},{"t":"That is nice. Do you live together?","n":"நல்லது. நீங்கள் ஒன்றாக வசிக்கிறீர்களா?"}]},{"keys":["work","job","office","student","study","teacher","engineer","school","college","company"],"replies":[{"t":"That is interesting! Do you like it?","n":"சுவாரஸ்யம்! உங்களுக்குப் பிடிக்குமா?"},{"t":"What is the best part of your day at work?","n":"வேலையில் உங்கள் நாளின் சிறந்த பகுதி எது?"}]},{"keys":["food","eat","rice","dinner","lunch","breakfast","hungry","drink","tea","coffee","dosa","idli"],"replies":[{"t":"Yum! What is your favorite food?","n":"ஆஹா! உங்களுக்குப் பிடித்த உணவு எது?"},{"t":"Can you cook? What do you cook?","n":"உங்களுக்கு சமைக்கத் தெரியுமா? என்ன சமைப்பீர்கள்?"}]},{"keys":["like","love","music","movie","movies","cricket","sport","read","dance","hobby","play","game"],"replies":[{"t":"Nice! How often do you do that?","n":"நல்லது! எத்தனை முறை செய்வீர்கள்?"},{"t":"That sounds fun. Who do you do it with?","n":"மகிழ்ச்சியாக இருக்கும். யாருடன் செய்வீர்கள்?"}]},{"keys":["weather","hot","rain","cold","sunny","summer","monsoon"],"replies":[{"t":"The weather can change fast. Do you like the rain?","n":"வானிலை வேகமாக மாறும். உங்களுக்கு மழை பிடிக்குமா?"}]}],"fallbacks":[{"t":"That is interesting. Can you tell me more?","n":"சுவாரஸ்யம். இன்னும் சொல்ல முடியுமா?"},{"t":"Could you say that in a different way?","n":"வேறு விதமாகச் சொல்ல முடியுமா?"},{"t":"I want to hear more. What do you think?","n":"இன்னும் கேட்க விரும்புகிறேன். நீங்கள் என்ன நினைக்கிறீர்கள்?"}],"fixes":[{"re":"\\bme name\\b","hint":"Use \"my\" before a noun, not \"me\".","better":"My name is ..."},{"re":"\\bi (is|are)\\b","hint":"With \"I\" always use \"am\".","better":"I am ..."},{"re":"\\bi am (go|eat|drink|work|study|come|play|read)\\b","hint":"After \"am / is / are\" use the -ing form.","better":"I am going / eating / working ..."},{"re":"\\b(he|she|it) (go|eat|drink|work|like|have|want|study|live)\\b","hint":"Add -s after he / she / it.","better":"he goes / she eats / it works ..."},{"re":"\\b(two|three|four|five|six|seven|eight|nine|ten) (book|friend|apple|brother|sister|bag|house|day)\\b","hint":"After a number bigger than one, add -s to the noun.","better":"two books / three friends ..."},{"re":"\\bdoes (he|she|it) \\w+s\\b","hint":"After \"does\" use the plain verb, without -s.","better":"Does she like tea?"},{"re":"\\bwhat you\\b","hint":"Questions need a helper verb: do / does / are.","better":"What do you ...?"},{"re":"\\byesterday i (go|eat|come|see|have|do)\\b","hint":"Use the past tense for yesterday.","better":"Yesterday I went / ate / came / saw ..."},{"re":"\\bi am agree\\b","hint":"\"Agree\" is a verb. Do not say \"am\".","better":"I agree."},{"re":"\\bi (am )?(doctor|teacher|engineer|student|driver)\\b","hint":"Add \"a\" before a job.","better":"I am a teacher."}],"closers":[{"t":"Great talking with you! Keep practicing. Goodbye!","n":"உங்களுடன் பேசியது மகிழ்ச்சி! தொடர்ந்து பயிற்சி செய்யுங்கள். வணக்கம்!"}]}}$json$::jsonb, true) on conflict (id) do update set title = excluded.title, spec = excluded.spec, published = true;
insert into public.courses (id, title, native_lang, target_lang, spec, published) values ('es-for-en', 'Spanish for English Speakers', 'en', 'es', $json${"id":"es-for-en","title":"Spanish for English Speakers","flag":"🇪🇸","native":{"code":"en","name":"English","tts":"en-US"},"target":{"code":"es","name":"Spanish","tts":"es-ES","stt":"es-ES"},"persona":{"name":"Maya","emoji":"👩🏻‍🏫","color":"#CE82FF","role":"Spanish tutor"},"units":[{"title":"Hola, Spanish!","subtitle":"Greetings, names, family, numbers, colors","section":"Section 1: Getting Started","theme":"green","intro":"Spanish is very regular and you pronounce it the way you read it. Start with the everyday basics.","tips":[{"title":"Questions get two marks","body":"Spanish opens a question with ¿ and closes it with ?. The opening mark tells you early that a question is coming.","examples":[{"t":"¿Cómo estás?","n":"How are you?"},{"t":"¿Cómo te llamas?","n":"What is your name?"}]},{"title":"Every noun has a gender","body":"Nouns are masculine (el, un) or feminine (la, una). Most words ending in -o are masculine and -a feminine.","examples":[{"t":"el hermano","n":"the brother"},{"t":"la hermana","n":"the sister"}]},{"title":"Add -s for plurals","body":"Add -s to a noun ending in a vowel: libro, libros. Numbers above one need the plural.","examples":[{"t":"un libro","n":"one book"},{"t":"dos libros","n":"two books"}]}],"lessons":[{"title":"Greetings","icon":"👋","tip":"Spanish says \"buenos días\" (plural) for good morning, but \"buenas noches\" for good night. Questions start with ¿ and end with ?.","v":[["hola","hello","👋"],["buenos días","good morning","🌅"],["buenas noches","good night","🌙"],["gracias","thank you","🙏"],["por favor","please"]],"s":[["Hola, ¿cómo estás?","Hello, how are you?","Spanish questions start with ¿ and end with ?."],["Estoy bien, gracias","I am fine, thank you"],["Buenos días, profesora","Good morning, teacher"],["Por favor, siéntate","Please sit down"]],"fill":{"before":"Buenos","after":", profesora.","opts":["días","noches","tardes"],"ans":0,"tr":"Good morning, teacher."},"dlg":{"lines":["Hola, ¿cómo estás?"],"opts":["Estoy bien, gracias.","Buenas noches.","Por favor."],"ans":0,"tr":"Hello, how are you?"}},{"title":"Introductions","icon":"🙋","tip":"To say your name use \"Me llamo ...\" (literally \"I call myself\"). To ask, use \"¿Cómo te llamas?\".","v":[["yo","I"],["tú","you"],["nombre","name","🏷️"],["amigo","friend","🧑‍🤝‍🧑"],["profesor","teacher","👨‍🏫"]],"s":[["Me llamo Ravi","My name is Ravi","Spanish says \"I call myself\" (me llamo) for \"my name is\"."],["¿Cómo te llamas?","What is your name?"],["Mucho gusto","Nice to meet you"],["Él es mi amigo","He is my friend"]],"fill":{"before":"Me","after":" Ravi.","opts":["llamo","llamas","llama"],"ans":0,"tr":"My name is Ravi.","note":"Me goes with llamo (I). Te goes with llamas (you)."},"dlg":{"lines":["¿Cómo te llamas?"],"opts":["Me llamo Ravi.","Estoy bien.","Buenas noches."],"ans":0,"tr":"What is your name?"}},{"title":"Family","icon":"👨‍👩‍👧","tip":"Every Spanish noun is masculine or feminine. Use el / un for masculine and la / una for feminine. Family words show it clearly: hermano / hermana.","v":[["madre","mother","👩"],["padre","father","👨"],["hermano","brother","👦"],["hermana","sister","👧"],["familia","family","👨‍👩‍👧‍👦"]],"s":[["Esta es mi madre","This is my mother","\"Esta\" goes with feminine words (madre), \"este\" with masculine (padre)."],["Tengo un hermano","I have a brother"],["Mi padre es médico","My father is a doctor","Spanish drops \"a\" before jobs: es médico, not es un médico."],["Ella es mi hermana","She is my sister"]],"fill":{"before":"Ella es mi","after":".","opts":["hermana","hermano","padre"],"ans":0,"tr":"She is my sister.","note":"\"Ella\" is she, so use the feminine word: hermana."},"dlg":{"lines":["¿Quién es ella?"],"opts":["Ella es mi hermana.","Él es mi hermano.","Estoy bien."],"ans":0,"tr":"Who is she?"}},{"title":"Numbers 1 to 5","icon":"🔢","tip":"Add -s to make a noun plural: un libro, dos libros. For age, Spanish says \"tengo ... años\" (I have ... years).","v":[["uno","one","1️⃣"],["dos","two","2️⃣"],["tres","three","3️⃣"],["cuatro","four","4️⃣"],["cinco","five","5️⃣"]],"s":[["Tengo dos libros","I have two books","For more than one, add -s to the noun: un libro, dos libros."],["Hay cinco personas","There are five people"],["Tengo diez años","I am ten years old","Spanish says \"I have ten years\" (tengo diez años) for age."],["Tres manzanas, por favor","Three apples, please"]],"fill":{"before":"Tengo dos","after":".","opts":["libros","libro","un libro"],"ans":0,"tr":"I have two books."},"dlg":{"lines":["¿Cuántos libros tienes?"],"opts":["Tengo dos libros.","Me llamo Ravi.","Buenos días."],"ans":0,"tr":"How many books do you have?"}},{"title":"Colors","icon":"🎨","tip":"Colors usually go AFTER the noun and match its gender: la manzana roja, el libro rojo. English puts them before.","v":[["rojo","red","🔴"],["azul","blue","🔵"],["verde","green","🟢"],["amarillo","yellow","🟡"],["negro","black","⚫"]],"s":[["La manzana es roja","The apple is red","Colors change to match the noun: la manzana roja (feminine), el coche rojo (masculine)."],["Me gusta el azul","I like blue"],["El cielo es azul","The sky is blue"],["Mi bolsa es negra","My bag is black"]],"fill":{"before":"El cielo es","after":".","opts":["azul","roja","negra"],"ans":0,"tr":"The sky is blue.","note":"Cielo is masculine, so pick a form that works for masculine: azul. Roja and negra are feminine."},"dlg":{"lines":["¿De qué color es tu bolsa?"],"opts":["Mi bolsa es negra.","Tengo dos libros.","Buenas noches."],"ans":0,"tr":"What color is your bag?"}}],"story":{"title":"Un nuevo amigo","cast":[{"id":"raul","name":"Raúl","emoji":"🧑"},{"id":"sofia","name":"Sofía","emoji":"👩"},{"id":"arturo","name":"Arturo","emoji":"👦"}],"parts":[["raul","¡Hola! Me llamo Raúl.","Hello! My name is Raúl."],["sofia","¡Hola, Raúl! Yo soy Sofía.","Hi, Raúl! I am Sofía."],["raul","Mucho gusto, Sofía.","Nice to meet you, Sofía."],["sofia","Igualmente. Este es mi hermano, Arturo.","Likewise. This is my brother, Arturo."],["arturo","¡Hola! ¿Cómo estás?","Hello! How are you?"],["raul","Estoy bien, gracias.","I am fine, thank you."]],"questions":[{"after":1,"q":"What is the girl's name?","opts":["Sofía","Raúl","Arturo"],"ans":0},{"after":4,"q":"Who is Arturo?","opts":["Sofía's brother","Raúl's teacher","Sofía's father"],"ans":0}]},"roleplays":["coffee","doctor"]},{"title":"Daily Life","subtitle":"Food, home, routine, days, shopping","section":"Section 2: Everyday Life","theme":"blue","intro":"Spanish verbs change their ending for each person. Learn the pattern once and it works for hundreds of verbs.","tips":[{"title":"Verbs change endings","body":"The ending tells you who is doing the action, so you can often drop the pronoun.","examples":[{"t":"yo como","n":"I eat"},{"t":"ella come","n":"she eats"},{"t":"nosotros comemos","n":"we eat"}]},{"title":"Ser vs estar (is)","body":"Use \"estar\" for where something is and for temporary states. Use \"ser\" for what something is like.","examples":[{"t":"La mesa está en la cocina","n":"The table is in the kitchen"},{"t":"Mi casa es grande","n":"My house is big"}]},{"title":"Time and days","body":"Days use \"el\": el lunes. Clock time uses \"a las\": a las seis.","examples":[{"t":"a las seis","n":"at six"},{"t":"el lunes","n":"on Monday"}]}],"lessons":[{"title":"Food and Drink","icon":"🍚","tip":"Spanish verbs change their ending for each person: yo como (I eat), ella come (she eats), nosotros comemos (we eat). Nouns have gender: el arroz, la leche.","v":[["arroz","rice","🍚"],["agua","water","💧"],["té","tea","🍵"],["leche","milk","🥛"],["pan","bread","🍞"]],"s":[["Yo como arroz","I eat rice","The verb changes with the person: yo como, tú comes, ella come."],["Yo bebo agua","I drink water"],["Ella bebe té","She drinks tea"],["Nosotros comemos pan","We eat bread"]],"fill":{"before":"Ella","after":" té.","opts":["bebe","bebo","bebemos"],"ans":0,"tr":"She drinks tea."},"dlg":{"lines":["¿Qué bebes por la mañana?"],"opts":["Bebo té.","Tengo dos libros.","Ella es mi hermana."],"ans":0,"tr":"What do you drink in the morning?"}},{"title":"Home","icon":"🏠","tip":"Use \"estar\" (está) to say where something is. Use \"es\" for what something is like: la casa es grande, la mesa está en la cocina.","v":[["casa","house","🏠"],["puerta","door","🚪"],["mesa","table"],["silla","chair","🪑"],["cocina","kitchen","🍳"]],"s":[["Mi casa es grande","My house is big"],["La mesa está en la cocina","The table is in the kitchen","Use \"estar\" for where something is: la mesa está en la cocina."],["Abre la puerta","Open the door"],["Aquí hay una silla","There is a chair here"]],"fill":{"before":"La mesa","after":" en la cocina.","opts":["está","es","soy"],"ans":0,"tr":"The table is in the kitchen.","note":"Location = estar. \"Está\" is the él/ella form of estar."},"dlg":{"lines":["¿Dónde está la mesa?"],"opts":["Está en la cocina.","Me llamo Ravi.","Tengo diez años."],"ans":0,"tr":"Where is the table?"}},{"title":"Daily Routine","icon":"⏰","tip":"Say the time with \"a la(s)\": a las seis (at six). \"Ir\" is irregular: voy, vas, va. Reflexive verbs like despertarse need me / te / se.","v":[["despertarse","to wake up","⏰"],["comer","to eat","🍽️"],["ir","to go","🚶"],["estudiar","to study","📚"],["dormir","to sleep","😴"]],"s":[["Me despierto a las seis","I wake up at six","Reflexive verbs use me/te/se: me despierto = I wake (myself) up."],["Él va a la escuela","He goes to school","\"Ir\" is irregular: voy, vas, va, vamos, van."],["Estudiamos español","We study Spanish"],["Duermo por la noche","I sleep at night"]],"fill":{"before":"Él","after":" a la escuela.","opts":["va","voy","vas"],"ans":0,"tr":"He goes to school."},"dlg":{"lines":["¿A qué hora te despiertas?"],"opts":["Me despierto a las seis.","Tengo dos libros.","Es mi amigo."],"ans":0,"tr":"What time do you wake up?"}},{"title":"Time and Days","icon":"📅","tip":"Days use \"el\" (el lunes = on Monday). Parts of the day use \"por la\": por la mañana. Temporary states use \"estar\": estoy ocupado.","v":[["hoy","today","📅"],["mañana","tomorrow"],["lunes","Monday"],["por la mañana","in the morning","🌅"],["la noche","night","🌃"]],"s":[["Hoy estoy ocupado","I am busy today","Use \"estar\" for temporary states like busy or tired."],["Hasta mañana","See you tomorrow"],["La escuela empieza el lunes","School starts on Monday","Days of the week use \"el\": el lunes = on Monday."],["Trabajo por la mañana","I work in the morning"]],"fill":{"before":"La escuela empieza","after":" lunes.","opts":["el","la","en"],"ans":0,"tr":"School starts on Monday."},"dlg":{"lines":["¡Hasta mañana!"],"opts":["¡Hasta luego!","Tengo diez años.","Mi casa es grande."],"ans":0,"tr":"See you tomorrow!"}},{"title":"Shopping","icon":"🛍️","tip":"Spanish questions need no \"do/does\". Just add ¿ and ? and change your tone: \"¿Tienes una bolsa?\". Use \"quiero\" (I want) + verb: quiero comprar.","v":[["tienda","shop","🏪"],["dinero","money","💰"],["barato","cheap"],["caro","expensive"],["comprar","to buy","🛒"]],"s":[["¿Cuánto cuesta esto?","How much is this?"],["Quiero comprar una camisa","I want to buy a shirt","Quiero + infinitive = I want to ..."],["Es demasiado caro","It is too expensive"],["¿Tienes una bolsa?","Do you have a bag?","No helper verb needed in Spanish questions: just add ¿ ? and raise your voice."]],"fill":{"before":"Quiero","after":" una camisa.","opts":["comprar","compro","compras"],"ans":0,"tr":"I want to buy a shirt.","note":"After \"quiero\" use the infinitive (comprar), not a conjugated form."},"dlg":{"lines":["¿Cuánto cuesta la camisa?"],"opts":["Cuesta veinte euros.","Me despierto a las seis.","Es mi amigo."],"ans":0,"tr":"How much is the shirt?"}}],"story":{"title":"En la tienda","cast":[{"id":"marta","name":"Marta","emoji":"👩"},{"id":"lopez","name":"Sr. López","emoji":"🧔"}],"parts":[["marta","¡Buenos días! ¿Cuánto cuesta esta bolsa?","Good morning! How much is this bag?"],["lopez","Cuesta veinte euros.","It costs twenty euros."],["marta","Es cara. ¿Tiene una bolsa más barata?","It is expensive. Do you have a cheaper bag?"],["lopez","Sí. Esta bolsa azul cuesta diez euros.","Yes. This blue bag costs ten euros."],["marta","¡Perfecto! Quiero comprarla.","Perfect! I want to buy it."],["lopez","¡Gracias!","Thank you!"]],"questions":[{"after":3,"q":"How much is the blue bag?","opts":["Ten euros","Twenty euros","Five euros"],"ans":0},{"after":4,"q":"What does Marta want to do?","opts":["Buy the blue bag","Sell a shirt","Drink tea"],"ans":0}]},"roleplays":[]},{"title":"Out and About","subtitle":"Directions, transport, weather, health, work","section":"Section 3: The Real World","theme":"purple","intro":"Get around town, talk about the weather, see a doctor and chat about work.","tips":[{"title":"Directions use commands","body":"Use the tú command form: gira (turn), sigue (continue), cruza (cross).","examples":[{"t":"Gira a la izquierda","n":"Turn left"},{"t":"Sigue todo recto","n":"Go straight"}]},{"title":"Weather uses hacer","body":"Spanish says \"it makes heat\": hace calor. For rain use está lloviendo.","examples":[{"t":"Hace calor","n":"It is hot"},{"t":"Está lloviendo","n":"It is raining"}]},{"title":"The near future: ir a","body":"Use ir + a + infinitive to say what you are going to do.","examples":[{"t":"Voy a enviar un correo","n":"I am going to send an email"}]}],"lessons":[{"title":"Directions","icon":"🧭","tip":"Directions use commands: gira (turn), sigue (continue). \"Cerca de\" = near, \"lejos de\" = far from.","v":[["izquierda","left","⬅️"],["derecha","right","➡️"],["recto","straight","⬆️"],["cerca","near"],["lejos","far"]],"s":[["Gira a la izquierda","Turn left","Commands (tú form): gira = turn, sigue = continue."],["¿Dónde está la parada de autobús?","Where is the bus stop?"],["Sigue todo recto","Go straight"],["Está cerca de la estación","It is near the station"]],"fill":{"before":"Gira a la","after":".","opts":["izquierda","recto","lejos"],"ans":0,"tr":"Turn left."},"dlg":{"lines":["Perdone, ¿dónde está la estación?"],"opts":["Sigue todo recto y gira a la izquierda.","Estoy bien.","Es azul."],"ans":0,"tr":"Excuse me, where is the station?"}},{"title":"Transport","icon":"🚌","tip":"Use \"tomar\" for taking transport: tomo el autobús. \"Llegar tarde\" = to be late (literally arrive late).","v":[["autobús","bus","🚌"],["tren","train","🚆"],["billete","ticket","🎫"],["estación","station","🚉"],["aeropuerto","airport","✈️"]],"s":[["Tomo el autobús al trabajo","I take the bus to work"],["Un billete, por favor","One ticket, please"],["El tren llega tarde","The train is late","Spanish says \"arrives late\" (llega tarde), not \"is late\"."],["¿Cuándo sale el tren?","When does the train leave?","\"Salir\" (to leave) becomes \"sale\" for él / ella / it."]],"fill":{"before":"Un","after":", por favor.","opts":["billete","casa","agua"],"ans":0,"tr":"One ticket, please."},"dlg":{"lines":["¿Adónde quieres ir?"],"opts":["Quiero ir al aeropuerto.","Tengo diez años.","Ella bebe té."],"ans":0,"tr":"Where do you want to go?"}},{"title":"Weather","icon":"🌦️","tip":"For weather Spanish says \"hace\" + noun: hace calor (it makes heat), hace frío, hace viento. For rain use \"está lloviendo\".","v":[["calor","heat / hot","🥵"],["lluvia","rain","🌧️"],["frío","cold","🥶"],["sol","sun","☀️"],["viento","wind","💨"]],"s":[["Hace calor hoy","It is hot today","Spanish uses \"hace\" (it makes) for weather: hace calor, hace frío, hace sol."],["Está lloviendo","It is raining"],["Hace buen tiempo","The weather is nice"],["Me gusta la lluvia","I like the rain"]],"fill":{"before":"Hoy","after":" calor.","opts":["hace","es","está"],"ans":0,"tr":"It is hot today."},"dlg":{"lines":["¿Qué tiempo hace?"],"opts":["Hace calor.","Tengo dos libros.","Me llamo Ravi."],"ans":0,"tr":"How is the weather?"}},{"title":"Health","icon":"🩺","tip":"Pain uses \"doler\": me duele la cabeza (my head hurts). With plural body parts use \"duelen\": me duelen los pies.","v":[["médico","doctor","🩺"],["medicina","medicine","💊"],["fiebre","fever","🤒"],["cabeza","head"],["dolor","pain","😣"]],"s":[["Tengo fiebre","I have a fever"],["Necesito un médico","I need a doctor"],["Me duele la cabeza","My head hurts","\"Doler\" works like \"gustar\": me duele la cabeza = the head hurts me."],["Toma esta medicina","Take this medicine"]],"fill":{"before":"Me","after":" la cabeza.","opts":["duele","duelen","tengo"],"ans":0,"tr":"My head hurts.","note":"One head (singular) = duele. Several things = duelen."},"dlg":{"lines":["¿Cuál es el problema?"],"opts":["Tengo fiebre.","El tren llega tarde.","Es azul."],"ans":0,"tr":"What is the problem?"}},{"title":"Work","icon":"💼","tip":"Use \"ir a + infinitive\" for the future: voy a enviar un correo (I am going to send an email). Jobs: \"trabajo en ...\" = I work in ...","v":[["oficina","office","🏢"],["trabajo","job / work","💼"],["jefe","boss"],["reunión","meeting","🗓️"],["correo","email","📧"]],"s":[["Trabajo en una oficina","I work in an office"],["Tengo una reunión a las diez","I have a meeting at ten"],["Voy a enviar un correo","I will send an email","Use \"ir a\" + verb for the near future: voy a enviar = I am going to send."],["Mi jefe es muy amable","My boss is very kind"]],"fill":{"before":"Voy a","after":" un correo.","opts":["enviar","envío","envías"],"ans":0,"tr":"I will send an email.","note":"After \"voy a\" always use the infinitive (enviar)."},"dlg":{"lines":["¿En qué trabajas?"],"opts":["Trabajo en una oficina.","Hace mucho frío.","Gira a la derecha."],"ans":0,"tr":"Where do you work?"}}],"story":{"title":"Tarde para el autobús","cast":[{"id":"sam","name":"Samuel","emoji":"🧑"},{"id":"ana","name":"Ana","emoji":"👩"}],"parts":[["sam","Perdone, ¿dónde está la parada de autobús?","Excuse me, where is the bus stop?"],["ana","Sigue todo recto y gira a la izquierda. Está cerca de la estación.","Go straight and turn left. It is near the station."],["sam","¡Gracias! ¿El autobús llega tarde hoy?","Thanks! Is the bus late today?"],["ana","Sí. Está lloviendo y el autobús llega tarde.","Yes. It is raining and the bus is late."],["sam","Ay no. Tengo una reunión a las diez.","Oh no. I have a meeting at ten."],["ana","Entonces toma un taxi. ¡Suerte!","Then take a taxi. Good luck!"]],"questions":[{"after":1,"q":"Where is the bus stop?","opts":["Near the station","Far from the shop","In the kitchen"],"ans":0},{"after":4,"q":"Why is Samuel worried?","opts":["He has a meeting at ten","He has no money","He is sick"],"ans":0}]},"roleplays":["bus","hotel","interview"]}],"roleplays":[{"id":"es-for-en.rp.coffee","title":"Order coffee and snacks","emoji":"☕","level":"Beginner","setting":"You are at Café Esquina. Order a drink and something to eat.","persona":{"name":"Lucía","role":"Camarera","emoji":"👩‍🍳"},"goals":[{"id":"greet","text":"Greet politely"},{"id":"order","text":"Order a drink"},{"id":"price","text":"Ask the price"},{"id":"snack","text":"Order something to eat"},{"id":"confirm","text":"Confirm your order"}],"opener":{"text":"¡Hola! Bienvenido a Café Esquina. ¿Qué desea?","tr":"Hello! Welcome to Café Esquina. What would you like?"},"steps":[{"goal":"greet","keys":["hola","buenos dias","buenas tardes","buenas noches","buenas"],"reply":"¡Hola! ¿En qué puedo ayudarle?","tr":"Hello! How can I help you?","better":"Buenos días. ¿Me pone un café, por favor?"},{"goal":"order","keys":["cafe","un te","zumo","jugo","quiero","quisiera","me gustaria","deme","dame","pido"],"reply":"¡Muy bien! ¿Quiere algo de comer?","tr":"Very good! Would you like something to eat?","better":"Quiero un café, por favor."},{"goal":"price","keys":["cuanto","precio","cuesta","cuestan"],"reply":"El café cuesta tres euros y el bocadillo cuesta cuatro.","tr":"The coffee costs three euros and the sandwich costs four.","better":"¿Cuánto cuesta el café?"},{"goal":"snack","keys":["bocadillo","sandwich","pastel","tarta","galleta","magdalena","pan","comer"],"reply":"¡Buena elección! Son siete euros en total. ¿Es todo?","tr":"Good choice! That is seven euros in total. Is that all?","better":"Quiero también un bocadillo, por favor."},{"goal":"confirm","keys":["si","eso es todo","es todo","vale","claro","de acuerdo","perfecto","correcto"],"reply":"Aquí tiene. ¡Que aproveche!","tr":"Here you go. Enjoy your meal!","better":"Sí, es todo. Gracias."},{"keys":["gracias","adios","hasta luego","chao"],"reply":"¡De nada! Que tenga un buen día.","tr":"You are welcome! Have a nice day."}],"fallbacks":[{"text":"Perdone, no entiendo. ¿Puede repetir?","tr":"Sorry, I do not understand. Can you repeat?"},{"text":"Pruebe con: Quiero un café, por favor.","tr":"Try: I want a coffee, please."}],"hints":["¡Hola! Buenos días.","Quiero un café, por favor.","¿Cuánto cuesta el café?","Quiero un bocadillo.","Sí, es todo. Gracias."],"closing":{"text":"¡Gracias por venir! Hasta pronto.","tr":"Thanks for coming! See you soon."}},{"id":"es-for-en.rp.bus","title":"Ask for bus directions","emoji":"🚌","level":"Beginner","setting":"You are lost in town. Ask a local how to get to the bus stop.","persona":{"name":"Sr. Díaz","role":"Vecino","emoji":"🧑‍🦱"},"goals":[{"id":"attention","text":"Get attention politely"},{"id":"where","text":"Ask where the bus stop is"},{"id":"repeat","text":"Repeat the directions"},{"id":"far","text":"Ask if it is far"},{"id":"thanks","text":"Say thank you"}],"opener":{"text":"Hola. Parece perdido. ¿Puedo ayudarle?","tr":"Hello. You look lost. Can I help you?"},"steps":[{"goal":"attention","keys":["perdone","disculpe","hola","oiga","perdon"],"reply":"¿Sí? ¿En qué puedo ayudarle?","tr":"Yes? How can I help you?","better":"Perdone, ¿puede ayudarme?"},{"goal":"where","keys":["donde","parada","autobus","estacion","como llego","como puedo llegar"],"reply":"Siga todo recto y gire a la izquierda en la tienda. La parada está cerca de la estación.","tr":"Go straight and turn left at the shop. The stop is near the station.","better":"Perdone, ¿dónde está la parada de autobús?"},{"goal":"repeat","keys":["izquierda","derecha","recto","gire","giro","sigo","entonces"],"reply":"Sí, correcto. Siga recto y gire a la izquierda.","tr":"Yes, correct. Go straight and turn left.","better":"¿Entonces sigo recto y giro a la izquierda?"},{"goal":"far","keys":["lejos","cerca","minutos","cuanto tarda","cuanto tiempo"],"reply":"No, no está lejos. Son solo cinco minutos a pie.","tr":"No, it is not far. Only five minutes on foot.","better":"¿Está lejos de aquí?"},{"goal":"thanks","keys":["gracias"],"reply":"¡De nada! Buen viaje.","tr":"You are welcome! Have a good trip.","better":"Muchas gracias por su ayuda."}],"fallbacks":[{"text":"Perdone, ¿puede repetir más despacio?","tr":"Sorry, can you repeat more slowly?"},{"text":"Pregunte: ¿Dónde está la parada de autobús?","tr":"Ask: Where is the bus stop?"}],"hints":["Perdone, ¿puede ayudarme?","¿Dónde está la parada de autobús?","¿Sigo recto y giro a la izquierda?","¿Está lejos?","Muchas gracias."],"closing":{"text":"¡Suerte! Espero que llegue a tiempo.","tr":"Good luck! I hope you arrive on time."}},{"id":"es-for-en.rp.hotel","title":"Check into a hotel","emoji":"🏨","level":"Elementary","setting":"You arrive at Hotel Sol late in the evening. Check in.","persona":{"name":"Marta","role":"Recepcionista","emoji":"🧑‍💼"},"goals":[{"id":"greet","text":"Greet the receptionist"},{"id":"booking","text":"Say you have a booking"},{"id":"name","text":"Give your name"},{"id":"breakfast","text":"Ask about breakfast"},{"id":"key","text":"Ask for the key or Wi-Fi"}],"opener":{"text":"¡Buenas noches! Bienvenido al Hotel Sol.","tr":"Good evening! Welcome to Hotel Sol."},"steps":[{"goal":"greet","keys":["hola","buenas noches","buenas tardes","buenos dias","buenas"],"reply":"¡Hola! ¿Tiene una reserva?","tr":"Hello! Do you have a reservation?","better":"Buenas noches. Tengo una reserva."},{"goal":"booking","keys":["reserva","reservado","reservada","tengo una habitacion","he reservado"],"reply":"Perfecto. ¿Me dice su nombre, por favor?","tr":"Perfect. Can you tell me your name, please?","better":"Sí, tengo una reserva para esta noche."},{"goal":"name","keys":["me llamo","mi nombre","soy","nombre"],"reply":"Gracias. Su habitación es la 204, en el segundo piso.","tr":"Thank you. Your room is 204, on the second floor.","better":"Me llamo Ravi Kumar."},{"goal":"breakfast","keys":["desayuno","desayunar"],"reply":"El desayuno es de siete a diez en el restaurante.","tr":"Breakfast is from seven to ten in the restaurant.","better":"¿A qué hora es el desayuno?"},{"goal":"key","keys":["llave","wifi","wi fi","contrasena","clave","tarjeta","internet"],"reply":"Aquí tiene su tarjeta. La contraseña del wifi está en la tarjeta.","tr":"Here is your card. The wifi password is on the card.","better":"¿Me da la llave, por favor?"},{"keys":["gracias","adios","hasta manana"],"reply":"De nada. ¡Que disfrute de su estancia!","tr":"You are welcome. Enjoy your stay!"}],"fallbacks":[{"text":"Perdone, ¿puede repetir?","tr":"Sorry, can you repeat?"},{"text":"Pruebe: Tengo una reserva. Me llamo ...","tr":"Try: I have a reservation. My name is ..."}],"hints":["Buenas noches.","Tengo una reserva.","Me llamo Ravi Kumar.","¿A qué hora es el desayuno?","¿Me da la llave, por favor?"],"closing":{"text":"¡Que descanse!","tr":"Rest well!"}},{"id":"es-for-en.rp.doctor","title":"Visit a doctor","emoji":"🩺","level":"Elementary","setting":"You feel sick. Tell the doctor what is wrong.","persona":{"name":"Dra. Vega","role":"Médica","emoji":"🧑‍⚕️"},"goals":[{"id":"greet","text":"Greet the doctor"},{"id":"problem","text":"Say what hurts"},{"id":"duration","text":"Say how long"},{"id":"medicine","text":"Ask about medicine"},{"id":"thanks","text":"Thank the doctor"}],"opener":{"text":"Hola. Siéntese, por favor. ¿Cuál es el problema?","tr":"Hello. Sit down, please. What is the problem?"},"steps":[{"goal":"greet","keys":["hola","buenos dias","buenas tardes","buenas"],"reply":"Dígame qué le pasa.","tr":"Tell me what is wrong.","better":"Buenos días, doctora."},{"goal":"problem","keys":["fiebre","dolor","duele","cabeza","tos","estomago","garganta","enfermo","enferma","mal"],"reply":"Lo siento. ¿Desde cuándo lo tiene?","tr":"I am sorry. Since when do you have it?","better":"Tengo fiebre y me duele la cabeza."},{"goal":"duration","keys":["dias","dia","desde","ayer","semana","horas","hace"],"reply":"Entiendo. Necesita descansar y beber mucha agua. Le doy una medicina.","tr":"I understand. You need to rest and drink a lot of water. I will give you medicine.","better":"Estoy enfermo desde hace dos días."},{"goal":"medicine","keys":["medicina","pastilla","pastillas","tomar","cuantas","medicamento"],"reply":"Tome una pastilla por la mañana y otra por la noche. Beba mucha agua.","tr":"Take one pill in the morning and one at night. Drink lots of water.","better":"¿Cómo tomo la medicina?"},{"goal":"thanks","keys":["gracias","adios"],"reply":"¡Cuídese! Vuelva si no mejora.","tr":"Take care! Come back if you do not get better.","better":"Muchas gracias, doctora."}],"fallbacks":[{"text":"Perdone, no le he entendido. ¿Dónde le duele?","tr":"Sorry, I did not understand. Where does it hurt?"},{"text":"Pruebe: Tengo fiebre. Me duele la cabeza.","tr":"Try: I have a fever. My head hurts."}],"hints":["Buenos días, doctora.","Tengo fiebre y me duele la cabeza.","Desde hace dos días.","¿Cómo tomo la medicina?","Muchas gracias, doctora."],"closing":{"text":"¡Que se mejore pronto!","tr":"Get well soon!"}},{"id":"es-for-en.rp.interview","title":"Job interview intro","emoji":"💼","level":"Intermediate","setting":"You are at an interview for a shop assistant job.","persona":{"name":"Sra. Ríos","role":"Entrevistadora","emoji":"👩‍💼"},"goals":[{"id":"greet","text":"Greet the interviewer"},{"id":"intro","text":"Introduce yourself"},{"id":"skills","text":"Say what you can do"},{"id":"why","text":"Say why you want the job"},{"id":"thanks","text":"Thank the interviewer"}],"opener":{"text":"Buenos días. Siéntese, por favor. Hábleme de usted.","tr":"Good morning. Sit down, please. Tell me about yourself."},"steps":[{"goal":"greet","keys":["hola","buenos dias","buenas tardes","encantado","encantada","mucho gusto"],"reply":"Mucho gusto. ¿Cómo se llama?","tr":"Nice to meet you. What is your name?","better":"Buenos días. Gracias por recibirme."},{"goal":"intro","keys":["me llamo","soy","mi nombre","anos","vivo","tengo"],"reply":"Gracias. ¿Qué sabe hacer? ¿Cuáles son sus habilidades?","tr":"Thank you. What can you do? What are your skills?","better":"Me llamo Ravi. Tengo veinticinco años."},{"goal":"skills","keys":["puedo","hablo","experiencia","trabajo","trabaje","habilidad","bueno en","buena en","se hacer","se usar","aprendo","ayudar"],"reply":"Muy bien. ¿Por qué quiere este trabajo?","tr":"Very good. Why do you want this job?","better":"Hablo inglés y tamil. Soy bueno con los clientes."},{"goal":"why","keys":["porque","me gusta","necesito","aprender","equipo","interesa","interesado","quiero este"],"reply":"Excelente. Gracias por venir. Le llamaremos pronto.","tr":"Excellent. Thanks for coming. We will call you soon.","better":"Quiero este trabajo porque me gusta ayudar a la gente."},{"goal":"thanks","keys":["gracias","adios","hasta luego"],"reply":"De nada. ¡Adiós!","tr":"You are welcome. Goodbye!","better":"Gracias por su tiempo."}],"fallbacks":[{"text":"¿Puede contarme un poco más?","tr":"Can you tell me a bit more?"},{"text":"Pruebe: Me llamo ... Puedo ...","tr":"Try: My name is ... I can ..."}],"hints":["Buenos días. Gracias por recibirme.","Me llamo Ravi.","Hablo inglés y tamil.","Quiero este trabajo porque me gusta ayudar.","Gracias por su tiempo."],"closing":{"text":"¡Mucha suerte con todo!","tr":"Good luck with everything!"}}],"tutor":{"openers":[{"t":"¡Hola! Soy Maya, tu profesora de español. ¿Cómo estás hoy?","n":"Hello! I am Maya, your Spanish teacher. How are you today?"}],"topics":[{"keys":["adios","hasta luego","chao","hasta manana","buenas noches"],"replies":[{"t":"¡Adiós! Hablas muy bien. ¡Hasta pronto!","n":"Goodbye! You speak very well. See you soon!"}]},{"keys":["hola","buenos dias","buenas tardes","buenas"],"replies":[{"t":"¡Hola! Me alegra hablar contigo. ¿Cómo estás hoy?","n":"Hello! I am happy to talk with you. How are you today?"}]},{"keys":["me llamo","mi nombre","soy"],"replies":[{"t":"¡Mucho gusto! ¿De dónde eres?","n":"Nice to meet you! Where are you from?"}]},{"keys":["bien","mal","cansado","cansada","contento","contenta","feliz","triste","regular","estoy"],"replies":[{"t":"¡Me alegro! ¿Qué hiciste hoy?","n":"I am glad! What did you do today?"},{"t":"Entiendo. Cuéntame más sobre tu día.","n":"I see. Tell me more about your day."}]},{"keys":["vivo","ciudad","pueblo","india","estados unidos","londres","vengo","pais"],"replies":[{"t":"¡Qué interesante! Háblame de tu familia.","n":"How interesting! Tell me about your family."}]},{"keys":["madre","padre","hermano","hermana","familia","padres","esposa","esposo","hijo","hija"],"replies":[{"t":"La familia es importante. ¿A qué se dedican?","n":"Family is important. What do they do?"},{"t":"¡Qué bonito! ¿Viven cerca de ti?","n":"How nice! Do they live near you?"}]},{"keys":["trabajo","oficina","estudiante","estudio","profesor","ingeniero","escuela","universidad","empresa"],"replies":[{"t":"¡Qué interesante! ¿Te gusta?","n":"How interesting! Do you like it?"},{"t":"¿Cuál es la mejor parte de tu día?","n":"What is the best part of your day?"}]},{"keys":["comida","como","arroz","cena","almuerzo","desayuno","hambre","bebo","cafe","pizza","tacos"],"replies":[{"t":"¡Qué rico! ¿Cuál es tu comida favorita?","n":"Yum! What is your favorite food?"},{"t":"¿Sabes cocinar? ¿Qué cocinas?","n":"Can you cook? What do you cook?"}]},{"keys":["me gusta","me encanta","musica","pelicula","peliculas","futbol","deporte","leer","bailar","juego","jugar"],"replies":[{"t":"¡Qué bien! ¿Con qué frecuencia lo haces?","n":"Nice! How often do you do it?"},{"t":"Suena divertido. ¿Con quién lo haces?","n":"Sounds fun. Who do you do it with?"}]},{"keys":["tiempo","calor","lluvia","frio","sol","verano","invierno","llueve"],"replies":[{"t":"El tiempo cambia rápido. ¿Te gusta la lluvia?","n":"The weather changes fast. Do you like the rain?"}]}],"fallbacks":[{"t":"Qué interesante. ¿Puedes contarme más?","n":"How interesting. Can you tell me more?"},{"t":"¿Puedes decirlo de otra manera?","n":"Can you say it another way?"},{"t":"Quiero saber más. ¿Qué piensas?","n":"I want to know more. What do you think?"}],"fixes":[{"re":"\\byo es\\b","hint":"With \"yo\" use \"soy\", not \"es\".","better":"Yo soy ..."},{"re":"\\bme llamo es\\b","hint":"Say \"Me llamo Ravi\" with no \"es\".","better":"Me llamo Ravi."},{"re":"\\b(yo )?(soy|es) (bien|mal|cansado|cansada|enfermo|enferma|feliz|triste)\\b","hint":"Feelings use \"estar\": estoy bien, estoy cansado.","better":"Estoy bien / Estoy cansado."},{"re":"\\byo (tiene|tienes|tenemos)\\b","hint":"With \"yo\" use \"tengo\".","better":"Yo tengo ..."},{"re":"\\bun (casa|mesa|silla|leche|manzana|familia|hermana|madre)\\b","hint":"This noun is feminine, so use \"una\".","better":"una casa / una mesa ..."},{"re":"\\buna (libro|amigo|hermano|padre|pan|arroz|vaso)\\b","hint":"This noun is masculine, so use \"un\".","better":"un libro / un amigo ..."},{"re":"\\bgusto (el|la|los|las)\\b","hint":"Say \"me gusta\" first: Me gusta el café.","better":"Me gusta el café."},{"re":"\\bsoy (\\d+|diez|veinte|treinta) anos?\\b","hint":"Age uses \"tener\": tengo diez años.","better":"Tengo diez años."},{"re":"\\bhay (muy|mucho) (calor|frio)\\b","hint":"Weather uses \"hace\": hace mucho calor.","better":"Hace mucho calor."}],"closers":[{"t":"¡Muy bien! Sigue practicando. ¡Adiós!","n":"Very good! Keep practicing. Goodbye!"}]}}$json$::jsonb, true) on conflict (id) do update set title = excluded.title, spec = excluded.spec, published = true;
insert into public.units (id, course_id, position, title, content) values ('en-for-ta.u1', 'en-for-ta', 1, 'Hello, English!', $json${"subtitle":"Greetings, names, family, numbers, colors","section":"Section 1: Getting Started","guidebook":{"intro":"Start with the words you use every day. Tamil and English work differently, so each tip shows the gap and how to close it.","tips":[{"title":"Greetings change with the time of day","body":"Tamil வணக்கம் works all day. English has a different greeting for each part of the day. Good morning is used until about noon.","examples":[{"t":"Good morning","n":"காலை வணக்கம்"},{"t":"Good night","n":"இனிய இரவு"}]},{"title":"Never skip am / is / are","body":"Tamil sentences like நான் ரவி have no word for \"am\". English always needs one. I am, you are, he/she/it is.","examples":[{"t":"I am Ravi","n":"நான் ரவி"},{"t":"She is a teacher","n":"அவள் ஒரு ஆசிரியர்"}]},{"title":"Add -s for more than one","body":"When you talk about two or more things, add -s to the noun. Tamil adds கள் instead.","examples":[{"t":"one book","n":"ஒரு புத்தகம்"},{"t":"two books","n":"இரண்டு புத்தகங்கள்"}]}]},"roleplayIds":["en-for-ta.rp.coffee","en-for-ta.rp.doctor"]}$json$::jsonb) on conflict (id) do update set title = excluded.title, content = excluded.content;
insert into public.lessons (id, unit_id, position, kind, title, content) values ('en-for-ta.u1.l1', 'en-for-ta.u1', 1, 'lesson', 'Greetings', $json${"vocab":[{"t":"Hello","n":"வணக்கம்","e":"👋"},{"t":"Good morning","n":"காலை வணக்கம்","e":"🌅"},{"t":"Good night","n":"இனிய இரவு","e":"🌙"},{"t":"Thank you","n":"நன்றி","e":"🙏"},{"t":"Please","n":"தயவுசெய்து"}],"exercises":[{"id":"en-for-ta.u1.l1.e1","type":"MULTIPLE_CHOICE","prompt":"What does “Hello” mean?","speak":"Hello","options":[{"text":"வணக்கம்"},{"text":"கூட்டம்"},{"text":"சாப்பிடு"},{"text":"ஐந்து"}],"correct":0,"focus":["Hello"],"explain":"“Hello” = “வணக்கம்”. English has a different greeting for each time of day: Good morning (until noon), Good afternoon, Good evening, and Good night (when you leave or go to bed). Tamil வணக்கம் works all day."},{"id":"en-for-ta.u1.l1.e2","type":"MATCH_PAIRS","pairs":[{"l":"Hello","r":"வணக்கம்"},{"l":"Good morning","r":"காலை வணக்கம்"},{"l":"Good night","r":"இனிய இரவு"},{"l":"Thank you","r":"நன்றி"},{"l":"Please","r":"தயவுசெய்து"}],"focus":["Hello","Good morning","Good night","Thank you","Please"],"explain":"Match each word with its meaning. Tap a word, then tap its partner."},{"id":"en-for-ta.u1.l1.e3","type":"MULTIPLE_CHOICE","prompt":"Which one is “வணக்கம்”?","options":[{"text":"green","emoji":"🟢"},{"text":"eat","emoji":"🍽️"},{"text":"left","emoji":"⬅️"},{"text":"Hello","emoji":"👋"}],"correct":3,"focus":["Hello"],"explain":"“Hello” means “வணக்கம்” 👋. English has a different greeting for each time of day: Good morning (until noon), Good afternoon, Good evening, and Good night (when you leave or go to bed). Tamil வணக்கம் works all day."},{"id":"en-for-ta.u1.l1.e4","type":"WORD_BANK","prompt":"வணக்கம், நீங்கள் எப்படி இருக்கிறீர்கள்?","dir":"toTarget","answer":"Hello how are you","bank":["how","this","you","Hello","are","ten","years"],"accept":[],"focus":["Hello"],"explain":"\"How are you?\" is the normal way to start a chat. Answer with \"I am fine.\""},{"id":"en-for-ta.u1.l1.e5","type":"LISTENING_TAP","audio":"I am fine thank you","answer":"I am fine thank you","bank":["five","thank","fine","you","I","am","brother","a"],"translation":"நான் நலமாக இருக்கிறேன், நன்றி","accept":["I'm fine thank you"],"focus":["Thank you"],"explain":"English has a different greeting for each time of day: Good morning (until noon), Good afternoon, Good evening, and Good night (when you leave or go to bed). Tamil வணக்கம் works all day."},{"id":"en-for-ta.u1.l1.e6","type":"MULTIPLE_CHOICE","prompt":"How do you say “காலை வணக்கம்” in English?","options":[{"text":"expensive"},{"text":"Good morning"},{"text":"station"},{"text":"cold"}],"correct":1,"focus":["Good morning"],"explain":"“காலை வணக்கம்” in English is “Good morning”."},{"id":"en-for-ta.u1.l1.e7","type":"TYPE_TRANSLATION","prompt":"காலை வணக்கம், ஆசிரியரே","dir":"toTarget","answer":"Good morning teacher","accept":[],"focus":["Good morning"],"explain":"English has a different greeting for each time of day: Good morning (until noon), Good afternoon, Good evening, and Good night (when you leave or go to bed). Tamil வணக்கம் works all day."},{"id":"en-for-ta.u1.l1.e8","type":"FILL_BLANK","before":"Good","after":", teacher!","options":["morning","night","evening"],"correct":0,"translation":"காலை வணக்கம், ஆசிரியரே!","explain":"English has a different greeting for each time of day: Good morning (until noon), Good afternoon, Good evening, and Good night (when you leave or go to bed). Tamil வணக்கம் works all day."},{"id":"en-for-ta.u1.l1.e9","type":"SPEAKING_REPEAT","phrase":"Hello how are you","translation":"வணக்கம், நீங்கள் எப்படி இருக்கிறீர்கள்?","focus":["Hello"],"explain":"Say it slowly first, then at normal speed. \"How are you?\" is the normal way to start a chat. Answer with \"I am fine.\""},{"id":"en-for-ta.u1.l1.e10","type":"DIALOGUE_COMPLETE","lines":[{"who":"A","text":"Hello, how are you?"}],"options":["I am fine, thank you.","Good night.","Please sit down."],"correct":0,"translation":"வணக்கம், நீங்கள் எப்படி இருக்கிறீர்கள்?","explain":"English has a different greeting for each time of day: Good morning (until noon), Good afternoon, Good evening, and Good night (when you leave or go to bed). Tamil வணக்கம் works all day."},{"id":"en-for-ta.u1.l1.e11","type":"WORD_BANK","prompt":"Please sit down","dir":"toNative","answer":"தயவுசெய்து உட்காருங்கள்","bank":["ஆப்பிள்","தயவுசெய்து","உட்காருங்கள்","மகிழ்ச்சி"],"focus":["Please"],"explain":"English has a different greeting for each time of day: Good morning (until noon), Good afternoon, Good evening, and Good night (when you leave or go to bed). Tamil வணக்கம் works all day."}]}$json$::jsonb) on conflict (id) do update set title = excluded.title, content = excluded.content;
insert into public.lessons (id, unit_id, position, kind, title, content) values ('en-for-ta.u1.l2', 'en-for-ta.u1', 2, 'lesson', 'Introductions', $json${"vocab":[{"t":"I","n":"நான்"},{"t":"you","n":"நீ / நீங்கள்"},{"t":"name","n":"பெயர்","e":"🏷️"},{"t":"friend","n":"நண்பன்","e":"🧑‍🤝‍🧑"},{"t":"teacher","n":"ஆசிரியர்","e":"👩‍🏫"}],"exercises":[{"id":"en-for-ta.u1.l2.e1","type":"MULTIPLE_CHOICE","prompt":"What does “I” mean?","speak":"I","options":[{"text":"பெயர்"},{"text":"அப்பா"},{"text":"வலது"},{"text":"நான்"}],"correct":3,"focus":["I"],"explain":"“I” = “நான்”. Tamil often leaves out \"am / is / are\". English never does: \"I am Ravi\", \"She is a teacher\"."},{"id":"en-for-ta.u1.l2.e2","type":"MATCH_PAIRS","pairs":[{"l":"I","r":"நான்"},{"l":"you","r":"நீ / நீங்கள்"},{"l":"name","r":"பெயர்"},{"l":"friend","r":"நண்பன்"},{"l":"teacher","r":"ஆசிரியர்"}],"focus":["I","you","name","friend","teacher"],"explain":"Match each word with its meaning. Tap a word, then tap its partner."},{"id":"en-for-ta.u1.l2.e3","type":"MULTIPLE_CHOICE","prompt":"Which one is “பெயர்”?","options":[{"text":"sun","emoji":"☀️"},{"text":"father","emoji":"👨"},{"text":"Good morning","emoji":"🌅"},{"text":"name","emoji":"🏷️"}],"correct":3,"focus":["name"],"explain":"“name” means “பெயர்” 🏷️. Tamil often leaves out \"am / is / are\". English never does: \"I am Ravi\", \"She is a teacher\"."},{"id":"en-for-ta.u1.l2.e4","type":"WORD_BANK","prompt":"என் பெயர் ரவி","dir":"toTarget","answer":"My name is Ravi","bank":["sister","name","am","is","My","fine","Ravi"],"accept":[],"focus":["name"],"explain":"Tamil says என் பெயர் ரவி with no word for \"is\". English needs it: My name is Ravi."},{"id":"en-for-ta.u1.l2.e5","type":"LISTENING_TAP","audio":"What is your name","answer":"What is your name","bank":["apples","name","books","is","What","your","teacher"],"translation":"உங்கள் பெயர் என்ன?","accept":["What's your name"],"focus":["name"],"explain":"Tamil often leaves out \"am / is / are\". English never does: \"I am Ravi\", \"She is a teacher\"."},{"id":"en-for-ta.u1.l2.e6","type":"MULTIPLE_CHOICE","prompt":"How do you say “நீ / நீங்கள்” in English?","options":[{"text":"today"},{"text":"kitchen"},{"text":"email"},{"text":"you"}],"correct":3,"focus":["you"],"explain":"“நீ / நீங்கள்” in English is “you”."},{"id":"en-for-ta.u1.l2.e7","type":"TYPE_TRANSLATION","prompt":"உங்களை சந்தித்ததில் மகிழ்ச்சி","dir":"toTarget","answer":"Nice to meet you","accept":[],"focus":["you"],"explain":"Tamil often leaves out \"am / is / are\". English never does: \"I am Ravi\", \"She is a teacher\"."},{"id":"en-for-ta.u1.l2.e8","type":"FILL_BLANK","before":"I","after":" Ravi.","options":["am","is","are"],"correct":0,"translation":"நான் ரவி.","explain":"Use \"am\" only with \"I\"."},{"id":"en-for-ta.u1.l2.e9","type":"SPEAKING_REPEAT","phrase":"My name is Ravi","translation":"என் பெயர் ரவி","focus":["name"],"explain":"Say it slowly first, then at normal speed. Tamil says என் பெயர் ரவி with no word for \"is\". English needs it: My name is Ravi."},{"id":"en-for-ta.u1.l2.e10","type":"DIALOGUE_COMPLETE","lines":[{"who":"A","text":"What is your name?"}],"options":["My name is Ravi.","I am fine.","Good night."],"correct":0,"translation":"உங்கள் பெயர் என்ன?","explain":"Tamil often leaves out \"am / is / are\". English never does: \"I am Ravi\", \"She is a teacher\"."},{"id":"en-for-ta.u1.l2.e11","type":"WORD_BANK","prompt":"He is my friend","dir":"toNative","answer":"அவன் என் நண்பன்","bank":["அவன்","பேர்","நண்பன்","பெயர்","என்"],"focus":["friend"],"explain":"Tamil often leaves out \"am / is / are\". English never does: \"I am Ravi\", \"She is a teacher\"."}]}$json$::jsonb) on conflict (id) do update set title = excluded.title, content = excluded.content;
insert into public.lessons (id, unit_id, position, kind, title, content) values ('en-for-ta.u1.l3', 'en-for-ta.u1', 3, 'lesson', 'Family', $json${"vocab":[{"t":"mother","n":"அம்மா","e":"👩"},{"t":"father","n":"அப்பா","e":"👨"},{"t":"brother","n":"சகோதரன்","e":"👦"},{"t":"sister","n":"சகோதரி","e":"👧"},{"t":"family","n":"குடும்பம்","e":"👨‍👩‍👧‍👦"}],"exercises":[{"id":"en-for-ta.u1.l3.e1","type":"MULTIPLE_CHOICE","prompt":"What does “mother” mean?","speak":"mother","options":[{"text":"இரண்டு"},{"text":"காற்று"},{"text":"சிவப்பு"},{"text":"அம்மா"}],"correct":3,"focus":["mother"],"explain":"“mother” = “அம்மா”. \"A\" has no exact Tamil word (ஒரு is close). Use \"a\" before one thing: a brother, a doctor. Use \"an\" before a vowel sound: an apple."},{"id":"en-for-ta.u1.l3.e2","type":"MATCH_PAIRS","pairs":[{"l":"mother","r":"அம்மா"},{"l":"father","r":"அப்பா"},{"l":"brother","r":"சகோதரன்"},{"l":"sister","r":"சகோதரி"},{"l":"family","r":"குடும்பம்"}],"focus":["mother","father","brother","sister","family"],"explain":"Match each word with its meaning. Tap a word, then tap its partner."},{"id":"en-for-ta.u1.l3.e3","type":"MULTIPLE_CHOICE","prompt":"Which one is “அம்மா”?","options":[{"text":"brother","emoji":"👦"},{"text":"mother","emoji":"👩"},{"text":"hot","emoji":"🥵"},{"text":"three","emoji":"3️⃣"}],"correct":1,"focus":["mother"],"explain":"“mother” means “அம்மா” 👩. \"A\" has no exact Tamil word (ஒரு is close). Use \"a\" before one thing: a brother, a doctor. Use \"an\" before a vowel sound: an apple."},{"id":"en-for-ta.u1.l3.e4","type":"WORD_BANK","prompt":"இது என் அம்மா","dir":"toTarget","answer":"This is my mother","bank":["apples","down","is","my","This","mother","how"],"accept":[],"focus":["mother"],"explain":"\"A\" has no exact Tamil word (ஒரு is close). Use \"a\" before one thing: a brother, a doctor. Use \"an\" before a vowel sound: an apple."},{"id":"en-for-ta.u1.l3.e5","type":"LISTENING_TAP","audio":"I have a brother","answer":"I have a brother","bank":["mother","to","have","I","a","bag","brother"],"translation":"எனக்கு ஒரு சகோதரன் இருக்கிறான்","accept":[],"focus":["brother"],"explain":"Use \"a\" before one singular thing: a brother, a sister. Tamil uses ஒரு."},{"id":"en-for-ta.u1.l3.e6","type":"MULTIPLE_CHOICE","prompt":"How do you say “அப்பா” in English?","options":[{"text":"buy"},{"text":"father"},{"text":"green"},{"text":"email"}],"correct":1,"focus":["father"],"explain":"“அப்பா” in English is “father”."},{"id":"en-for-ta.u1.l3.e7","type":"TYPE_TRANSLATION","prompt":"என் அப்பா ஒரு மருத்துவர்","dir":"toTarget","answer":"My father is a doctor","accept":[],"focus":["father"],"explain":"Jobs need \"a\": He is a doctor. Not \"He is doctor.\""},{"id":"en-for-ta.u1.l3.e8","type":"FILL_BLANK","before":"She is my","after":".","options":["sister","brother","father"],"correct":0,"translation":"அவள் என் சகோதரி.","explain":"\"She\" is a girl, so the family word is a girl too: sister."},{"id":"en-for-ta.u1.l3.e9","type":"SPEAKING_REPEAT","phrase":"This is my mother","translation":"இது என் அம்மா","focus":["mother"],"explain":"Say it slowly first, then at normal speed. \"A\" has no exact Tamil word (ஒரு is close). Use \"a\" before one thing: a brother, a doctor. Use \"an\" before a vowel sound: an apple."},{"id":"en-for-ta.u1.l3.e10","type":"DIALOGUE_COMPLETE","lines":[{"who":"A","text":"Who is she?"}],"options":["She is my sister.","He is my brother.","I am fine."],"correct":0,"translation":"அவள் யார்?","explain":"\"A\" has no exact Tamil word (ஒரு is close). Use \"a\" before one thing: a brother, a doctor. Use \"an\" before a vowel sound: an apple."},{"id":"en-for-ta.u1.l3.e11","type":"WORD_BANK","prompt":"She is my sister","dir":"toNative","answer":"அவள் என் சகோதரி","bank":["சகோதரி","அவள்","ஆப்பிள்","என்","இருக்கிறீர்கள்"],"focus":["sister"],"explain":"\"A\" has no exact Tamil word (ஒரு is close). Use \"a\" before one thing: a brother, a doctor. Use \"an\" before a vowel sound: an apple."}]}$json$::jsonb) on conflict (id) do update set title = excluded.title, content = excluded.content;
insert into public.lessons (id, unit_id, position, kind, title, content) values ('en-for-ta.u1.l4', 'en-for-ta.u1', 4, 'lesson', 'Numbers 1 to 5', $json${"vocab":[{"t":"one","n":"ஒன்று","e":"1️⃣"},{"t":"two","n":"இரண்டு","e":"2️⃣"},{"t":"three","n":"மூன்று","e":"3️⃣"},{"t":"four","n":"நான்கு","e":"4️⃣"},{"t":"five","n":"ஐந்து","e":"5️⃣"}],"exercises":[{"id":"en-for-ta.u1.l4.e1","type":"MULTIPLE_CHOICE","prompt":"What does “one” mean?","speak":"one","options":[{"text":"ஒன்று"},{"text":"காய்ச்சல்"},{"text":"காலை"},{"text":"விலை அதிகம்"}],"correct":0,"focus":["one"],"explain":"“one” = “ஒன்று”. Add -s to make a noun plural after any number bigger than one: one book, two books."},{"id":"en-for-ta.u1.l4.e2","type":"MATCH_PAIRS","pairs":[{"l":"one","r":"ஒன்று"},{"l":"two","r":"இரண்டு"},{"l":"three","r":"மூன்று"},{"l":"four","r":"நான்கு"},{"l":"five","r":"ஐந்து"}],"focus":["one","two","three","four","five"],"explain":"Match each word with its meaning. Tap a word, then tap its partner."},{"id":"en-for-ta.u1.l4.e3","type":"MULTIPLE_CHOICE","prompt":"Which one is “ஒன்று”?","options":[{"text":"one","emoji":"1️⃣"},{"text":"ticket","emoji":"🎫"},{"text":"friend","emoji":"🧑‍🤝‍🧑"},{"text":"sister","emoji":"👧"}],"correct":0,"focus":["one"],"explain":"“one” means “ஒன்று” 1️⃣. Add -s to make a noun plural after any number bigger than one: one book, two books."},{"id":"en-for-ta.u1.l4.e4","type":"WORD_BANK","prompt":"என்னிடம் இரண்டு புத்தகங்கள் உள்ளன","dir":"toTarget","answer":"I have two books","bank":["how","two","ravi","what","have","books","I"],"accept":[],"focus":["two"],"explain":"After two, three, four... the noun takes -s: two books."},{"id":"en-for-ta.u1.l4.e5","type":"LISTENING_TAP","audio":"There are five people","answer":"There are five people","bank":["are","There","am","like","people","friend","five"],"translation":"ஐந்து பேர் இருக்கிறார்கள்","accept":[],"focus":["five"],"explain":"Add -s to make a noun plural after any number bigger than one: one book, two books."},{"id":"en-for-ta.u1.l4.e6","type":"MULTIPLE_CHOICE","prompt":"How do you say “இரண்டு” in English?","options":[{"text":"go"},{"text":"two"},{"text":"name"},{"text":"chair"}],"correct":1,"focus":["two"],"explain":"“இரண்டு” in English is “two”."},{"id":"en-for-ta.u1.l4.e7","type":"TYPE_TRANSLATION","prompt":"எனக்கு பத்து வயது","dir":"toTarget","answer":"I am ten years old","accept":["I'm ten years old"],"focus":[],"explain":"English says \"I am ten years old\". Tamil says \"to me ten age\"."},{"id":"en-for-ta.u1.l4.e8","type":"FILL_BLANK","before":"I have two","after":".","options":["book","books","a book"],"correct":1,"translation":"என்னிடம் இரண்டு புத்தகங்கள் உள்ளன.","explain":"Add -s to make a noun plural after any number bigger than one: one book, two books."},{"id":"en-for-ta.u1.l4.e9","type":"SPEAKING_REPEAT","phrase":"I have two books","translation":"என்னிடம் இரண்டு புத்தகங்கள் உள்ளன","focus":["two"],"explain":"Say it slowly first, then at normal speed. After two, three, four... the noun takes -s: two books."},{"id":"en-for-ta.u1.l4.e10","type":"DIALOGUE_COMPLETE","lines":[{"who":"A","text":"How many books do you have?"}],"options":["I have two books.","I am fine.","My name is Ravi."],"correct":0,"translation":"உங்களிடம் எத்தனை புத்தகங்கள் உள்ளன?","explain":"Add -s to make a noun plural after any number bigger than one: one book, two books."},{"id":"en-for-ta.u1.l4.e11","type":"WORD_BANK","prompt":"Three apples, please","dir":"toNative","answer":"மூன்று ஆப்பிள்கள் தயவுசெய்து","bank":["தயவுசெய்து","மூன்று","உள்ளன","இருக்கிறான்","ஆப்பிள்கள்"],"focus":["three"],"explain":"Add -s to make a noun plural after any number bigger than one: one book, two books."}]}$json$::jsonb) on conflict (id) do update set title = excluded.title, content = excluded.content;
insert into public.lessons (id, unit_id, position, kind, title, content) values ('en-for-ta.u1.l5', 'en-for-ta.u1', 5, 'lesson', 'Colors', $json${"vocab":[{"t":"red","n":"சிவப்பு","e":"🔴"},{"t":"blue","n":"நீலம்","e":"🔵"},{"t":"green","n":"பச்சை","e":"🟢"},{"t":"yellow","n":"மஞ்சள்","e":"🟡"},{"t":"black","n":"கருப்பு","e":"⚫"}],"exercises":[{"id":"en-for-ta.u1.l5.e1","type":"MULTIPLE_CHOICE","prompt":"What does “red” mean?","speak":"red","options":[{"text":"சிவப்பு"},{"text":"மேலாளர்"},{"text":"மலிவு"},{"text":"மின்னஞ்சல்"}],"correct":0,"focus":["red"],"explain":"“red” = “சிவப்பு”. Colors come before the noun: a red apple, a black bag. Tamil does the same, so this one is easy."},{"id":"en-for-ta.u1.l5.e2","type":"MATCH_PAIRS","pairs":[{"l":"red","r":"சிவப்பு"},{"l":"blue","r":"நீலம்"},{"l":"green","r":"பச்சை"},{"l":"yellow","r":"மஞ்சள்"},{"l":"black","r":"கருப்பு"}],"focus":["red","blue","green","yellow","black"],"explain":"Match each word with its meaning. Tap a word, then tap its partner."},{"id":"en-for-ta.u1.l5.e3","type":"MULTIPLE_CHOICE","prompt":"Which one is “சிவப்பு”?","options":[{"text":"red","emoji":"🔴"},{"text":"station","emoji":"🚉"},{"text":"fever","emoji":"🤒"},{"text":"sun","emoji":"☀️"}],"correct":0,"focus":["red"],"explain":"“red” means “சிவப்பு” 🔴. Colors come before the noun: a red apple, a black bag. Tamil does the same, so this one is easy."},{"id":"en-for-ta.u1.l5.e4","type":"WORD_BANK","prompt":"ஆப்பிள் சிவப்பு","dir":"toTarget","answer":"The apple is red","bank":["people","The","is","apple","my","good","red"],"accept":[],"focus":["red"],"explain":"Use \"the\" for a specific thing both people know about: the apple."},{"id":"en-for-ta.u1.l5.e5","type":"LISTENING_TAP","audio":"I like blue","answer":"I like blue","bank":["like","blue","I","red","books","nice"],"translation":"எனக்கு நீலம் பிடிக்கும்","accept":[],"focus":["blue"],"explain":"Colors come before the noun: a red apple, a black bag. Tamil does the same, so this one is easy."},{"id":"en-for-ta.u1.l5.e6","type":"MULTIPLE_CHOICE","prompt":"How do you say “நீலம்” in English?","options":[{"text":"hot"},{"text":"blue"},{"text":"station"},{"text":"cold"}],"correct":1,"focus":["blue"],"explain":"“நீலம்” in English is “blue”."},{"id":"en-for-ta.u1.l5.e7","type":"TYPE_TRANSLATION","prompt":"வானம் நீலம்","dir":"toTarget","answer":"The sky is blue","accept":[],"focus":["blue"],"explain":"Colors come before the noun: a red apple, a black bag. Tamil does the same, so this one is easy."},{"id":"en-for-ta.u1.l5.e8","type":"FILL_BLANK","before":"The sky is","after":".","options":["blue","red","black"],"correct":0,"translation":"வானம் நீலம்.","explain":"Colors come before the noun: a red apple, a black bag. Tamil does the same, so this one is easy."},{"id":"en-for-ta.u1.l5.e9","type":"SPEAKING_REPEAT","phrase":"The apple is red","translation":"ஆப்பிள் சிவப்பு","focus":["red"],"explain":"Say it slowly first, then at normal speed. Use \"the\" for a specific thing both people know about: the apple."},{"id":"en-for-ta.u1.l5.e10","type":"DIALOGUE_COMPLETE","lines":[{"who":"A","text":"What color is your bag?"}],"options":["My bag is black.","I have two books.","Good morning."],"correct":0,"translation":"உங்கள் பையின் நிறம் என்ன?","explain":"Colors come before the noun: a red apple, a black bag. Tamil does the same, so this one is easy."},{"id":"en-for-ta.u1.l5.e11","type":"WORD_BANK","prompt":"My bag is black","dir":"toNative","answer":"என் பை கருப்பு","bank":["மகிழ்ச்சி","ரவி","என்","பை","கருப்பு"],"focus":["black"],"explain":"Colors come before the noun: a red apple, a black bag. Tamil does the same, so this one is easy."}]}$json$::jsonb) on conflict (id) do update set title = excluded.title, content = excluded.content;
insert into public.lessons (id, unit_id, position, kind, title, content) values ('en-for-ta.u1.story', 'en-for-ta.u1', 6, 'story', 'Meeting a New Friend', $json${"vocab":[],"exercises":[{"id":"en-for-ta.u1.story.e1","type":"INTERACTIVE_STORY","title":"Meeting a New Friend","cast":[{"id":"raj","name":"Raj","emoji":"🧑"},{"id":"priya","name":"Priya","emoji":"👩"},{"id":"arun","name":"Arun","emoji":"👦"}],"parts":[{"who":"raj","text":"Hello! My name is Raj.","tr":"வணக்கம்! என் பெயர் ராஜ்."},{"who":"priya","text":"Hi Raj! I am Priya.","tr":"வணக்கம் ராஜ்! நான் பிரியா."},{"who":"raj","text":"Nice to meet you, Priya.","tr":"உங்களை சந்தித்ததில் மகிழ்ச்சி, பிரியா."},{"who":"priya","text":"Nice to meet you too. This is my brother, Arun.","tr":"எனக்கும் மகிழ்ச்சி. இது என் சகோதரன், அருண்."},{"who":"arun","text":"Hello! How are you?","tr":"வணக்கம்! நீங்கள் எப்படி இருக்கிறீர்கள்?"},{"who":"raj","text":"I am fine, thank you.","tr":"நான் நலமாக இருக்கிறேன், நன்றி."}],"questions":[{"after":1,"q":"What is the girl's name?","options":["Priya","Raj","Arun"],"correct":0},{"after":4,"q":"Who is Arun?","options":["Priya's brother","Raj's teacher","Priya's father"],"correct":0}],"explain":"Listen to the story, then answer the comprehension questions."}]}$json$::jsonb) on conflict (id) do update set title = excluded.title, content = excluded.content;
insert into public.lessons (id, unit_id, position, kind, title, content) values ('en-for-ta.u1.timed', 'en-for-ta.u1', 7, 'timed', 'Match Madness', $json${"vocab":[],"exercises":[{"id":"en-for-ta.u1.timed.e1","type":"TIMED_CHALLENGE","mode":"match_madness","seconds":90,"pairs":[{"l":"Hello","r":"வணக்கம்"},{"l":"Good morning","r":"காலை வணக்கம்"},{"l":"Good night","r":"இனிய இரவு"},{"l":"Thank you","r":"நன்றி"},{"l":"Please","r":"தயவுசெய்து"},{"l":"I","r":"நான்"},{"l":"you","r":"நீ / நீங்கள்"},{"l":"name","r":"பெயர்"},{"l":"friend","r":"நண்பன்"},{"l":"teacher","r":"ஆசிரியர்"},{"l":"mother","r":"அம்மா"},{"l":"father","r":"அப்பா"},{"l":"brother","r":"சகோதரன்"},{"l":"sister","r":"சகோதரி"},{"l":"family","r":"குடும்பம்"},{"l":"one","r":"ஒன்று"},{"l":"two","r":"இரண்டு"},{"l":"three","r":"மூன்று"},{"l":"four","r":"நான்கு"},{"l":"five","r":"ஐந்து"},{"l":"red","r":"சிவப்பு"},{"l":"blue","r":"நீலம்"},{"l":"green","r":"பச்சை"},{"l":"yellow","r":"மஞ்சள்"},{"l":"black","r":"கருப்பு"}],"explain":"Match as many pairs as you can in 90 seconds. Wrong taps cost you time."}]}$json$::jsonb) on conflict (id) do update set title = excluded.title, content = excluded.content;
insert into public.units (id, course_id, position, title, content) values ('en-for-ta.u2', 'en-for-ta', 2, 'Daily Life', $json${"subtitle":"Food, home, routine, days, shopping","section":"Section 2: Everyday Life","guidebook":{"intro":"Now build real sentences. The biggest change from Tamil: in English the verb sits in the middle of the sentence, not at the end.","tips":[{"title":"Subject, Verb, Object","body":"Tamil puts the verb last. English puts it second: Subject + Verb + Object.","examples":[{"t":"I eat rice","n":"நான் சாதம் சாப்பிடுகிறேன்"}]},{"title":"He / she / it adds -s","body":"With I, you, we, they the verb stays the same. With he, she or it, add -s (or -es after go).","examples":[{"t":"She drinks tea","n":"அவள் தேநீர் குடிக்கிறாள்"},{"t":"He goes to school","n":"அவன் பள்ளிக்குச் செல்கிறான்"}]},{"title":"In, on, at","body":"Tamil adds an ending to the word (-இல், -க்கு). English puts a small word before it. at + clock time, on + day, in + morning.","examples":[{"t":"at six","n":"ஆறு மணிக்கு"},{"t":"on Monday","n":"திங்கள்கிழமை"},{"t":"in the morning","n":"காலையில்"}]}]},"roleplayIds":[]}$json$::jsonb) on conflict (id) do update set title = excluded.title, content = excluded.content;
insert into public.lessons (id, unit_id, position, kind, title, content) values ('en-for-ta.u2.l1', 'en-for-ta.u2', 1, 'lesson', 'Food and Drink', $json${"vocab":[{"t":"rice","n":"சாதம்","e":"🍚"},{"t":"water","n":"தண்ணீர்","e":"💧"},{"t":"tea","n":"தேநீர்","e":"🍵"},{"t":"milk","n":"பால்","e":"🥛"},{"t":"bread","n":"ரொட்டி","e":"🍞"}],"exercises":[{"id":"en-for-ta.u2.l1.e1","type":"MULTIPLE_CHOICE","prompt":"What does “rice” mean?","speak":"rice","options":[{"text":"காலை"},{"text":"இடது"},{"text":"பச்சை"},{"text":"சாதம்"}],"correct":3,"focus":["rice"],"explain":"“rice” = “சாதம்”. English word order is Subject + Verb + Object (I eat rice). In Tamil the verb comes last. With he, she or it, add -s to the verb: she drinks."},{"id":"en-for-ta.u2.l1.e2","type":"MATCH_PAIRS","pairs":[{"l":"rice","r":"சாதம்"},{"l":"water","r":"தண்ணீர்"},{"l":"tea","r":"தேநீர்"},{"l":"milk","r":"பால்"},{"l":"bread","r":"ரொட்டி"}],"focus":["rice","water","tea","milk","bread"],"explain":"Match each word with its meaning. Tap a word, then tap its partner."},{"id":"en-for-ta.u2.l1.e3","type":"MULTIPLE_CHOICE","prompt":"Which one is “சாதம்”?","options":[{"text":"three","emoji":"3️⃣"},{"text":"tea","emoji":"🍵"},{"text":"hot","emoji":"🥵"},{"text":"rice","emoji":"🍚"}],"correct":3,"focus":["rice"],"explain":"“rice” means “சாதம்” 🍚. English word order is Subject + Verb + Object (I eat rice). In Tamil the verb comes last. With he, she or it, add -s to the verb: she drinks."},{"id":"en-for-ta.u2.l1.e4","type":"WORD_BANK","prompt":"நான் சாதம் சாப்பிடுகிறேன்","dir":"toTarget","answer":"I eat rice","bank":["table","six","eat","rice","I"],"accept":[],"focus":["rice"],"explain":"Subject (I) + verb (eat) + object (rice). The verb is in the middle, not at the end like Tamil."},{"id":"en-for-ta.u2.l1.e5","type":"LISTENING_TAP","audio":"I drink water","answer":"I drink water","bank":["at","drink","today","water","I","she"],"translation":"நான் தண்ணீர் குடிக்கிறேன்","accept":[],"focus":["water"],"explain":"English word order is Subject + Verb + Object (I eat rice). In Tamil the verb comes last. With he, she or it, add -s to the verb: she drinks."},{"id":"en-for-ta.u2.l1.e6","type":"MULTIPLE_CHOICE","prompt":"How do you say “தண்ணீர்” in English?","options":[{"text":"water"},{"text":"family"},{"text":"friend"},{"text":"wake up"}],"correct":0,"focus":["water"],"explain":"“தண்ணீர்” in English is “water”."},{"id":"en-for-ta.u2.l1.e7","type":"TYPE_TRANSLATION","prompt":"அவள் தேநீர் குடிக்கிறாள்","dir":"toTarget","answer":"She drinks tea","accept":[],"focus":["tea"],"explain":"With he / she / it, add -s to the verb: she drinks, he eats."},{"id":"en-for-ta.u2.l1.e8","type":"FILL_BLANK","before":"She","after":" tea.","options":["drinks","drink","drinking"],"correct":0,"translation":"அவள் தேநீர் குடிக்கிறாள்.","explain":"English word order is Subject + Verb + Object (I eat rice). In Tamil the verb comes last. With he, she or it, add -s to the verb: she drinks."},{"id":"en-for-ta.u2.l1.e9","type":"SPEAKING_REPEAT","phrase":"I eat rice","translation":"நான் சாதம் சாப்பிடுகிறேன்","focus":["rice"],"explain":"Say it slowly first, then at normal speed. Subject (I) + verb (eat) + object (rice). The verb is in the middle, not at the end like Tamil."},{"id":"en-for-ta.u2.l1.e10","type":"DIALOGUE_COMPLETE","lines":[{"who":"A","text":"What do you drink in the morning?"}],"options":["I drink tea.","I eat a chair.","She is my sister."],"correct":0,"translation":"நீங்கள் காலையில் என்ன குடிக்கிறீர்கள்?","explain":"English word order is Subject + Verb + Object (I eat rice). In Tamil the verb comes last. With he, she or it, add -s to the verb: she drinks."},{"id":"en-for-ta.u2.l1.e11","type":"WORD_BANK","prompt":"நாங்கள் ரொட்டி சாப்பிடுகிறோம்","dir":"toTarget","answer":"We eat bread","bank":["eat","you","We","bread","is"],"accept":[],"focus":["bread"],"explain":"English word order is Subject + Verb + Object (I eat rice). In Tamil the verb comes last. With he, she or it, add -s to the verb: she drinks."}]}$json$::jsonb) on conflict (id) do update set title = excluded.title, content = excluded.content;
insert into public.lessons (id, unit_id, position, kind, title, content) values ('en-for-ta.u2.l2', 'en-for-ta.u2', 2, 'lesson', 'Home', $json${"vocab":[{"t":"house","n":"வீடு","e":"🏠"},{"t":"door","n":"கதவு","e":"🚪"},{"t":"table","n":"மேசை"},{"t":"chair","n":"நாற்காலி","e":"🪑"},{"t":"kitchen","n":"சமையலறை","e":"🍳"}],"exercises":[{"id":"en-for-ta.u2.l2.e1","type":"MULTIPLE_CHOICE","prompt":"What does “house” mean?","speak":"house","options":[{"text":"வீடு"},{"text":"தேநீர்"},{"text":"சகோதரன்"},{"text":"நான்"}],"correct":0,"focus":["house"],"explain":"“house” = “வீடு”. Place words come after in / on / at in English: in the kitchen, on the table. Tamil adds endings like -இல் to the end of the word."},{"id":"en-for-ta.u2.l2.e2","type":"MATCH_PAIRS","pairs":[{"l":"house","r":"வீடு"},{"l":"door","r":"கதவு"},{"l":"table","r":"மேசை"},{"l":"chair","r":"நாற்காலி"},{"l":"kitchen","r":"சமையலறை"}],"focus":["house","door","table","chair","kitchen"],"explain":"Match each word with its meaning. Tap a word, then tap its partner."},{"id":"en-for-ta.u2.l2.e3","type":"MULTIPLE_CHOICE","prompt":"Which one is “வீடு”?","options":[{"text":"black","emoji":"⚫"},{"text":"go","emoji":"🚶"},{"text":"morning","emoji":"🌅"},{"text":"house","emoji":"🏠"}],"correct":3,"focus":["house"],"explain":"“house” means “வீடு” 🏠. Place words come after in / on / at in English: in the kitchen, on the table. Tamil adds endings like -இல் to the end of the word."},{"id":"en-for-ta.u2.l2.e4","type":"WORD_BANK","prompt":"என் வீடு பெரியது","dir":"toTarget","answer":"My house is big","bank":["big","is","this","house","My","drinks","here"],"accept":[],"focus":["house"],"explain":"Place words come after in / on / at in English: in the kitchen, on the table. Tamil adds endings like -இல் to the end of the word."},{"id":"en-for-ta.u2.l2.e5","type":"LISTENING_TAP","audio":"The table is in the kitchen","answer":"The table is in the kitchen","bank":["too","The","in","kitchen","the","is","tea","table","do"],"translation":"மேசை சமையலறையில் உள்ளது","accept":[],"focus":["table","kitchen"],"explain":"Tamil adds -இல் to the place word. English puts \"in\" before it: in the kitchen."},{"id":"en-for-ta.u2.l2.e6","type":"MULTIPLE_CHOICE","prompt":"How do you say “கதவு” in English?","options":[{"text":"medicine"},{"text":"door"},{"text":"station"},{"text":"fever"}],"correct":1,"focus":["door"],"explain":"“கதவு” in English is “door”."},{"id":"en-for-ta.u2.l2.e7","type":"TYPE_TRANSLATION","prompt":"கதவைத் திற","dir":"toTarget","answer":"Open the door","accept":[],"focus":["door"],"explain":"Place words come after in / on / at in English: in the kitchen, on the table. Tamil adds endings like -இல் to the end of the word."},{"id":"en-for-ta.u2.l2.e8","type":"FILL_BLANK","before":"The table is","after":" the kitchen.","options":["in","on","for"],"correct":0,"translation":"மேசை சமையலறையில் உள்ளது.","explain":"Place words come after in / on / at in English: in the kitchen, on the table. Tamil adds endings like -இல் to the end of the word."},{"id":"en-for-ta.u2.l2.e9","type":"SPEAKING_REPEAT","phrase":"My house is big","translation":"என் வீடு பெரியது","focus":["house"],"explain":"Say it slowly first, then at normal speed. Place words come after in / on / at in English: in the kitchen, on the table. Tamil adds endings like -இல் to the end of the word."},{"id":"en-for-ta.u2.l2.e10","type":"DIALOGUE_COMPLETE","lines":[{"who":"A","text":"Where is the table?"}],"options":["It is in the kitchen.","I am fine.","It is red."],"correct":0,"translation":"மேசை எங்கே?","explain":"Place words come after in / on / at in English: in the kitchen, on the table. Tamil adds endings like -இல் to the end of the word."},{"id":"en-for-ta.u2.l2.e11","type":"WORD_BANK","prompt":"இங்கே ஒரு நாற்காலி உள்ளது","dir":"toTarget","answer":"There is a chair here","bank":["a","here","is","have","how","the","There","chair"],"accept":["There's a chair here"],"focus":["chair"],"explain":"Place words come after in / on / at in English: in the kitchen, on the table. Tamil adds endings like -இல் to the end of the word."}]}$json$::jsonb) on conflict (id) do update set title = excluded.title, content = excluded.content;
insert into public.lessons (id, unit_id, position, kind, title, content) values ('en-for-ta.u2.l3', 'en-for-ta.u2', 3, 'lesson', 'Daily Routine', $json${"vocab":[{"t":"wake up","n":"எழுந்திரு","e":"⏰"},{"t":"eat","n":"சாப்பிடு","e":"🍽️"},{"t":"go","n":"போ","e":"🚶"},{"t":"study","n":"படி","e":"📚"},{"t":"sleep","n":"தூங்கு","e":"😴"}],"exercises":[{"id":"en-for-ta.u2.l3.e1","type":"MULTIPLE_CHOICE","prompt":"What does “wake up” mean?","speak":"wake up","options":[{"text":"நேராக"},{"text":"எழுந்திரு"},{"text":"விமான நிலையம்"},{"text":"காலை வணக்கம்"}],"correct":1,"focus":["wake up"],"explain":"“wake up” = “எழுந்திரு”. Use \"at\" for clock time (at six, at ten). With he / she / it the verb gets -s or -es: he goes, she studies."},{"id":"en-for-ta.u2.l3.e2","type":"MATCH_PAIRS","pairs":[{"l":"wake up","r":"எழுந்திரு"},{"l":"eat","r":"சாப்பிடு"},{"l":"go","r":"போ"},{"l":"study","r":"படி"},{"l":"sleep","r":"தூங்கு"}],"focus":["wake up","eat","go","study","sleep"],"explain":"Match each word with its meaning. Tap a word, then tap its partner."},{"id":"en-for-ta.u2.l3.e3","type":"MULTIPLE_CHOICE","prompt":"Which one is “எழுந்திரு”?","options":[{"text":"father","emoji":"👨"},{"text":"wake up","emoji":"⏰"},{"text":"yellow","emoji":"🟡"},{"text":"night","emoji":"🌃"}],"correct":1,"focus":["wake up"],"explain":"“wake up” means “எழுந்திரு” ⏰. Use \"at\" for clock time (at six, at ten). With he / she / it the verb gets -s or -es: he goes, she studies."},{"id":"en-for-ta.u2.l3.e4","type":"WORD_BANK","prompt":"நான் ஆறு மணிக்கு எழுந்திருக்கிறேன்","dir":"toTarget","answer":"I wake up at six","bank":["at","eat","six","up","too","I","wake","today"],"accept":[],"focus":["wake up"],"explain":"Use \"at\" before a clock time: at six. Tamil puts மணிக்கு after the time."},{"id":"en-for-ta.u2.l3.e5","type":"LISTENING_TAP","audio":"He goes to school","answer":"He goes to school","bank":["am","big","school","goes","morning","He","to"],"translation":"அவன் பள்ளிக்குச் செல்கிறான்","accept":[],"focus":[],"explain":"Use \"at\" for clock time (at six, at ten). With he / she / it the verb gets -s or -es: he goes, she studies."},{"id":"en-for-ta.u2.l3.e6","type":"MULTIPLE_CHOICE","prompt":"How do you say “சாப்பிடு” in English?","options":[{"text":"family"},{"text":"go"},{"text":"eat"},{"text":"sleep"}],"correct":2,"focus":["eat"],"explain":"“சாப்பிடு” in English is “eat”."},{"id":"en-for-ta.u2.l3.e7","type":"TYPE_TRANSLATION","prompt":"நாங்கள் ஆங்கிலம் படிக்கிறோம்","dir":"toTarget","answer":"We study English","accept":[],"focus":["study"],"explain":"Use \"at\" for clock time (at six, at ten). With he / she / it the verb gets -s or -es: he goes, she studies."},{"id":"en-for-ta.u2.l3.e8","type":"FILL_BLANK","before":"He","after":" to school.","options":["goes","go","going"],"correct":0,"translation":"அவன் பள்ளிக்குச் செல்கிறான்.","explain":"Use \"at\" for clock time (at six, at ten). With he / she / it the verb gets -s or -es: he goes, she studies."},{"id":"en-for-ta.u2.l3.e9","type":"SPEAKING_REPEAT","phrase":"I wake up at six","translation":"நான் ஆறு மணிக்கு எழுந்திருக்கிறேன்","focus":["wake up"],"explain":"Say it slowly first, then at normal speed. Use \"at\" before a clock time: at six. Tamil puts மணிக்கு after the time."},{"id":"en-for-ta.u2.l3.e10","type":"DIALOGUE_COMPLETE","lines":[{"who":"A","text":"When do you wake up?"}],"options":["I wake up at six.","I have two books.","He is my friend."],"correct":0,"translation":"நீங்கள் எப்போது எழுந்திருக்கிறீர்கள்?","explain":"Use \"at\" for clock time (at six, at ten). With he / she / it the verb gets -s or -es: he goes, she studies."},{"id":"en-for-ta.u2.l3.e11","type":"WORD_BANK","prompt":"நான் இரவில் தூங்குகிறேன்","dir":"toTarget","answer":"I sleep at night","bank":["at","sleep","the","is","I","eat","night"],"accept":[],"focus":["sleep"],"explain":"Use \"at\" for clock time (at six, at ten). With he / she / it the verb gets -s or -es: he goes, she studies."}]}$json$::jsonb) on conflict (id) do update set title = excluded.title, content = excluded.content;
insert into public.lessons (id, unit_id, position, kind, title, content) values ('en-for-ta.u2.l4', 'en-for-ta.u2', 4, 'lesson', 'Time and Days', $json${"vocab":[{"t":"today","n":"இன்று","e":"📅"},{"t":"tomorrow","n":"நாளை"},{"t":"Monday","n":"திங்கள்"},{"t":"morning","n":"காலை","e":"🌅"},{"t":"night","n":"இரவு","e":"🌃"}],"exercises":[{"id":"en-for-ta.u2.l4.e1","type":"MULTIPLE_CHOICE","prompt":"What does “today” mean?","speak":"today","options":[{"text":"நேராக"},{"text":"சூரியன்"},{"text":"தேநீர்"},{"text":"இன்று"}],"correct":3,"focus":["today"],"explain":"“today” = “இன்று”. Use \"on\" with days (on Monday), \"in\" with parts of the day (in the morning) and \"at\" with night (at night)."},{"id":"en-for-ta.u2.l4.e2","type":"MATCH_PAIRS","pairs":[{"l":"today","r":"இன்று"},{"l":"tomorrow","r":"நாளை"},{"l":"Monday","r":"திங்கள்"},{"l":"morning","r":"காலை"},{"l":"night","r":"இரவு"}],"focus":["today","tomorrow","Monday","morning","night"],"explain":"Match each word with its meaning. Tap a word, then tap its partner."},{"id":"en-for-ta.u2.l4.e3","type":"MULTIPLE_CHOICE","prompt":"Which one is “இன்று”?","options":[{"text":"today","emoji":"📅"},{"text":"name","emoji":"🏷️"},{"text":"straight","emoji":"⬆️"},{"text":"door","emoji":"🚪"}],"correct":0,"focus":["today"],"explain":"“today” means “இன்று” 📅. Use \"on\" with days (on Monday), \"in\" with parts of the day (in the morning) and \"at\" with night (at night)."},{"id":"en-for-ta.u2.l4.e4","type":"WORD_BANK","prompt":"நான் இன்று பிஸியாக இருக்கிறேன்","dir":"toTarget","answer":"I am busy today","bank":["today","am","goes","I","he","eat","busy"],"accept":["I'm busy today"],"focus":["today"],"explain":"Use \"on\" with days (on Monday), \"in\" with parts of the day (in the morning) and \"at\" with night (at night)."},{"id":"en-for-ta.u2.l4.e5","type":"LISTENING_TAP","audio":"See you tomorrow","answer":"See you tomorrow","bank":["am","kitchen","you","See","sleep","tomorrow"],"translation":"நாளை சந்திப்போம்","accept":[],"focus":["tomorrow"],"explain":"Use \"on\" with days (on Monday), \"in\" with parts of the day (in the morning) and \"at\" with night (at night)."},{"id":"en-for-ta.u2.l4.e6","type":"MULTIPLE_CHOICE","prompt":"How do you say “நாளை” in English?","options":[{"text":"morning"},{"text":"hot"},{"text":"tomorrow"},{"text":"blue"}],"correct":2,"focus":["tomorrow"],"explain":"“நாளை” in English is “tomorrow”."},{"id":"en-for-ta.u2.l4.e7","type":"TYPE_TRANSLATION","prompt":"பள்ளி திங்கள்கிழமை தொடங்குகிறது","dir":"toTarget","answer":"School starts on Monday","accept":[],"focus":["Monday"],"explain":"Use \"on\" with days: on Monday. Use \"in\" with morning or evening: in the morning."},{"id":"en-for-ta.u2.l4.e8","type":"FILL_BLANK","before":"School starts","after":" Monday.","options":["on","in","at"],"correct":0,"translation":"பள்ளி திங்கள்கிழமை தொடங்குகிறது.","explain":"Use \"on\" with days (on Monday), \"in\" with parts of the day (in the morning) and \"at\" with night (at night)."},{"id":"en-for-ta.u2.l4.e9","type":"SPEAKING_REPEAT","phrase":"I am busy today","translation":"நான் இன்று பிஸியாக இருக்கிறேன்","focus":["today"],"explain":"Say it slowly first, then at normal speed. Use \"on\" with days (on Monday), \"in\" with parts of the day (in the morning) and \"at\" with night (at night)."},{"id":"en-for-ta.u2.l4.e10","type":"DIALOGUE_COMPLETE","lines":[{"who":"A","text":"See you tomorrow!"}],"options":["See you!","I am ten years old.","The table is red."],"correct":0,"translation":"நாளை சந்திப்போம்!","explain":"Use \"on\" with days (on Monday), \"in\" with parts of the day (in the morning) and \"at\" with night (at night)."},{"id":"en-for-ta.u2.l4.e11","type":"WORD_BANK","prompt":"நான் காலையில் வேலை செய்கிறேன்","dir":"toTarget","answer":"I work in the morning","bank":["morning","I","too","in","the","a","work","eat"],"accept":[],"focus":["morning"],"explain":"Use \"on\" with days (on Monday), \"in\" with parts of the day (in the morning) and \"at\" with night (at night)."}]}$json$::jsonb) on conflict (id) do update set title = excluded.title, content = excluded.content;
insert into public.lessons (id, unit_id, position, kind, title, content) values ('en-for-ta.u2.l5', 'en-for-ta.u2', 5, 'lesson', 'Shopping', $json${"vocab":[{"t":"shop","n":"கடை","e":"🏪"},{"t":"money","n":"பணம்","e":"💰"},{"t":"cheap","n":"மலிவு"},{"t":"expensive","n":"விலை அதிகம்"},{"t":"buy","n":"வாங்கு","e":"🛒"}],"exercises":[{"id":"en-for-ta.u2.l5.e1","type":"MULTIPLE_CHOICE","prompt":"What does “shop” mean?","speak":"shop","options":[{"text":"தேநீர்"},{"text":"இடது"},{"text":"கடை"},{"text":"காலை வணக்கம்"}],"correct":2,"focus":["shop"],"explain":"“shop” = “கடை”. To ask a yes/no question, start with \"Do\" or \"Does\": \"Do you have a bag?\" Tamil adds ஆ at the end instead."},{"id":"en-for-ta.u2.l5.e2","type":"MATCH_PAIRS","pairs":[{"l":"shop","r":"கடை"},{"l":"money","r":"பணம்"},{"l":"cheap","r":"மலிவு"},{"l":"expensive","r":"விலை அதிகம்"},{"l":"buy","r":"வாங்கு"}],"focus":["shop","money","cheap","expensive","buy"],"explain":"Match each word with its meaning. Tap a word, then tap its partner."},{"id":"en-for-ta.u2.l5.e3","type":"MULTIPLE_CHOICE","prompt":"Which one is “கடை”?","options":[{"text":"shop","emoji":"🏪"},{"text":"night","emoji":"🌃"},{"text":"sleep","emoji":"😴"},{"text":"green","emoji":"🟢"}],"correct":0,"focus":["shop"],"explain":"“shop” means “கடை” 🏪. To ask a yes/no question, start with \"Do\" or \"Does\": \"Do you have a bag?\" Tamil adds ஆ at the end instead."},{"id":"en-for-ta.u2.l5.e4","type":"WORD_BANK","prompt":"இது எவ்வளவு?","dir":"toTarget","answer":"How much is this","bank":["How","much","school","is","night","this","water"],"accept":[],"focus":[],"explain":"To ask a yes/no question, start with \"Do\" or \"Does\": \"Do you have a bag?\" Tamil adds ஆ at the end instead."},{"id":"en-for-ta.u2.l5.e5","type":"LISTENING_TAP","audio":"I want to buy a shirt","answer":"I want to buy a shirt","bank":["buy","shirt","much","I","drinks","here","to","a","want"],"translation":"நான் ஒரு சட்டை வாங்க விரும்புகிறேன்","accept":[],"focus":["buy"],"explain":"After \"want\" use \"to\" + verb: want to buy."},{"id":"en-for-ta.u2.l5.e6","type":"MULTIPLE_CHOICE","prompt":"How do you say “பணம்” in English?","options":[{"text":"table"},{"text":"money"},{"text":"brother"},{"text":"green"}],"correct":1,"focus":["money"],"explain":"“பணம்” in English is “money”."},{"id":"en-for-ta.u2.l5.e7","type":"TYPE_TRANSLATION","prompt":"இது மிகவும் விலை அதிகம்","dir":"toTarget","answer":"It is too expensive","accept":["It's too expensive"],"focus":["expensive"],"explain":"To ask a yes/no question, start with \"Do\" or \"Does\": \"Do you have a bag?\" Tamil adds ஆ at the end instead."},{"id":"en-for-ta.u2.l5.e8","type":"FILL_BLANK","before":"","after":" you have a bag?","options":["Do","Does","Are"],"correct":0,"translation":"உங்களிடம் பை இருக்கிறதா?","explain":"Use \"Do\" with you, I, we, they. Use \"Does\" with he, she, it."},{"id":"en-for-ta.u2.l5.e9","type":"SPEAKING_REPEAT","phrase":"How much is this","translation":"இது எவ்வளவு?","focus":[],"explain":"Say it slowly first, then at normal speed. To ask a yes/no question, start with \"Do\" or \"Does\": \"Do you have a bag?\" Tamil adds ஆ at the end instead."},{"id":"en-for-ta.u2.l5.e10","type":"DIALOGUE_COMPLETE","lines":[{"who":"A","text":"How much is this shirt?"}],"options":["It is two hundred rupees.","I wake up at six.","My name is Ravi."],"correct":0,"translation":"இந்த சட்டை எவ்வளவு?","explain":"To ask a yes/no question, start with \"Do\" or \"Does\": \"Do you have a bag?\" Tamil adds ஆ at the end instead."},{"id":"en-for-ta.u2.l5.e11","type":"WORD_BANK","prompt":"உங்களிடம் பை இருக்கிறதா?","dir":"toTarget","answer":"Do you have a bag","bank":["have","in","a","you","bag","on","today","Do"],"accept":[],"focus":[],"explain":"Start yes/no questions with Do/Does: Do you have a bag? Tamil adds -ஆ at the end."}]}$json$::jsonb) on conflict (id) do update set title = excluded.title, content = excluded.content;
insert into public.lessons (id, unit_id, position, kind, title, content) values ('en-for-ta.u2.story', 'en-for-ta.u2', 6, 'story', 'At the Shop', $json${"vocab":[],"exercises":[{"id":"en-for-ta.u2.story.e1","type":"INTERACTIVE_STORY","title":"At the Shop","cast":[{"id":"meena","name":"Meena","emoji":"👩"},{"id":"kumar","name":"Mr. Kumar","emoji":"🧔"}],"parts":[{"who":"meena","text":"Good morning! How much is this bag?","tr":"காலை வணக்கம்! இந்த பை எவ்வளவு?"},{"who":"kumar","text":"It is two hundred rupees.","tr":"இது இருநூறு ரூபாய்."},{"who":"meena","text":"That is expensive. Do you have a cheaper bag?","tr":"அது விலை அதிகம். மலிவான பை இருக்கிறதா?"},{"who":"kumar","text":"Yes. This blue bag is one hundred rupees.","tr":"ஆம். இந்த நீலப் பை நூறு ரூபாய்."},{"who":"meena","text":"Great! I want to buy it.","tr":"அருமை! நான் அதை வாங்க விரும்புகிறேன்."},{"who":"kumar","text":"Thank you!","tr":"நன்றி!"}],"questions":[{"after":3,"q":"How much is the blue bag?","options":["One hundred rupees","Two hundred rupees","Five rupees"],"correct":0},{"after":4,"q":"What does Meena want to do?","options":["Buy the blue bag","Sell a shirt","Drink tea"],"correct":0}],"explain":"Listen to the story, then answer the comprehension questions."}]}$json$::jsonb) on conflict (id) do update set title = excluded.title, content = excluded.content;
insert into public.lessons (id, unit_id, position, kind, title, content) values ('en-for-ta.u2.timed', 'en-for-ta.u2', 7, 'timed', 'Ramp Up', $json${"vocab":[],"exercises":[{"id":"en-for-ta.u2.timed.e1","type":"TIMED_CHALLENGE","mode":"ramp_up","seconds":90,"pairs":[{"l":"rice","r":"சாதம்"},{"l":"water","r":"தண்ணீர்"},{"l":"tea","r":"தேநீர்"},{"l":"milk","r":"பால்"},{"l":"bread","r":"ரொட்டி"},{"l":"house","r":"வீடு"},{"l":"door","r":"கதவு"},{"l":"table","r":"மேசை"},{"l":"chair","r":"நாற்காலி"},{"l":"kitchen","r":"சமையலறை"},{"l":"wake up","r":"எழுந்திரு"},{"l":"eat","r":"சாப்பிடு"},{"l":"go","r":"போ"},{"l":"study","r":"படி"},{"l":"sleep","r":"தூங்கு"},{"l":"today","r":"இன்று"},{"l":"tomorrow","r":"நாளை"},{"l":"Monday","r":"திங்கள்"},{"l":"morning","r":"காலை"},{"l":"night","r":"இரவு"},{"l":"shop","r":"கடை"},{"l":"money","r":"பணம்"},{"l":"cheap","r":"மலிவு"},{"l":"expensive","r":"விலை அதிகம்"},{"l":"buy","r":"வாங்கு"}],"explain":"Match as many pairs as you can in 90 seconds. Wrong taps cost you time."}]}$json$::jsonb) on conflict (id) do update set title = excluded.title, content = excluded.content;
insert into public.units (id, course_id, position, title, content) values ('en-for-ta.u3', 'en-for-ta', 3, 'Out and About', $json${"subtitle":"Directions, transport, weather, health, work","section":"Section 3: The Real World","guidebook":{"intro":"Time to use English outside: asking the way, taking a bus, seeing a doctor and talking about work.","tips":[{"title":"Always give a subject","body":"Tamil can say மழை பெய்கிறது with no subject. English needs \"It\": It is raining.","examples":[{"t":"It is hot today","n":"இன்று வெப்பமாக இருக்கிறது"},{"t":"It is raining","n":"மழை பெய்கிறது"}]},{"title":"Questions with do / does","body":"Put Do or Does first. After does, the verb has no -s.","examples":[{"t":"Do you have a bag?","n":"உங்களிடம் பை இருக்கிறதா?"},{"t":"When does the train leave?","n":"ரயில் எப்போது புறப்படும்?"}]},{"title":"The future with will","body":"Use will + base verb. Never add -s after will.","examples":[{"t":"I will send an email","n":"நான் ஒரு மின்னஞ்சல் அனுப்புவேன்"}]}]},"roleplayIds":["en-for-ta.rp.bus","en-for-ta.rp.hotel","en-for-ta.rp.interview"]}$json$::jsonb) on conflict (id) do update set title = excluded.title, content = excluded.content;
insert into public.lessons (id, unit_id, position, kind, title, content) values ('en-for-ta.u3.l1', 'en-for-ta.u3', 1, 'lesson', 'Directions', $json${"vocab":[{"t":"left","n":"இடது","e":"⬅️"},{"t":"right","n":"வலது","e":"➡️"},{"t":"straight","n":"நேராக","e":"⬆️"},{"t":"near","n":"அருகில்"},{"t":"far","n":"தூரம்"}],"exercises":[{"id":"en-for-ta.u3.l1.e1","type":"MULTIPLE_CHOICE","prompt":"What does “left” mean?","speak":"left","options":[{"text":"இடது"},{"text":"குடும்பம்"},{"text":"வலது"},{"text":"மழை"}],"correct":0,"focus":["left"],"explain":"“left” = “இடது”. For directions, start with the verb: \"Turn left\", \"Go straight\". Use \"the\" before places: the bus stop, the station."},{"id":"en-for-ta.u3.l1.e2","type":"MATCH_PAIRS","pairs":[{"l":"left","r":"இடது"},{"l":"right","r":"வலது"},{"l":"straight","r":"நேராக"},{"l":"near","r":"அருகில்"},{"l":"far","r":"தூரம்"}],"focus":["left","right","straight","near","far"],"explain":"Match each word with its meaning. Tap a word, then tap its partner."},{"id":"en-for-ta.u3.l1.e3","type":"MULTIPLE_CHOICE","prompt":"Which one is “இடது”?","options":[{"text":"chair","emoji":"🪑"},{"text":"red","emoji":"🔴"},{"text":"left","emoji":"⬅️"},{"text":"doctor","emoji":"🩺"}],"correct":2,"focus":["left"],"explain":"“left” means “இடது” ⬅️. For directions, start with the verb: \"Turn left\", \"Go straight\". Use \"the\" before places: the bus stop, the station."},{"id":"en-for-ta.u3.l1.e4","type":"WORD_BANK","prompt":"இடதுபுறம் திரும்புங்கள்","dir":"toTarget","answer":"Turn left","bank":["left","kind","Turn","today"],"accept":[],"focus":["left"],"explain":"Give directions with the verb first: Turn left, Go straight."},{"id":"en-for-ta.u3.l1.e5","type":"LISTENING_TAP","audio":"Where is the bus stop","answer":"Where is the bus stop","bank":["is","train","in","stop","bus","the","Where","it"],"translation":"பேருந்து நிறுத்தம் எங்கே?","accept":["Where's the bus stop"],"focus":[],"explain":"For directions, start with the verb: \"Turn left\", \"Go straight\". Use \"the\" before places: the bus stop, the station."},{"id":"en-for-ta.u3.l1.e6","type":"MULTIPLE_CHOICE","prompt":"How do you say “வலது” in English?","options":[{"text":"bread"},{"text":"yellow"},{"text":"right"},{"text":"station"}],"correct":2,"focus":["right"],"explain":"“வலது” in English is “right”."},{"id":"en-for-ta.u3.l1.e7","type":"TYPE_TRANSLATION","prompt":"நேராகச் செல்லுங்கள்","dir":"toTarget","answer":"Go straight","accept":[],"focus":["straight"],"explain":"For directions, start with the verb: \"Turn left\", \"Go straight\". Use \"the\" before places: the bus stop, the station."},{"id":"en-for-ta.u3.l1.e8","type":"FILL_BLANK","before":"Turn","after":" at the corner.","options":["left","near","far"],"correct":0,"translation":"முனையில் இடதுபுறம் திரும்புங்கள்.","explain":"For directions, start with the verb: \"Turn left\", \"Go straight\". Use \"the\" before places: the bus stop, the station."},{"id":"en-for-ta.u3.l1.e9","type":"SPEAKING_REPEAT","phrase":"Turn left","translation":"இடதுபுறம் திரும்புங்கள்","focus":["left"],"explain":"Say it slowly first, then at normal speed. Give directions with the verb first: Turn left, Go straight."},{"id":"en-for-ta.u3.l1.e10","type":"DIALOGUE_COMPLETE","lines":[{"who":"A","text":"Excuse me, where is the station?"}],"options":["Go straight, then turn left.","I am fine.","It is red."],"correct":0,"translation":"மன்னிக்கவும், நிலையம் எங்கே?","explain":"For directions, start with the verb: \"Turn left\", \"Go straight\". Use \"the\" before places: the bus stop, the station."},{"id":"en-for-ta.u3.l1.e11","type":"WORD_BANK","prompt":"It is near the station","dir":"toNative","answer":"அது நிலையத்திற்கு அருகில் உள்ளது","bank":["உள்ளது","நிலையத்திற்கு","என்","வேலை","இடதுபுறம்","அருகில்","அது"],"focus":["near"],"explain":"For directions, start with the verb: \"Turn left\", \"Go straight\". Use \"the\" before places: the bus stop, the station."}]}$json$::jsonb) on conflict (id) do update set title = excluded.title, content = excluded.content;
insert into public.lessons (id, unit_id, position, kind, title, content) values ('en-for-ta.u3.l2', 'en-for-ta.u3', 2, 'lesson', 'Transport', $json${"vocab":[{"t":"bus","n":"பேருந்து","e":"🚌"},{"t":"train","n":"ரயில்","e":"🚆"},{"t":"ticket","n":"பயணச்சீட்டு","e":"🎫"},{"t":"station","n":"நிலையம்","e":"🚉"},{"t":"airport","n":"விமான நிலையம்","e":"✈️"}],"exercises":[{"id":"en-for-ta.u3.l2.e1","type":"MULTIPLE_CHOICE","prompt":"What does “bus” mean?","speak":"bus","options":[{"text":"பேருந்து"},{"text":"கடை"},{"text":"அருகில்"},{"text":"இரவு"}],"correct":0,"focus":["bus"],"explain":"“bus” = “பேருந்து”. Use \"take the bus\" or \"go by bus\". In questions with \"does\", the verb stays simple: \"When does the train leave?\" (not \"leaves\")."},{"id":"en-for-ta.u3.l2.e2","type":"MATCH_PAIRS","pairs":[{"l":"bus","r":"பேருந்து"},{"l":"train","r":"ரயில்"},{"l":"ticket","r":"பயணச்சீட்டு"},{"l":"station","r":"நிலையம்"},{"l":"airport","r":"விமான நிலையம்"}],"focus":["bus","train","ticket","station","airport"],"explain":"Match each word with its meaning. Tap a word, then tap its partner."},{"id":"en-for-ta.u3.l2.e3","type":"MULTIPLE_CHOICE","prompt":"Which one is “பேருந்து”?","options":[{"text":"bus","emoji":"🚌"},{"text":"shop","emoji":"🏪"},{"text":"two","emoji":"2️⃣"},{"text":"bread","emoji":"🍞"}],"correct":0,"focus":["bus"],"explain":"“bus” means “பேருந்து” 🚌. Use \"take the bus\" or \"go by bus\". In questions with \"does\", the verb stays simple: \"When does the train leave?\" (not \"leaves\")."},{"id":"en-for-ta.u3.l2.e4","type":"WORD_BANK","prompt":"நான் வேலைக்குப் பேருந்தில் செல்கிறேன்","dir":"toTarget","answer":"I take the bus to work","bank":["I","work","it","when","bus","to","this","take","the"],"accept":[],"focus":["bus"],"explain":"Use \"take the bus\" or \"go by bus\". In questions with \"does\", the verb stays simple: \"When does the train leave?\" (not \"leaves\")."},{"id":"en-for-ta.u3.l2.e5","type":"LISTENING_TAP","audio":"One ticket please","answer":"One ticket please","bank":["office","One","straight","ticket","i","please"],"translation":"ஒரு பயணச்சீட்டு தயவுசெய்து","accept":[],"focus":["ticket"],"explain":"Use \"take the bus\" or \"go by bus\". In questions with \"does\", the verb stays simple: \"When does the train leave?\" (not \"leaves\")."},{"id":"en-for-ta.u3.l2.e6","type":"MULTIPLE_CHOICE","prompt":"How do you say “ரயில்” in English?","options":[{"text":"Please"},{"text":"two"},{"text":"train"},{"text":"Thank you"}],"correct":2,"focus":["train"],"explain":"“ரயில்” in English is “train”."},{"id":"en-for-ta.u3.l2.e7","type":"TYPE_TRANSLATION","prompt":"ரயில் தாமதமாக உள்ளது","dir":"toTarget","answer":"The train is late","accept":[],"focus":["train"],"explain":"Use \"take the bus\" or \"go by bus\". In questions with \"does\", the verb stays simple: \"When does the train leave?\" (not \"leaves\")."},{"id":"en-for-ta.u3.l2.e8","type":"FILL_BLANK","before":"When does the train","after":"?","options":["leave","leaves","leaving"],"correct":0,"translation":"ரயில் எப்போது புறப்படும்?","explain":"Use \"take the bus\" or \"go by bus\". In questions with \"does\", the verb stays simple: \"When does the train leave?\" (not \"leaves\")."},{"id":"en-for-ta.u3.l2.e9","type":"SPEAKING_REPEAT","phrase":"I take the bus to work","translation":"நான் வேலைக்குப் பேருந்தில் செல்கிறேன்","focus":["bus"],"explain":"Say it slowly first, then at normal speed. Use \"take the bus\" or \"go by bus\". In questions with \"does\", the verb stays simple: \"When does the train leave?\" (not \"leaves\")."},{"id":"en-for-ta.u3.l2.e10","type":"DIALOGUE_COMPLETE","lines":[{"who":"A","text":"Where do you want to go?"}],"options":["I want to go to the airport.","I am ten years old.","She drinks tea."],"correct":0,"translation":"நீங்கள் எங்கே செல்ல விரும்புகிறீர்கள்?","explain":"Use \"take the bus\" or \"go by bus\". In questions with \"does\", the verb stays simple: \"When does the train leave?\" (not \"leaves\")."},{"id":"en-for-ta.u3.l2.e11","type":"WORD_BANK","prompt":"When does the train leave?","dir":"toNative","answer":"ரயில் எப்போது புறப்படும்","bank":["எப்போது","ஒரு","புறப்படும்","ரயில்","பேருந்தில்"],"focus":["train"],"explain":"After \"does\" the verb has no -s: When does the train leave (not leaves)."}]}$json$::jsonb) on conflict (id) do update set title = excluded.title, content = excluded.content;
insert into public.lessons (id, unit_id, position, kind, title, content) values ('en-for-ta.u3.l3', 'en-for-ta.u3', 3, 'lesson', 'Weather', $json${"vocab":[{"t":"hot","n":"வெப்பம்","e":"🥵"},{"t":"rain","n":"மழை","e":"🌧️"},{"t":"cold","n":"குளிர்","e":"🥶"},{"t":"sun","n":"சூரியன்","e":"☀️"},{"t":"wind","n":"காற்று","e":"💨"}],"exercises":[{"id":"en-for-ta.u3.l3.e1","type":"MULTIPLE_CHOICE","prompt":"What does “hot” mean?","speak":"hot","options":[{"text":"வெப்பம்"},{"text":"பால்"},{"text":"படி"},{"text":"சகோதரி"}],"correct":0,"focus":["hot"],"explain":"“hot” = “வெப்பம்”. English always needs a subject. For weather we use \"It\": \"It is hot\", \"It is raining\". Tamil has no such word."},{"id":"en-for-ta.u3.l3.e2","type":"MATCH_PAIRS","pairs":[{"l":"hot","r":"வெப்பம்"},{"l":"rain","r":"மழை"},{"l":"cold","r":"குளிர்"},{"l":"sun","r":"சூரியன்"},{"l":"wind","r":"காற்று"}],"focus":["hot","rain","cold","sun","wind"],"explain":"Match each word with its meaning. Tap a word, then tap its partner."},{"id":"en-for-ta.u3.l3.e3","type":"MULTIPLE_CHOICE","prompt":"Which one is “வெப்பம்”?","options":[{"text":"straight","emoji":"⬆️"},{"text":"medicine","emoji":"💊"},{"text":"meeting","emoji":"🗓️"},{"text":"hot","emoji":"🥵"}],"correct":3,"focus":["hot"],"explain":"“hot” means “வெப்பம்” 🥵. English always needs a subject. For weather we use \"It\": \"It is hot\", \"It is raining\". Tamil has no such word."},{"id":"en-for-ta.u3.l3.e4","type":"WORD_BANK","prompt":"இன்று வெப்பமாக இருக்கிறது","dir":"toTarget","answer":"It is hot today","bank":["train","is","have","today","hot","It","hurts"],"accept":["It's hot today"],"focus":["hot"],"explain":"English needs \"It\" here. It has no meaning, but every English sentence needs a subject."},{"id":"en-for-ta.u3.l3.e5","type":"LISTENING_TAP","audio":"It is raining","answer":"It is raining","bank":["raining","It","station","when","is","email"],"translation":"மழை பெய்கிறது","accept":["It's raining"],"focus":[],"explain":"English always needs a subject. For weather we use \"It\": \"It is hot\", \"It is raining\". Tamil has no such word."},{"id":"en-for-ta.u3.l3.e6","type":"MULTIPLE_CHOICE","prompt":"How do you say “மழை” in English?","options":[{"text":"five"},{"text":"kitchen"},{"text":"family"},{"text":"rain"}],"correct":3,"focus":["rain"],"explain":"“மழை” in English is “rain”."},{"id":"en-for-ta.u3.l3.e7","type":"TYPE_TRANSLATION","prompt":"வானிலை நன்றாக உள்ளது","dir":"toTarget","answer":"The weather is nice","accept":[],"focus":[],"explain":"English always needs a subject. For weather we use \"It\": \"It is hot\", \"It is raining\". Tamil has no such word."},{"id":"en-for-ta.u3.l3.e8","type":"FILL_BLANK","before":"","after":" is raining.","options":["It","He","They"],"correct":0,"translation":"மழை பெய்கிறது.","explain":"English always needs a subject. For weather we use \"It\": \"It is hot\", \"It is raining\". Tamil has no such word."},{"id":"en-for-ta.u3.l3.e9","type":"SPEAKING_REPEAT","phrase":"It is hot today","translation":"இன்று வெப்பமாக இருக்கிறது","focus":["hot"],"explain":"Say it slowly first, then at normal speed. English needs \"It\" here. It has no meaning, but every English sentence needs a subject."},{"id":"en-for-ta.u3.l3.e10","type":"DIALOGUE_COMPLETE","lines":[{"who":"A","text":"How is the weather?"}],"options":["It is hot today.","I want to buy a shirt.","My father is a doctor."],"correct":0,"translation":"வானிலை எப்படி?","explain":"English always needs a subject. For weather we use \"It\": \"It is hot\", \"It is raining\". Tamil has no such word."},{"id":"en-for-ta.u3.l3.e11","type":"WORD_BANK","prompt":"I like the rain","dir":"toNative","answer":"எனக்கு மழை பிடிக்கும்","bank":["பிடிக்கும்","மழை","புறப்படும்","எனக்கு","இருக்கிறது"],"focus":["rain"],"explain":"English always needs a subject. For weather we use \"It\": \"It is hot\", \"It is raining\". Tamil has no such word."}]}$json$::jsonb) on conflict (id) do update set title = excluded.title, content = excluded.content;
insert into public.lessons (id, unit_id, position, kind, title, content) values ('en-for-ta.u3.l4', 'en-for-ta.u3', 4, 'lesson', 'Health', $json${"vocab":[{"t":"doctor","n":"மருத்துவர்","e":"🩺"},{"t":"medicine","n":"மருந்து","e":"💊"},{"t":"fever","n":"காய்ச்சல்","e":"🤒"},{"t":"head","n":"தலை"},{"t":"pain","n":"வலி","e":"😣"}],"exercises":[{"id":"en-for-ta.u3.l4.e1","type":"MULTIPLE_CHOICE","prompt":"What does “doctor” mean?","speak":"doctor","options":[{"text":"எழுந்திரு"},{"text":"தலை"},{"text":"மருத்துவர்"},{"text":"ஆசிரியர்"}],"correct":2,"focus":["doctor"],"explain":"“doctor” = “மருத்துவர்”. For illness say \"I have a ...\" (I have a fever). For body pain say \"My ... hurts\" (My head hurts). Tamil uses எனக்கு (to me) instead."},{"id":"en-for-ta.u3.l4.e2","type":"MATCH_PAIRS","pairs":[{"l":"doctor","r":"மருத்துவர்"},{"l":"medicine","r":"மருந்து"},{"l":"fever","r":"காய்ச்சல்"},{"l":"head","r":"தலை"},{"l":"pain","r":"வலி"}],"focus":["doctor","medicine","fever","head","pain"],"explain":"Match each word with its meaning. Tap a word, then tap its partner."},{"id":"en-for-ta.u3.l4.e3","type":"MULTIPLE_CHOICE","prompt":"Which one is “மருத்துவர்”?","options":[{"text":"station","emoji":"🚉"},{"text":"two","emoji":"2️⃣"},{"text":"email","emoji":"📧"},{"text":"doctor","emoji":"🩺"}],"correct":3,"focus":["doctor"],"explain":"“doctor” means “மருத்துவர்” 🩺. For illness say \"I have a ...\" (I have a fever). For body pain say \"My ... hurts\" (My head hurts). Tamil uses எனக்கு (to me) instead."},{"id":"en-for-ta.u3.l4.e4","type":"WORD_BANK","prompt":"எனக்கு காய்ச்சல் உள்ளது","dir":"toTarget","answer":"I have a fever","bank":["fever","have","I","left","straight","a","when"],"accept":[],"focus":["fever"],"explain":"English says \"I have a fever\". Tamil uses எனக்கு (to me)."},{"id":"en-for-ta.u3.l4.e5","type":"LISTENING_TAP","audio":"I need a doctor","answer":"I need a doctor","bank":["I","send","straight","doctor","a","need","raining"],"translation":"எனக்கு ஒரு மருத்துவர் தேவை","accept":[],"focus":["doctor"],"explain":"For illness say \"I have a ...\" (I have a fever). For body pain say \"My ... hurts\" (My head hurts). Tamil uses எனக்கு (to me) instead."},{"id":"en-for-ta.u3.l4.e6","type":"MULTIPLE_CHOICE","prompt":"How do you say “மருந்து” in English?","options":[{"text":"head"},{"text":"right"},{"text":"medicine"},{"text":"cold"}],"correct":2,"focus":["medicine"],"explain":"“மருந்து” in English is “medicine”."},{"id":"en-for-ta.u3.l4.e7","type":"TYPE_TRANSLATION","prompt":"என் தலை வலிக்கிறது","dir":"toTarget","answer":"My head hurts","accept":[],"focus":["head"],"explain":"For illness say \"I have a ...\" (I have a fever). For body pain say \"My ... hurts\" (My head hurts). Tamil uses எனக்கு (to me) instead."},{"id":"en-for-ta.u3.l4.e8","type":"FILL_BLANK","before":"I","after":" a fever.","options":["have","am","has"],"correct":0,"translation":"எனக்கு காய்ச்சல் உள்ளது.","explain":"For illness say \"I have a ...\" (I have a fever). For body pain say \"My ... hurts\" (My head hurts). Tamil uses எனக்கு (to me) instead."},{"id":"en-for-ta.u3.l4.e9","type":"SPEAKING_REPEAT","phrase":"I have a fever","translation":"எனக்கு காய்ச்சல் உள்ளது","focus":["fever"],"explain":"Say it slowly first, then at normal speed. English says \"I have a fever\". Tamil uses எனக்கு (to me)."},{"id":"en-for-ta.u3.l4.e10","type":"DIALOGUE_COMPLETE","lines":[{"who":"A","text":"What is the problem?"}],"options":["I have a fever.","The bus is late.","It is blue."],"correct":0,"translation":"என்ன பிரச்சனை?","explain":"For illness say \"I have a ...\" (I have a fever). For body pain say \"My ... hurts\" (My head hurts). Tamil uses எனக்கு (to me) instead."},{"id":"en-for-ta.u3.l4.e11","type":"WORD_BANK","prompt":"Take this medicine","dir":"toNative","answer":"இந்த மருந்தை எடுத்துக்கொள்ளுங்கள்","bank":["இந்த","வலிக்கிறது","உள்ளது","மருந்தை","எடுத்துக்கொள்ளுங்கள்"],"focus":["medicine"],"explain":"For illness say \"I have a ...\" (I have a fever). For body pain say \"My ... hurts\" (My head hurts). Tamil uses எனக்கு (to me) instead."}]}$json$::jsonb) on conflict (id) do update set title = excluded.title, content = excluded.content;
insert into public.lessons (id, unit_id, position, kind, title, content) values ('en-for-ta.u3.l5', 'en-for-ta.u3', 5, 'lesson', 'Work', $json${"vocab":[{"t":"office","n":"அலுவலகம்","e":"🏢"},{"t":"job","n":"வேலை","e":"💼"},{"t":"boss","n":"மேலாளர்"},{"t":"meeting","n":"கூட்டம்","e":"🗓️"},{"t":"email","n":"மின்னஞ்சல்","e":"📧"}],"exercises":[{"id":"en-for-ta.u3.l5.e1","type":"MULTIPLE_CHOICE","prompt":"What does “office” mean?","speak":"office","options":[{"text":"கூட்டம்"},{"text":"எழுந்திரு"},{"text":"அலுவலகம்"},{"text":"தூரம்"}],"correct":2,"focus":["office"],"explain":"“office” = “அலுவலகம்”. Use \"will\" + base verb for the future: \"I will send an email\" (not \"I will sends\"). Use \"an\" before vowel sounds: an office, an email."},{"id":"en-for-ta.u3.l5.e2","type":"MATCH_PAIRS","pairs":[{"l":"office","r":"அலுவலகம்"},{"l":"job","r":"வேலை"},{"l":"boss","r":"மேலாளர்"},{"l":"meeting","r":"கூட்டம்"},{"l":"email","r":"மின்னஞ்சல்"}],"focus":["office","job","boss","meeting","email"],"explain":"Match each word with its meaning. Tap a word, then tap its partner."},{"id":"en-for-ta.u3.l5.e3","type":"MULTIPLE_CHOICE","prompt":"Which one is “அலுவலகம்”?","options":[{"text":"office","emoji":"🏢"},{"text":"yellow","emoji":"🟡"},{"text":"hot","emoji":"🥵"},{"text":"sister","emoji":"👧"}],"correct":0,"focus":["office"],"explain":"“office” means “அலுவலகம்” 🏢. Use \"will\" + base verb for the future: \"I will send an email\" (not \"I will sends\"). Use \"an\" before vowel sounds: an office, an email."},{"id":"en-for-ta.u3.l5.e4","type":"WORD_BANK","prompt":"நான் ஒரு அலுவலகத்தில் வேலை செய்கிறேன்","dir":"toTarget","answer":"I work in an office","bank":["this","today","an","office","I","work","email","in"],"accept":[],"focus":["office"],"explain":"Use \"an\" before a vowel sound: an office, an email."},{"id":"en-for-ta.u3.l5.e5","type":"LISTENING_TAP","audio":"I have a meeting at ten","answer":"I have a meeting at ten","bank":["at","I","ten","a","have","head","meeting","is","very"],"translation":"எனக்கு பத்து மணிக்கு ஒரு கூட்டம் உள்ளது","accept":[],"focus":["meeting"],"explain":"Use \"will\" + base verb for the future: \"I will send an email\" (not \"I will sends\"). Use \"an\" before vowel sounds: an office, an email."},{"id":"en-for-ta.u3.l5.e6","type":"MULTIPLE_CHOICE","prompt":"How do you say “வேலை” in English?","options":[{"text":"morning"},{"text":"cold"},{"text":"job"},{"text":"mother"}],"correct":2,"focus":["job"],"explain":"“வேலை” in English is “job”."},{"id":"en-for-ta.u3.l5.e7","type":"TYPE_TRANSLATION","prompt":"நான் ஒரு மின்னஞ்சல் அனுப்புவேன்","dir":"toTarget","answer":"I will send an email","accept":["I'll send an email"],"focus":["email"],"explain":"Will + base verb. No -s after will."},{"id":"en-for-ta.u3.l5.e8","type":"FILL_BLANK","before":"I will","after":" an email.","options":["send","sends","sending"],"correct":0,"translation":"நான் ஒரு மின்னஞ்சல் அனுப்புவேன்.","explain":"Use \"will\" + base verb for the future: \"I will send an email\" (not \"I will sends\"). Use \"an\" before vowel sounds: an office, an email."},{"id":"en-for-ta.u3.l5.e9","type":"SPEAKING_REPEAT","phrase":"I work in an office","translation":"நான் ஒரு அலுவலகத்தில் வேலை செய்கிறேன்","focus":["office"],"explain":"Say it slowly first, then at normal speed. Use \"an\" before a vowel sound: an office, an email."},{"id":"en-for-ta.u3.l5.e10","type":"DIALOGUE_COMPLETE","lines":[{"who":"A","text":"What do you do?"}],"options":["I work in an office.","I am very cold.","Turn left."],"correct":0,"translation":"நீங்கள் என்ன வேலை செய்கிறீர்கள்?","explain":"Use \"will\" + base verb for the future: \"I will send an email\" (not \"I will sends\"). Use \"an\" before vowel sounds: an office, an email."},{"id":"en-for-ta.u3.l5.e11","type":"WORD_BANK","prompt":"My boss is very kind","dir":"toNative","answer":"என் மேலாளர் மிகவும் அன்பானவர்","bank":["மிகவும்","வானிலை","அன்பானவர்","என்","மருத்துவர்","மேலாளர்","வேலைக்குப்"],"focus":["boss"],"explain":"Use \"will\" + base verb for the future: \"I will send an email\" (not \"I will sends\"). Use \"an\" before vowel sounds: an office, an email."}]}$json$::jsonb) on conflict (id) do update set title = excluded.title, content = excluded.content;
insert into public.lessons (id, unit_id, position, kind, title, content) values ('en-for-ta.u3.story', 'en-for-ta.u3', 6, 'story', 'Late for the Bus', $json${"vocab":[],"exercises":[{"id":"en-for-ta.u3.story.e1","type":"INTERACTIVE_STORY","title":"Late for the Bus","cast":[{"id":"sam","name":"Sam","emoji":"🧑"},{"id":"anu","name":"Anu","emoji":"👩"}],"parts":[{"who":"sam","text":"Excuse me, where is the bus stop?","tr":"மன்னிக்கவும், பேருந்து நிறுத்தம் எங்கே?"},{"who":"anu","text":"Go straight and turn left. It is near the station.","tr":"நேராகச் சென்று இடதுபுறம் திரும்புங்கள். அது நிலையத்திற்கு அருகில் உள்ளது."},{"who":"sam","text":"Thank you! Is the bus late today?","tr":"நன்றி! இன்று பேருந்து தாமதமா?"},{"who":"anu","text":"Yes. It is raining and the bus is late.","tr":"ஆம். மழை பெய்கிறது, பேருந்து தாமதமாக உள்ளது."},{"who":"sam","text":"Oh no. I have a meeting at ten.","tr":"ஐயோ. எனக்கு பத்து மணிக்கு கூட்டம் உள்ளது."},{"who":"anu","text":"Take a taxi, then. Good luck!","tr":"அப்படியானால் டாக்ஸியில் செல்லுங்கள். வாழ்த்துகள்!"}],"questions":[{"after":1,"q":"Where is the bus stop?","options":["Near the station","Far from the shop","In the kitchen"],"correct":0},{"after":4,"q":"Why is Sam worried?","options":["He has a meeting at ten","He has no money","He is sick"],"correct":0}],"explain":"Listen to the story, then answer the comprehension questions."}]}$json$::jsonb) on conflict (id) do update set title = excluded.title, content = excluded.content;
insert into public.lessons (id, unit_id, position, kind, title, content) values ('en-for-ta.u3.timed', 'en-for-ta.u3', 7, 'timed', 'Match Madness', $json${"vocab":[],"exercises":[{"id":"en-for-ta.u3.timed.e1","type":"TIMED_CHALLENGE","mode":"match_madness","seconds":90,"pairs":[{"l":"left","r":"இடது"},{"l":"right","r":"வலது"},{"l":"straight","r":"நேராக"},{"l":"near","r":"அருகில்"},{"l":"far","r":"தூரம்"},{"l":"bus","r":"பேருந்து"},{"l":"train","r":"ரயில்"},{"l":"ticket","r":"பயணச்சீட்டு"},{"l":"station","r":"நிலையம்"},{"l":"airport","r":"விமான நிலையம்"},{"l":"hot","r":"வெப்பம்"},{"l":"rain","r":"மழை"},{"l":"cold","r":"குளிர்"},{"l":"sun","r":"சூரியன்"},{"l":"wind","r":"காற்று"},{"l":"doctor","r":"மருத்துவர்"},{"l":"medicine","r":"மருந்து"},{"l":"fever","r":"காய்ச்சல்"},{"l":"head","r":"தலை"},{"l":"pain","r":"வலி"},{"l":"office","r":"அலுவலகம்"},{"l":"job","r":"வேலை"},{"l":"boss","r":"மேலாளர்"},{"l":"meeting","r":"கூட்டம்"},{"l":"email","r":"மின்னஞ்சல்"}],"explain":"Match as many pairs as you can in 90 seconds. Wrong taps cost you time."}]}$json$::jsonb) on conflict (id) do update set title = excluded.title, content = excluded.content;
insert into public.units (id, course_id, position, title, content) values ('es-for-en.u1', 'es-for-en', 1, 'Hola, Spanish!', $json${"subtitle":"Greetings, names, family, numbers, colors","section":"Section 1: Getting Started","guidebook":{"intro":"Spanish is very regular and you pronounce it the way you read it. Start with the everyday basics.","tips":[{"title":"Questions get two marks","body":"Spanish opens a question with ¿ and closes it with ?. The opening mark tells you early that a question is coming.","examples":[{"t":"¿Cómo estás?","n":"How are you?"},{"t":"¿Cómo te llamas?","n":"What is your name?"}]},{"title":"Every noun has a gender","body":"Nouns are masculine (el, un) or feminine (la, una). Most words ending in -o are masculine and -a feminine.","examples":[{"t":"el hermano","n":"the brother"},{"t":"la hermana","n":"the sister"}]},{"title":"Add -s for plurals","body":"Add -s to a noun ending in a vowel: libro, libros. Numbers above one need the plural.","examples":[{"t":"un libro","n":"one book"},{"t":"dos libros","n":"two books"}]}]},"roleplayIds":["es-for-en.rp.coffee","es-for-en.rp.doctor"]}$json$::jsonb) on conflict (id) do update set title = excluded.title, content = excluded.content;
insert into public.lessons (id, unit_id, position, kind, title, content) values ('es-for-en.u1.l1', 'es-for-en.u1', 1, 'lesson', 'Greetings', $json${"vocab":[{"t":"hola","n":"hello","e":"👋"},{"t":"buenos días","n":"good morning","e":"🌅"},{"t":"buenas noches","n":"good night","e":"🌙"},{"t":"gracias","n":"thank you","e":"🙏"},{"t":"por favor","n":"please"}],"exercises":[{"id":"es-for-en.u1.l1.e1","type":"MULTIPLE_CHOICE","prompt":"What does “hola” mean?","speak":"hola","options":[{"text":"blue"},{"text":"station"},{"text":"meeting"},{"text":"hello"}],"correct":3,"focus":["hola"],"explain":"“hola” = “hello”. Spanish says \"buenos días\" (plural) for good morning, but \"buenas noches\" for good night. Questions start with ¿ and end with ?."},{"id":"es-for-en.u1.l1.e2","type":"MATCH_PAIRS","pairs":[{"l":"hola","r":"hello"},{"l":"buenos días","r":"good morning"},{"l":"buenas noches","r":"good night"},{"l":"gracias","r":"thank you"},{"l":"por favor","r":"please"}],"focus":["hola","buenos días","buenas noches","gracias","por favor"],"explain":"Match each word with its meaning. Tap a word, then tap its partner."},{"id":"es-for-en.u1.l1.e3","type":"MULTIPLE_CHOICE","prompt":"Which one is “hello”?","options":[{"text":"hola","emoji":"👋"},{"text":"médico","emoji":"🩺"},{"text":"comer","emoji":"🍽️"},{"text":"amarillo","emoji":"🟡"}],"correct":0,"focus":["hola"],"explain":"“hola” means “hello” 👋. Spanish says \"buenos días\" (plural) for good morning, but \"buenas noches\" for good night. Questions start with ¿ and end with ?."},{"id":"es-for-en.u1.l1.e4","type":"WORD_BANK","prompt":"Hello, how are you?","dir":"toTarget","answer":"Hola cómo estás","bank":["años","estás","cómo","bolsa","Hola"],"accept":[],"focus":["hola"],"explain":"Spanish questions start with ¿ and end with ?."},{"id":"es-for-en.u1.l1.e5","type":"LISTENING_TAP","audio":"Estoy bien gracias","answer":"Estoy bien gracias","bank":["diez","hola","Estoy","gracias","bien","gusto"],"translation":"I am fine, thank you","accept":[],"focus":["gracias"],"explain":"Spanish says \"buenos días\" (plural) for good morning, but \"buenas noches\" for good night. Questions start with ¿ and end with ?."},{"id":"es-for-en.u1.l1.e6","type":"MULTIPLE_CHOICE","prompt":"How do you say “good morning” in Spanish?","options":[{"text":"lluvia"},{"text":"uno"},{"text":"buenos días"},{"text":"sol"}],"correct":2,"focus":["buenos días"],"explain":"“good morning” in Spanish is “buenos días”."},{"id":"es-for-en.u1.l1.e7","type":"TYPE_TRANSLATION","prompt":"Good morning, teacher","dir":"toTarget","answer":"Buenos días profesora","accept":[],"focus":["buenos días"],"explain":"Spanish says \"buenos días\" (plural) for good morning, but \"buenas noches\" for good night. Questions start with ¿ and end with ?."},{"id":"es-for-en.u1.l1.e8","type":"FILL_BLANK","before":"Buenos","after":", profesora.","options":["días","noches","tardes"],"correct":0,"translation":"Good morning, teacher.","explain":"Spanish says \"buenos días\" (plural) for good morning, but \"buenas noches\" for good night. Questions start with ¿ and end with ?."},{"id":"es-for-en.u1.l1.e9","type":"SPEAKING_REPEAT","phrase":"Hola cómo estás","translation":"Hello, how are you?","focus":["hola"],"explain":"Say it slowly first, then at normal speed. Spanish questions start with ¿ and end with ?."},{"id":"es-for-en.u1.l1.e10","type":"DIALOGUE_COMPLETE","lines":[{"who":"A","text":"Hola, ¿cómo estás?"}],"options":["Estoy bien, gracias.","Buenas noches.","Por favor."],"correct":0,"translation":"Hello, how are you?","explain":"Spanish says \"buenos días\" (plural) for good morning, but \"buenas noches\" for good night. Questions start with ¿ and end with ?."},{"id":"es-for-en.u1.l1.e11","type":"WORD_BANK","prompt":"Por favor, siéntate","dir":"toNative","answer":"Please sit down","bank":["Please","ravi","down","sit","your"],"focus":["por favor"],"explain":"Spanish says \"buenos días\" (plural) for good morning, but \"buenas noches\" for good night. Questions start with ¿ and end with ?."}]}$json$::jsonb) on conflict (id) do update set title = excluded.title, content = excluded.content;
insert into public.lessons (id, unit_id, position, kind, title, content) values ('es-for-en.u1.l2', 'es-for-en.u1', 2, 'lesson', 'Introductions', $json${"vocab":[{"t":"yo","n":"I"},{"t":"tú","n":"you"},{"t":"nombre","n":"name","e":"🏷️"},{"t":"amigo","n":"friend","e":"🧑‍🤝‍🧑"},{"t":"profesor","n":"teacher","e":"👨‍🏫"}],"exercises":[{"id":"es-for-en.u1.l2.e1","type":"MULTIPLE_CHOICE","prompt":"What does “yo” mean?","speak":"yo","options":[{"text":"bus"},{"text":"sister"},{"text":"I"},{"text":"to go"}],"correct":2,"focus":["yo"],"explain":"“yo” = “I”. To say your name use \"Me llamo ...\" (literally \"I call myself\"). To ask, use \"¿Cómo te llamas?\"."},{"id":"es-for-en.u1.l2.e2","type":"MATCH_PAIRS","pairs":[{"l":"yo","r":"I"},{"l":"tú","r":"you"},{"l":"nombre","r":"name"},{"l":"amigo","r":"friend"},{"l":"profesor","r":"teacher"}],"focus":["yo","tú","nombre","amigo","profesor"],"explain":"Match each word with its meaning. Tap a word, then tap its partner."},{"id":"es-for-en.u1.l2.e3","type":"MULTIPLE_CHOICE","prompt":"Which one is “name”?","options":[{"text":"dinero","emoji":"💰"},{"text":"amarillo","emoji":"🟡"},{"text":"nombre","emoji":"🏷️"},{"text":"familia","emoji":"👨‍👩‍👧‍👦"}],"correct":2,"focus":["nombre"],"explain":"“nombre” means “name” 🏷️. To say your name use \"Me llamo ...\" (literally \"I call myself\"). To ask, use \"¿Cómo te llamas?\"."},{"id":"es-for-en.u1.l2.e4","type":"WORD_BANK","prompt":"My name is Ravi","dir":"toTarget","answer":"Me llamo Ravi","bank":["gracias","Ravi","siéntate","llamo","Me"],"accept":[],"focus":[],"explain":"Spanish says \"I call myself\" (me llamo) for \"my name is\"."},{"id":"es-for-en.u1.l2.e5","type":"LISTENING_TAP","audio":"Cómo te llamas","answer":"Cómo te llamas","bank":["amigo","te","Cómo","mi","tengo","llamas"],"translation":"What is your name?","accept":[],"focus":[],"explain":"To say your name use \"Me llamo ...\" (literally \"I call myself\"). To ask, use \"¿Cómo te llamas?\"."},{"id":"es-for-en.u1.l2.e6","type":"MULTIPLE_CHOICE","prompt":"How do you say “you” in Spanish?","options":[{"text":"yo"},{"text":"lejos"},{"text":"cerca"},{"text":"tú"}],"correct":3,"focus":["tú"],"explain":"“you” in Spanish is “tú”."},{"id":"es-for-en.u1.l2.e7","type":"TYPE_TRANSLATION","prompt":"Nice to meet you","dir":"toTarget","answer":"Mucho gusto","accept":[],"focus":[],"explain":"To say your name use \"Me llamo ...\" (literally \"I call myself\"). To ask, use \"¿Cómo te llamas?\"."},{"id":"es-for-en.u1.l2.e8","type":"FILL_BLANK","before":"Me","after":" Ravi.","options":["llamo","llamas","llama"],"correct":0,"translation":"My name is Ravi.","explain":"Me goes with llamo (I). Te goes with llamas (you)."},{"id":"es-for-en.u1.l2.e9","type":"SPEAKING_REPEAT","phrase":"Me llamo Ravi","translation":"My name is Ravi","focus":[],"explain":"Say it slowly first, then at normal speed. Spanish says \"I call myself\" (me llamo) for \"my name is\"."},{"id":"es-for-en.u1.l2.e10","type":"DIALOGUE_COMPLETE","lines":[{"who":"A","text":"¿Cómo te llamas?"}],"options":["Me llamo Ravi.","Estoy bien.","Buenas noches."],"correct":0,"translation":"What is your name?","explain":"To say your name use \"Me llamo ...\" (literally \"I call myself\"). To ask, use \"¿Cómo te llamas?\"."},{"id":"es-for-en.u1.l2.e11","type":"WORD_BANK","prompt":"Él es mi amigo","dir":"toNative","answer":"He is my friend","bank":["He","bag","my","is","your","ten","friend"],"focus":["amigo"],"explain":"To say your name use \"Me llamo ...\" (literally \"I call myself\"). To ask, use \"¿Cómo te llamas?\"."}]}$json$::jsonb) on conflict (id) do update set title = excluded.title, content = excluded.content;
insert into public.lessons (id, unit_id, position, kind, title, content) values ('es-for-en.u1.l3', 'es-for-en.u1', 3, 'lesson', 'Family', $json${"vocab":[{"t":"madre","n":"mother","e":"👩"},{"t":"padre","n":"father","e":"👨"},{"t":"hermano","n":"brother","e":"👦"},{"t":"hermana","n":"sister","e":"👧"},{"t":"familia","n":"family","e":"👨‍👩‍👧‍👦"}],"exercises":[{"id":"es-for-en.u1.l3.e1","type":"MULTIPLE_CHOICE","prompt":"What does “madre” mean?","speak":"madre","options":[{"text":"to study"},{"text":"mother"},{"text":"rice"},{"text":"train"}],"correct":1,"focus":["madre"],"explain":"“madre” = “mother”. Every Spanish noun is masculine or feminine. Use el / un for masculine and la / una for feminine. Family words show it clearly: hermano / hermana."},{"id":"es-for-en.u1.l3.e2","type":"MATCH_PAIRS","pairs":[{"l":"madre","r":"mother"},{"l":"padre","r":"father"},{"l":"hermano","r":"brother"},{"l":"hermana","r":"sister"},{"l":"familia","r":"family"}],"focus":["madre","padre","hermano","hermana","familia"],"explain":"Match each word with its meaning. Tap a word, then tap its partner."},{"id":"es-for-en.u1.l3.e3","type":"MULTIPLE_CHOICE","prompt":"Which one is “mother”?","options":[{"text":"tres","emoji":"3️⃣"},{"text":"madre","emoji":"👩"},{"text":"arroz","emoji":"🍚"},{"text":"azul","emoji":"🔵"}],"correct":1,"focus":["madre"],"explain":"“madre” means “mother” 👩. Every Spanish noun is masculine or feminine. Use el / un for masculine and la / una for feminine. Family words show it clearly: hermano / hermana."},{"id":"es-for-en.u1.l3.e4","type":"WORD_BANK","prompt":"This is my mother","dir":"toTarget","answer":"Esta es mi madre","bank":["años","Esta","es","madre","cómo","el","mi"],"accept":[],"focus":["madre"],"explain":"\"Esta\" goes with feminine words (madre), \"este\" with masculine (padre)."},{"id":"es-for-en.u1.l3.e5","type":"LISTENING_TAP","audio":"Tengo un hermano","answer":"Tengo un hermano","bank":["azul","años","un","negra","Tengo","hermano"],"translation":"I have a brother","accept":[],"focus":["hermano"],"explain":"Every Spanish noun is masculine or feminine. Use el / un for masculine and la / una for feminine. Family words show it clearly: hermano / hermana."},{"id":"es-for-en.u1.l3.e6","type":"MULTIPLE_CHOICE","prompt":"How do you say “father” in Spanish?","options":[{"text":"padre"},{"text":"tren"},{"text":"buenas noches"},{"text":"puerta"}],"correct":0,"focus":["padre"],"explain":"“father” in Spanish is “padre”."},{"id":"es-for-en.u1.l3.e7","type":"TYPE_TRANSLATION","prompt":"My father is a doctor","dir":"toTarget","answer":"Mi padre es médico","accept":[],"focus":["padre"],"explain":"Spanish drops \"a\" before jobs: es médico, not es un médico."},{"id":"es-for-en.u1.l3.e8","type":"FILL_BLANK","before":"Ella es mi","after":".","options":["hermana","hermano","padre"],"correct":0,"translation":"She is my sister.","explain":"\"Ella\" is she, so use the feminine word: hermana."},{"id":"es-for-en.u1.l3.e9","type":"SPEAKING_REPEAT","phrase":"Esta es mi madre","translation":"This is my mother","focus":["madre"],"explain":"Say it slowly first, then at normal speed. \"Esta\" goes with feminine words (madre), \"este\" with masculine (padre)."},{"id":"es-for-en.u1.l3.e10","type":"DIALOGUE_COMPLETE","lines":[{"who":"A","text":"¿Quién es ella?"}],"options":["Ella es mi hermana.","Él es mi hermano.","Estoy bien."],"correct":0,"translation":"Who is she?","explain":"Every Spanish noun is masculine or feminine. Use el / un for masculine and la / una for feminine. Family words show it clearly: hermano / hermana."},{"id":"es-for-en.u1.l3.e11","type":"WORD_BANK","prompt":"Ella es mi hermana","dir":"toNative","answer":"She is my sister","bank":["my","is","She","sister","fine","black","thank"],"focus":["hermana"],"explain":"Every Spanish noun is masculine or feminine. Use el / un for masculine and la / una for feminine. Family words show it clearly: hermano / hermana."}]}$json$::jsonb) on conflict (id) do update set title = excluded.title, content = excluded.content;
insert into public.lessons (id, unit_id, position, kind, title, content) values ('es-for-en.u1.l4', 'es-for-en.u1', 4, 'lesson', 'Numbers 1 to 5', $json${"vocab":[{"t":"uno","n":"one","e":"1️⃣"},{"t":"dos","n":"two","e":"2️⃣"},{"t":"tres","n":"three","e":"3️⃣"},{"t":"cuatro","n":"four","e":"4️⃣"},{"t":"cinco","n":"five","e":"5️⃣"}],"exercises":[{"id":"es-for-en.u1.l4.e1","type":"MULTIPLE_CHOICE","prompt":"What does “uno” mean?","speak":"uno","options":[{"text":"rice"},{"text":"four"},{"text":"medicine"},{"text":"one"}],"correct":3,"focus":["uno"],"explain":"“uno” = “one”. Add -s to make a noun plural: un libro, dos libros. For age, Spanish says \"tengo ... años\" (I have ... years)."},{"id":"es-for-en.u1.l4.e2","type":"MATCH_PAIRS","pairs":[{"l":"uno","r":"one"},{"l":"dos","r":"two"},{"l":"tres","r":"three"},{"l":"cuatro","r":"four"},{"l":"cinco","r":"five"}],"focus":["uno","dos","tres","cuatro","cinco"],"explain":"Match each word with its meaning. Tap a word, then tap its partner."},{"id":"es-for-en.u1.l4.e3","type":"MULTIPLE_CHOICE","prompt":"Which one is “one”?","options":[{"text":"uno","emoji":"1️⃣"},{"text":"negro","emoji":"⚫"},{"text":"hoy","emoji":"📅"},{"text":"gracias","emoji":"🙏"}],"correct":0,"focus":["uno"],"explain":"“uno” means “one” 1️⃣. Add -s to make a noun plural: un libro, dos libros. For age, Spanish says \"tengo ... años\" (I have ... years)."},{"id":"es-for-en.u1.l4.e4","type":"WORD_BANK","prompt":"I have two books","dir":"toTarget","answer":"Tengo dos libros","bank":["Tengo","dos","llamas","libros","azul"],"accept":[],"focus":["dos"],"explain":"For more than one, add -s to the noun: un libro, dos libros."},{"id":"es-for-en.u1.l4.e5","type":"LISTENING_TAP","audio":"Hay cinco personas","answer":"Hay cinco personas","bank":["personas","él","tengo","cinco","siéntate","Hay"],"translation":"There are five people","accept":[],"focus":["cinco"],"explain":"Add -s to make a noun plural: un libro, dos libros. For age, Spanish says \"tengo ... años\" (I have ... years)."},{"id":"es-for-en.u1.l4.e6","type":"MULTIPLE_CHOICE","prompt":"How do you say “two” in Spanish?","options":[{"text":"derecha"},{"text":"oficina"},{"text":"puerta"},{"text":"dos"}],"correct":3,"focus":["dos"],"explain":"“two” in Spanish is “dos”."},{"id":"es-for-en.u1.l4.e7","type":"TYPE_TRANSLATION","prompt":"I am ten years old","dir":"toTarget","answer":"Tengo diez años","accept":[],"focus":[],"explain":"Spanish says \"I have ten years\" (tengo diez años) for age."},{"id":"es-for-en.u1.l4.e8","type":"FILL_BLANK","before":"Tengo dos","after":".","options":["libros","libro","un libro"],"correct":0,"translation":"I have two books.","explain":"Add -s to make a noun plural: un libro, dos libros. For age, Spanish says \"tengo ... años\" (I have ... years)."},{"id":"es-for-en.u1.l4.e9","type":"SPEAKING_REPEAT","phrase":"Tengo dos libros","translation":"I have two books","focus":["dos"],"explain":"Say it slowly first, then at normal speed. For more than one, add -s to the noun: un libro, dos libros."},{"id":"es-for-en.u1.l4.e10","type":"DIALOGUE_COMPLETE","lines":[{"who":"A","text":"¿Cuántos libros tienes?"}],"options":["Tengo dos libros.","Me llamo Ravi.","Buenos días."],"correct":0,"translation":"How many books do you have?","explain":"Add -s to make a noun plural: un libro, dos libros. For age, Spanish says \"tengo ... años\" (I have ... years)."},{"id":"es-for-en.u1.l4.e11","type":"WORD_BANK","prompt":"Tres manzanas, por favor","dir":"toNative","answer":"Three apples please","bank":["a","apples","Three","please","five"],"focus":["tres"],"explain":"Add -s to make a noun plural: un libro, dos libros. For age, Spanish says \"tengo ... años\" (I have ... years)."}]}$json$::jsonb) on conflict (id) do update set title = excluded.title, content = excluded.content;
insert into public.lessons (id, unit_id, position, kind, title, content) values ('es-for-en.u1.l5', 'es-for-en.u1', 5, 'lesson', 'Colors', $json${"vocab":[{"t":"rojo","n":"red","e":"🔴"},{"t":"azul","n":"blue","e":"🔵"},{"t":"verde","n":"green","e":"🟢"},{"t":"amarillo","n":"yellow","e":"🟡"},{"t":"negro","n":"black","e":"⚫"}],"exercises":[{"id":"es-for-en.u1.l5.e1","type":"MULTIPLE_CHOICE","prompt":"What does “rojo” mean?","speak":"rojo","options":[{"text":"rain"},{"text":"tomorrow"},{"text":"red"},{"text":"water"}],"correct":2,"focus":["rojo"],"explain":"“rojo” = “red”. Colors usually go AFTER the noun and match its gender: la manzana roja, el libro rojo. English puts them before."},{"id":"es-for-en.u1.l5.e2","type":"MATCH_PAIRS","pairs":[{"l":"rojo","r":"red"},{"l":"azul","r":"blue"},{"l":"verde","r":"green"},{"l":"amarillo","r":"yellow"},{"l":"negro","r":"black"}],"focus":["rojo","azul","verde","amarillo","negro"],"explain":"Match each word with its meaning. Tap a word, then tap its partner."},{"id":"es-for-en.u1.l5.e3","type":"MULTIPLE_CHOICE","prompt":"Which one is “red”?","options":[{"text":"madre","emoji":"👩"},{"text":"silla","emoji":"🪑"},{"text":"hermana","emoji":"👧"},{"text":"rojo","emoji":"🔴"}],"correct":3,"focus":["rojo"],"explain":"“rojo” means “red” 🔴. Colors usually go AFTER the noun and match its gender: la manzana roja, el libro rojo. English puts them before."},{"id":"es-for-en.u1.l5.e4","type":"WORD_BANK","prompt":"The apple is red","dir":"toTarget","answer":"La manzana es roja","bank":["cielo","manzana","es","roja","cómo","hola","La"],"accept":[],"focus":[],"explain":"Colors change to match the noun: la manzana roja (feminine), el coche rojo (masculine)."},{"id":"es-for-en.u1.l5.e5","type":"LISTENING_TAP","audio":"Me gusta el azul","answer":"Me gusta el azul","bank":["un","esta","el","Me","gusta","cinco","azul"],"translation":"I like blue","accept":[],"focus":["azul"],"explain":"Colors usually go AFTER the noun and match its gender: la manzana roja, el libro rojo. English puts them before."},{"id":"es-for-en.u1.l5.e6","type":"MULTIPLE_CHOICE","prompt":"How do you say “blue” in Spanish?","options":[{"text":"trabajo"},{"text":"hermano"},{"text":"té"},{"text":"azul"}],"correct":3,"focus":["azul"],"explain":"“blue” in Spanish is “azul”."},{"id":"es-for-en.u1.l5.e7","type":"TYPE_TRANSLATION","prompt":"The sky is blue","dir":"toTarget","answer":"El cielo es azul","accept":[],"focus":["azul"],"explain":"Colors usually go AFTER the noun and match its gender: la manzana roja, el libro rojo. English puts them before."},{"id":"es-for-en.u1.l5.e8","type":"FILL_BLANK","before":"El cielo es","after":".","options":["azul","roja","negra"],"correct":0,"translation":"The sky is blue.","explain":"Cielo is masculine, so pick a form that works for masculine: azul. Roja and negra are feminine."},{"id":"es-for-en.u1.l5.e9","type":"SPEAKING_REPEAT","phrase":"La manzana es roja","translation":"The apple is red","focus":[],"explain":"Say it slowly first, then at normal speed. Colors change to match the noun: la manzana roja (feminine), el coche rojo (masculine)."},{"id":"es-for-en.u1.l5.e10","type":"DIALOGUE_COMPLETE","lines":[{"who":"A","text":"¿De qué color es tu bolsa?"}],"options":["Mi bolsa es negra.","Tengo dos libros.","Buenas noches."],"correct":0,"translation":"What color is your bag?","explain":"Colors usually go AFTER the noun and match its gender: la manzana roja, el libro rojo. English puts them before."},{"id":"es-for-en.u1.l5.e11","type":"WORD_BANK","prompt":"Mi bolsa es negra","dir":"toNative","answer":"My bag is black","bank":["is","father","friend","blue","black","bag","My"],"focus":[],"explain":"Colors usually go AFTER the noun and match its gender: la manzana roja, el libro rojo. English puts them before."}]}$json$::jsonb) on conflict (id) do update set title = excluded.title, content = excluded.content;
insert into public.lessons (id, unit_id, position, kind, title, content) values ('es-for-en.u1.story', 'es-for-en.u1', 6, 'story', 'Un nuevo amigo', $json${"vocab":[],"exercises":[{"id":"es-for-en.u1.story.e1","type":"INTERACTIVE_STORY","title":"Un nuevo amigo","cast":[{"id":"raul","name":"Raúl","emoji":"🧑"},{"id":"sofia","name":"Sofía","emoji":"👩"},{"id":"arturo","name":"Arturo","emoji":"👦"}],"parts":[{"who":"raul","text":"¡Hola! Me llamo Raúl.","tr":"Hello! My name is Raúl."},{"who":"sofia","text":"¡Hola, Raúl! Yo soy Sofía.","tr":"Hi, Raúl! I am Sofía."},{"who":"raul","text":"Mucho gusto, Sofía.","tr":"Nice to meet you, Sofía."},{"who":"sofia","text":"Igualmente. Este es mi hermano, Arturo.","tr":"Likewise. This is my brother, Arturo."},{"who":"arturo","text":"¡Hola! ¿Cómo estás?","tr":"Hello! How are you?"},{"who":"raul","text":"Estoy bien, gracias.","tr":"I am fine, thank you."}],"questions":[{"after":1,"q":"What is the girl's name?","options":["Sofía","Raúl","Arturo"],"correct":0},{"after":4,"q":"Who is Arturo?","options":["Sofía's brother","Raúl's teacher","Sofía's father"],"correct":0}],"explain":"Listen to the story, then answer the comprehension questions."}]}$json$::jsonb) on conflict (id) do update set title = excluded.title, content = excluded.content;
insert into public.lessons (id, unit_id, position, kind, title, content) values ('es-for-en.u1.timed', 'es-for-en.u1', 7, 'timed', 'Match Madness', $json${"vocab":[],"exercises":[{"id":"es-for-en.u1.timed.e1","type":"TIMED_CHALLENGE","mode":"match_madness","seconds":90,"pairs":[{"l":"hola","r":"hello"},{"l":"buenos días","r":"good morning"},{"l":"buenas noches","r":"good night"},{"l":"gracias","r":"thank you"},{"l":"por favor","r":"please"},{"l":"yo","r":"I"},{"l":"tú","r":"you"},{"l":"nombre","r":"name"},{"l":"amigo","r":"friend"},{"l":"profesor","r":"teacher"},{"l":"madre","r":"mother"},{"l":"padre","r":"father"},{"l":"hermano","r":"brother"},{"l":"hermana","r":"sister"},{"l":"familia","r":"family"},{"l":"uno","r":"one"},{"l":"dos","r":"two"},{"l":"tres","r":"three"},{"l":"cuatro","r":"four"},{"l":"cinco","r":"five"},{"l":"rojo","r":"red"},{"l":"azul","r":"blue"},{"l":"verde","r":"green"},{"l":"amarillo","r":"yellow"},{"l":"negro","r":"black"}],"explain":"Match as many pairs as you can in 90 seconds. Wrong taps cost you time."}]}$json$::jsonb) on conflict (id) do update set title = excluded.title, content = excluded.content;
insert into public.units (id, course_id, position, title, content) values ('es-for-en.u2', 'es-for-en', 2, 'Daily Life', $json${"subtitle":"Food, home, routine, days, shopping","section":"Section 2: Everyday Life","guidebook":{"intro":"Spanish verbs change their ending for each person. Learn the pattern once and it works for hundreds of verbs.","tips":[{"title":"Verbs change endings","body":"The ending tells you who is doing the action, so you can often drop the pronoun.","examples":[{"t":"yo como","n":"I eat"},{"t":"ella come","n":"she eats"},{"t":"nosotros comemos","n":"we eat"}]},{"title":"Ser vs estar (is)","body":"Use \"estar\" for where something is and for temporary states. Use \"ser\" for what something is like.","examples":[{"t":"La mesa está en la cocina","n":"The table is in the kitchen"},{"t":"Mi casa es grande","n":"My house is big"}]},{"title":"Time and days","body":"Days use \"el\": el lunes. Clock time uses \"a las\": a las seis.","examples":[{"t":"a las seis","n":"at six"},{"t":"el lunes","n":"on Monday"}]}]},"roleplayIds":[]}$json$::jsonb) on conflict (id) do update set title = excluded.title, content = excluded.content;
insert into public.lessons (id, unit_id, position, kind, title, content) values ('es-for-en.u2.l1', 'es-for-en.u2', 1, 'lesson', 'Food and Drink', $json${"vocab":[{"t":"arroz","n":"rice","e":"🍚"},{"t":"agua","n":"water","e":"💧"},{"t":"té","n":"tea","e":"🍵"},{"t":"leche","n":"milk","e":"🥛"},{"t":"pan","n":"bread","e":"🍞"}],"exercises":[{"id":"es-for-en.u2.l1.e1","type":"MULTIPLE_CHOICE","prompt":"What does “arroz” mean?","speak":"arroz","options":[{"text":"kitchen"},{"text":"boss"},{"text":"teacher"},{"text":"rice"}],"correct":3,"focus":["arroz"],"explain":"“arroz” = “rice”. Spanish verbs change their ending for each person: yo como (I eat), ella come (she eats), nosotros comemos (we eat). Nouns have gender: el arroz, la leche."},{"id":"es-for-en.u2.l1.e2","type":"MATCH_PAIRS","pairs":[{"l":"arroz","r":"rice"},{"l":"agua","r":"water"},{"l":"té","r":"tea"},{"l":"leche","r":"milk"},{"l":"pan","r":"bread"}],"focus":["arroz","agua","té","leche","pan"],"explain":"Match each word with its meaning. Tap a word, then tap its partner."},{"id":"es-for-en.u2.l1.e3","type":"MULTIPLE_CHOICE","prompt":"Which one is “rice”?","options":[{"text":"arroz","emoji":"🍚"},{"text":"pan","emoji":"🍞"},{"text":"tres","emoji":"3️⃣"},{"text":"aeropuerto","emoji":"✈️"}],"correct":0,"focus":["arroz"],"explain":"“arroz” means “rice” 🍚. Spanish verbs change their ending for each person: yo como (I eat), ella come (she eats), nosotros comemos (we eat). Nouns have gender: el arroz, la leche."},{"id":"es-for-en.u2.l1.e4","type":"WORD_BANK","prompt":"I eat rice","dir":"toTarget","answer":"Yo como arroz","bank":["como","arroz","lunes","Yo","caro"],"accept":[],"focus":["arroz"],"explain":"The verb changes with the person: yo como, tú comes, ella come."},{"id":"es-for-en.u2.l1.e5","type":"LISTENING_TAP","audio":"Yo bebo agua","answer":"Yo bebo agua","bank":["hasta","Yo","bebo","lunes","quiero","agua"],"translation":"I drink water","accept":[],"focus":["agua"],"explain":"Spanish verbs change their ending for each person: yo como (I eat), ella come (she eats), nosotros comemos (we eat). Nouns have gender: el arroz, la leche."},{"id":"es-for-en.u2.l1.e6","type":"MULTIPLE_CHOICE","prompt":"How do you say “water” in Spanish?","options":[{"text":"agua"},{"text":"hoy"},{"text":"hermano"},{"text":"frío"}],"correct":0,"focus":["agua"],"explain":"“water” in Spanish is “agua”."},{"id":"es-for-en.u2.l1.e7","type":"TYPE_TRANSLATION","prompt":"She drinks tea","dir":"toTarget","answer":"Ella bebe té","accept":[],"focus":["té"],"explain":"Spanish verbs change their ending for each person: yo como (I eat), ella come (she eats), nosotros comemos (we eat). Nouns have gender: el arroz, la leche."},{"id":"es-for-en.u2.l1.e8","type":"FILL_BLANK","before":"Ella","after":" té.","options":["bebe","bebo","bebemos"],"correct":0,"translation":"She drinks tea.","explain":"Spanish verbs change their ending for each person: yo como (I eat), ella come (she eats), nosotros comemos (we eat). Nouns have gender: el arroz, la leche."},{"id":"es-for-en.u2.l1.e9","type":"SPEAKING_REPEAT","phrase":"Yo como arroz","translation":"I eat rice","focus":["arroz"],"explain":"Say it slowly first, then at normal speed. The verb changes with the person: yo como, tú comes, ella come."},{"id":"es-for-en.u2.l1.e10","type":"DIALOGUE_COMPLETE","lines":[{"who":"A","text":"¿Qué bebes por la mañana?"}],"options":["Bebo té.","Tengo dos libros.","Ella es mi hermana."],"correct":0,"translation":"What do you drink in the morning?","explain":"Spanish verbs change their ending for each person: yo como (I eat), ella come (she eats), nosotros comemos (we eat). Nouns have gender: el arroz, la leche."},{"id":"es-for-en.u2.l1.e11","type":"WORD_BANK","prompt":"We eat bread","dir":"toTarget","answer":"Nosotros comemos pan","bank":["pan","cuánto","duermo","Nosotros","comemos"],"accept":[],"focus":["pan"],"explain":"Spanish verbs change their ending for each person: yo como (I eat), ella come (she eats), nosotros comemos (we eat). Nouns have gender: el arroz, la leche."}]}$json$::jsonb) on conflict (id) do update set title = excluded.title, content = excluded.content;
insert into public.lessons (id, unit_id, position, kind, title, content) values ('es-for-en.u2.l2', 'es-for-en.u2', 2, 'lesson', 'Home', $json${"vocab":[{"t":"casa","n":"house","e":"🏠"},{"t":"puerta","n":"door","e":"🚪"},{"t":"mesa","n":"table"},{"t":"silla","n":"chair","e":"🪑"},{"t":"cocina","n":"kitchen","e":"🍳"}],"exercises":[{"id":"es-for-en.u2.l2.e1","type":"MULTIPLE_CHOICE","prompt":"What does “casa” mean?","speak":"casa","options":[{"text":"good night"},{"text":"night"},{"text":"house"},{"text":"table"}],"correct":2,"focus":["casa"],"explain":"“casa” = “house”. Use \"estar\" (está) to say where something is. Use \"es\" for what something is like: la casa es grande, la mesa está en la cocina."},{"id":"es-for-en.u2.l2.e2","type":"MATCH_PAIRS","pairs":[{"l":"casa","r":"house"},{"l":"puerta","r":"door"},{"l":"mesa","r":"table"},{"l":"silla","r":"chair"},{"l":"cocina","r":"kitchen"}],"focus":["casa","puerta","mesa","silla","cocina"],"explain":"Match each word with its meaning. Tap a word, then tap its partner."},{"id":"es-for-en.u2.l2.e3","type":"MULTIPLE_CHOICE","prompt":"Which one is “house”?","options":[{"text":"casa","emoji":"🏠"},{"text":"nombre","emoji":"🏷️"},{"text":"viento","emoji":"💨"},{"text":"reunión","emoji":"🗓️"}],"correct":0,"focus":["casa"],"explain":"“casa” means “house” 🏠. Use \"estar\" (está) to say where something is. Use \"es\" for what something is like: la casa es grande, la mesa está en la cocina."},{"id":"es-for-en.u2.l2.e4","type":"WORD_BANK","prompt":"My house is big","dir":"toTarget","answer":"Mi casa es grande","bank":["puerta","es","despierto","grande","Mi","hasta","casa"],"accept":[],"focus":["casa"],"explain":"Use \"estar\" (está) to say where something is. Use \"es\" for what something is like: la casa es grande, la mesa está en la cocina."},{"id":"es-for-en.u2.l2.e5","type":"LISTENING_TAP","audio":"La mesa está en la cocina","answer":"La mesa está en la cocina","bank":["comprar","está","estudiamos","La","la","en","mesa","cocina","escuela"],"translation":"The table is in the kitchen","accept":[],"focus":["mesa","cocina"],"explain":"Use \"estar\" for where something is: la mesa está en la cocina."},{"id":"es-for-en.u2.l2.e6","type":"MULTIPLE_CHOICE","prompt":"How do you say “door” in Spanish?","options":[{"text":"dos"},{"text":"puerta"},{"text":"amigo"},{"text":"tú"}],"correct":1,"focus":["puerta"],"explain":"“door” in Spanish is “puerta”."},{"id":"es-for-en.u2.l2.e7","type":"TYPE_TRANSLATION","prompt":"Open the door","dir":"toTarget","answer":"Abre la puerta","accept":[],"focus":["puerta"],"explain":"Use \"estar\" (está) to say where something is. Use \"es\" for what something is like: la casa es grande, la mesa está en la cocina."},{"id":"es-for-en.u2.l2.e8","type":"FILL_BLANK","before":"La mesa","after":" en la cocina.","options":["está","es","soy"],"correct":0,"translation":"The table is in the kitchen.","explain":"Location = estar. \"Está\" is the él/ella form of estar."},{"id":"es-for-en.u2.l2.e9","type":"SPEAKING_REPEAT","phrase":"Mi casa es grande","translation":"My house is big","focus":["casa"],"explain":"Say it slowly first, then at normal speed. Use \"estar\" (está) to say where something is. Use \"es\" for what something is like: la casa es grande, la mesa está en la cocina."},{"id":"es-for-en.u2.l2.e10","type":"DIALOGUE_COMPLETE","lines":[{"who":"A","text":"¿Dónde está la mesa?"}],"options":["Está en la cocina.","Me llamo Ravi.","Tengo diez años."],"correct":0,"translation":"Where is the table?","explain":"Use \"estar\" (está) to say where something is. Use \"es\" for what something is like: la casa es grande, la mesa está en la cocina."},{"id":"es-for-en.u2.l2.e11","type":"WORD_BANK","prompt":"There is a chair here","dir":"toTarget","answer":"Aquí hay una silla","bank":["silla","una","cuánto","hoy","por","Aquí","hay"],"accept":[],"focus":["silla"],"explain":"Use \"estar\" (está) to say where something is. Use \"es\" for what something is like: la casa es grande, la mesa está en la cocina."}]}$json$::jsonb) on conflict (id) do update set title = excluded.title, content = excluded.content;
insert into public.lessons (id, unit_id, position, kind, title, content) values ('es-for-en.u2.l3', 'es-for-en.u2', 3, 'lesson', 'Daily Routine', $json${"vocab":[{"t":"despertarse","n":"to wake up","e":"⏰"},{"t":"comer","n":"to eat","e":"🍽️"},{"t":"ir","n":"to go","e":"🚶"},{"t":"estudiar","n":"to study","e":"📚"},{"t":"dormir","n":"to sleep","e":"😴"}],"exercises":[{"id":"es-for-en.u2.l3.e1","type":"MULTIPLE_CHOICE","prompt":"What does “despertarse” mean?","speak":"despertarse","options":[{"text":"bus"},{"text":"house"},{"text":"to wake up"},{"text":"green"}],"correct":2,"focus":["despertarse"],"explain":"“despertarse” = “to wake up”. Say the time with \"a la(s)\": a las seis (at six). \"Ir\" is irregular: voy, vas, va. Reflexive verbs like despertarse need me / te / se."},{"id":"es-for-en.u2.l3.e2","type":"MATCH_PAIRS","pairs":[{"l":"despertarse","r":"to wake up"},{"l":"comer","r":"to eat"},{"l":"ir","r":"to go"},{"l":"estudiar","r":"to study"},{"l":"dormir","r":"to sleep"}],"focus":["despertarse","comer","ir","estudiar","dormir"],"explain":"Match each word with its meaning. Tap a word, then tap its partner."},{"id":"es-for-en.u2.l3.e3","type":"MULTIPLE_CHOICE","prompt":"Which one is “to wake up”?","options":[{"text":"leche","emoji":"🥛"},{"text":"correo","emoji":"📧"},{"text":"despertarse","emoji":"⏰"},{"text":"sol","emoji":"☀️"}],"correct":2,"focus":["despertarse"],"explain":"“despertarse” means “to wake up” ⏰. Say the time with \"a la(s)\": a las seis (at six). \"Ir\" is irregular: voy, vas, va. Reflexive verbs like despertarse need me / te / se."},{"id":"es-for-en.u2.l3.e4","type":"WORD_BANK","prompt":"I wake up at six","dir":"toTarget","answer":"Me despierto a las seis","bank":["las","arroz","despierto","seis","Me","mi","aquí","a"],"accept":[],"focus":[],"explain":"Reflexive verbs use me/te/se: me despierto = I wake (myself) up."},{"id":"es-for-en.u2.l3.e5","type":"LISTENING_TAP","audio":"Él va a la escuela","answer":"Él va a la escuela","bank":["escuela","Él","estoy","nosotros","a","la","español","va"],"translation":"He goes to school","accept":[],"focus":[],"explain":"\"Ir\" is irregular: voy, vas, va, vamos, van."},{"id":"es-for-en.u2.l3.e6","type":"MULTIPLE_CHOICE","prompt":"How do you say “to eat” in Spanish?","options":[{"text":"comer"},{"text":"dormir"},{"text":"pan"},{"text":"lejos"}],"correct":0,"focus":["comer"],"explain":"“to eat” in Spanish is “comer”."},{"id":"es-for-en.u2.l3.e7","type":"TYPE_TRANSLATION","prompt":"We study Spanish","dir":"toTarget","answer":"Estudiamos español","accept":[],"focus":[],"explain":"Say the time with \"a la(s)\": a las seis (at six). \"Ir\" is irregular: voy, vas, va. Reflexive verbs like despertarse need me / te / se."},{"id":"es-for-en.u2.l3.e8","type":"FILL_BLANK","before":"Él","after":" a la escuela.","options":["va","voy","vas"],"correct":0,"translation":"He goes to school.","explain":"Say the time with \"a la(s)\": a las seis (at six). \"Ir\" is irregular: voy, vas, va. Reflexive verbs like despertarse need me / te / se."},{"id":"es-for-en.u2.l3.e9","type":"SPEAKING_REPEAT","phrase":"Me despierto a las seis","translation":"I wake up at six","focus":[],"explain":"Say it slowly first, then at normal speed. Reflexive verbs use me/te/se: me despierto = I wake (myself) up."},{"id":"es-for-en.u2.l3.e10","type":"DIALOGUE_COMPLETE","lines":[{"who":"A","text":"¿A qué hora te despiertas?"}],"options":["Me despierto a las seis.","Tengo dos libros.","Es mi amigo."],"correct":0,"translation":"What time do you wake up?","explain":"Say the time with \"a la(s)\": a las seis (at six). \"Ir\" is irregular: voy, vas, va. Reflexive verbs like despertarse need me / te / se."},{"id":"es-for-en.u2.l3.e11","type":"WORD_BANK","prompt":"I sleep at night","dir":"toTarget","answer":"Duermo por la noche","bank":["noche","pan","Duermo","bebe","escuela","por","la"],"accept":[],"focus":[],"explain":"Say the time with \"a la(s)\": a las seis (at six). \"Ir\" is irregular: voy, vas, va. Reflexive verbs like despertarse need me / te / se."}]}$json$::jsonb) on conflict (id) do update set title = excluded.title, content = excluded.content;
insert into public.lessons (id, unit_id, position, kind, title, content) values ('es-for-en.u2.l4', 'es-for-en.u2', 4, 'lesson', 'Time and Days', $json${"vocab":[{"t":"hoy","n":"today","e":"📅"},{"t":"mañana","n":"tomorrow"},{"t":"lunes","n":"Monday"},{"t":"por la mañana","n":"in the morning","e":"🌅"},{"t":"la noche","n":"night","e":"🌃"}],"exercises":[{"id":"es-for-en.u2.l4.e1","type":"MULTIPLE_CHOICE","prompt":"What does “hoy” mean?","speak":"hoy","options":[{"text":"night"},{"text":"today"},{"text":"to buy"},{"text":"rain"}],"correct":1,"focus":["hoy"],"explain":"“hoy” = “today”. Days use \"el\" (el lunes = on Monday). Parts of the day use \"por la\": por la mañana. Temporary states use \"estar\": estoy ocupado."},{"id":"es-for-en.u2.l4.e2","type":"MATCH_PAIRS","pairs":[{"l":"hoy","r":"today"},{"l":"mañana","r":"tomorrow"},{"l":"lunes","r":"Monday"},{"l":"por la mañana","r":"in the morning"},{"l":"la noche","r":"night"}],"focus":["hoy","mañana","lunes","por la mañana","la noche"],"explain":"Match each word with its meaning. Tap a word, then tap its partner."},{"id":"es-for-en.u2.l4.e3","type":"MULTIPLE_CHOICE","prompt":"Which one is “today”?","options":[{"text":"cinco","emoji":"5️⃣"},{"text":"hoy","emoji":"📅"},{"text":"despertarse","emoji":"⏰"},{"text":"buenas noches","emoji":"🌙"}],"correct":1,"focus":["hoy"],"explain":"“hoy” means “today” 📅. Days use \"el\" (el lunes = on Monday). Parts of the day use \"por la\": por la mañana. Temporary states use \"estar\": estoy ocupado."},{"id":"es-for-en.u2.l4.e4","type":"WORD_BANK","prompt":"I am busy today","dir":"toTarget","answer":"Hoy estoy ocupado","bank":["Hoy","estoy","va","ella","ocupado"],"accept":[],"focus":["hoy"],"explain":"Use \"estar\" for temporary states like busy or tired."},{"id":"es-for-en.u2.l4.e5","type":"LISTENING_TAP","audio":"Hasta mañana","answer":"Hasta mañana","bank":["mañana","hay","Hasta","va","bolsa"],"translation":"See you tomorrow","accept":[],"focus":["mañana"],"explain":"Days use \"el\" (el lunes = on Monday). Parts of the day use \"por la\": por la mañana. Temporary states use \"estar\": estoy ocupado."},{"id":"es-for-en.u2.l4.e6","type":"MULTIPLE_CHOICE","prompt":"How do you say “tomorrow” in Spanish?","options":[{"text":"casa"},{"text":"tren"},{"text":"hoy"},{"text":"mañana"}],"correct":3,"focus":["mañana"],"explain":"“tomorrow” in Spanish is “mañana”."},{"id":"es-for-en.u2.l4.e7","type":"TYPE_TRANSLATION","prompt":"School starts on Monday","dir":"toTarget","answer":"La escuela empieza el lunes","accept":[],"focus":["lunes"],"explain":"Days of the week use \"el\": el lunes = on Monday."},{"id":"es-for-en.u2.l4.e8","type":"FILL_BLANK","before":"La escuela empieza","after":" lunes.","options":["el","la","en"],"correct":0,"translation":"School starts on Monday.","explain":"Days use \"el\" (el lunes = on Monday). Parts of the day use \"por la\": por la mañana. Temporary states use \"estar\": estoy ocupado."},{"id":"es-for-en.u2.l4.e9","type":"SPEAKING_REPEAT","phrase":"Hoy estoy ocupado","translation":"I am busy today","focus":["hoy"],"explain":"Say it slowly first, then at normal speed. Use \"estar\" for temporary states like busy or tired."},{"id":"es-for-en.u2.l4.e10","type":"DIALOGUE_COMPLETE","lines":[{"who":"A","text":"¡Hasta mañana!"}],"options":["¡Hasta luego!","Tengo diez años.","Mi casa es grande."],"correct":0,"translation":"See you tomorrow!","explain":"Days use \"el\" (el lunes = on Monday). Parts of the day use \"por la\": por la mañana. Temporary states use \"estar\": estoy ocupado."},{"id":"es-for-en.u2.l4.e11","type":"WORD_BANK","prompt":"I work in the morning","dir":"toTarget","answer":"Trabajo por la mañana","bank":["mi","mañana","Trabajo","por","una","va","la"],"accept":[],"focus":["mañana","por la mañana"],"explain":"Days use \"el\" (el lunes = on Monday). Parts of the day use \"por la\": por la mañana. Temporary states use \"estar\": estoy ocupado."}]}$json$::jsonb) on conflict (id) do update set title = excluded.title, content = excluded.content;
insert into public.lessons (id, unit_id, position, kind, title, content) values ('es-for-en.u2.l5', 'es-for-en.u2', 5, 'lesson', 'Shopping', $json${"vocab":[{"t":"tienda","n":"shop","e":"🏪"},{"t":"dinero","n":"money","e":"💰"},{"t":"barato","n":"cheap"},{"t":"caro","n":"expensive"},{"t":"comprar","n":"to buy","e":"🛒"}],"exercises":[{"id":"es-for-en.u2.l5.e1","type":"MULTIPLE_CHOICE","prompt":"What does “tienda” mean?","speak":"tienda","options":[{"text":"meeting"},{"text":"heat / hot"},{"text":"shop"},{"text":"to go"}],"correct":2,"focus":["tienda"],"explain":"“tienda” = “shop”. Spanish questions need no \"do/does\". Just add ¿ and ? and change your tone: \"¿Tienes una bolsa?\". Use \"quiero\" (I want) + verb: quiero comprar."},{"id":"es-for-en.u2.l5.e2","type":"MATCH_PAIRS","pairs":[{"l":"tienda","r":"shop"},{"l":"dinero","r":"money"},{"l":"barato","r":"cheap"},{"l":"caro","r":"expensive"},{"l":"comprar","r":"to buy"}],"focus":["tienda","dinero","barato","caro","comprar"],"explain":"Match each word with its meaning. Tap a word, then tap its partner."},{"id":"es-for-en.u2.l5.e3","type":"MULTIPLE_CHOICE","prompt":"Which one is “shop”?","options":[{"text":"profesor","emoji":"👨‍🏫"},{"text":"comer","emoji":"🍽️"},{"text":"tienda","emoji":"🏪"},{"text":"autobús","emoji":"🚌"}],"correct":2,"focus":["tienda"],"explain":"“tienda” means “shop” 🏪. Spanish questions need no \"do/does\". Just add ¿ and ? and change your tone: \"¿Tienes una bolsa?\". Use \"quiero\" (I want) + verb: quiero comprar."},{"id":"es-for-en.u2.l5.e4","type":"WORD_BANK","prompt":"How much is this?","dir":"toTarget","answer":"Cuánto cuesta esto","bank":["esto","puerta","cuesta","nosotros","Cuánto"],"accept":[],"focus":[],"explain":"Spanish questions need no \"do/does\". Just add ¿ and ? and change your tone: \"¿Tienes una bolsa?\". Use \"quiero\" (I want) + verb: quiero comprar."},{"id":"es-for-en.u2.l5.e5","type":"LISTENING_TAP","audio":"Quiero comprar una camisa","answer":"Quiero comprar una camisa","bank":["Quiero","hasta","camisa","una","comprar","estoy","va"],"translation":"I want to buy a shirt","accept":[],"focus":["comprar"],"explain":"Quiero + infinitive = I want to ..."},{"id":"es-for-en.u2.l5.e6","type":"MULTIPLE_CHOICE","prompt":"How do you say “money” in Spanish?","options":[{"text":"dinero"},{"text":"azul"},{"text":"calor"},{"text":"ir"}],"correct":0,"focus":["dinero"],"explain":"“money” in Spanish is “dinero”."},{"id":"es-for-en.u2.l5.e7","type":"TYPE_TRANSLATION","prompt":"It is too expensive","dir":"toTarget","answer":"Es demasiado caro","accept":[],"focus":["caro"],"explain":"Spanish questions need no \"do/does\". Just add ¿ and ? and change your tone: \"¿Tienes una bolsa?\". Use \"quiero\" (I want) + verb: quiero comprar."},{"id":"es-for-en.u2.l5.e8","type":"FILL_BLANK","before":"Quiero","after":" una camisa.","options":["comprar","compro","compras"],"correct":0,"translation":"I want to buy a shirt.","explain":"After \"quiero\" use the infinitive (comprar), not a conjugated form."},{"id":"es-for-en.u2.l5.e9","type":"SPEAKING_REPEAT","phrase":"Cuánto cuesta esto","translation":"How much is this?","focus":[],"explain":"Say it slowly first, then at normal speed. Spanish questions need no \"do/does\". Just add ¿ and ? and change your tone: \"¿Tienes una bolsa?\". Use \"quiero\" (I want) + verb: quiero comprar."},{"id":"es-for-en.u2.l5.e10","type":"DIALOGUE_COMPLETE","lines":[{"who":"A","text":"¿Cuánto cuesta la camisa?"}],"options":["Cuesta veinte euros.","Me despierto a las seis.","Es mi amigo."],"correct":0,"translation":"How much is the shirt?","explain":"Spanish questions need no \"do/does\". Just add ¿ and ? and change your tone: \"¿Tienes una bolsa?\". Use \"quiero\" (I want) + verb: quiero comprar."},{"id":"es-for-en.u2.l5.e11","type":"WORD_BANK","prompt":"Do you have a bag?","dir":"toTarget","answer":"Tienes una bolsa","bank":["una","bolsa","Tienes","ella","lunes"],"accept":[],"focus":[],"explain":"No helper verb needed in Spanish questions: just add ¿ ? and raise your voice."}]}$json$::jsonb) on conflict (id) do update set title = excluded.title, content = excluded.content;
insert into public.lessons (id, unit_id, position, kind, title, content) values ('es-for-en.u2.story', 'es-for-en.u2', 6, 'story', 'En la tienda', $json${"vocab":[],"exercises":[{"id":"es-for-en.u2.story.e1","type":"INTERACTIVE_STORY","title":"En la tienda","cast":[{"id":"marta","name":"Marta","emoji":"👩"},{"id":"lopez","name":"Sr. López","emoji":"🧔"}],"parts":[{"who":"marta","text":"¡Buenos días! ¿Cuánto cuesta esta bolsa?","tr":"Good morning! How much is this bag?"},{"who":"lopez","text":"Cuesta veinte euros.","tr":"It costs twenty euros."},{"who":"marta","text":"Es cara. ¿Tiene una bolsa más barata?","tr":"It is expensive. Do you have a cheaper bag?"},{"who":"lopez","text":"Sí. Esta bolsa azul cuesta diez euros.","tr":"Yes. This blue bag costs ten euros."},{"who":"marta","text":"¡Perfecto! Quiero comprarla.","tr":"Perfect! I want to buy it."},{"who":"lopez","text":"¡Gracias!","tr":"Thank you!"}],"questions":[{"after":3,"q":"How much is the blue bag?","options":["Ten euros","Twenty euros","Five euros"],"correct":0},{"after":4,"q":"What does Marta want to do?","options":["Buy the blue bag","Sell a shirt","Drink tea"],"correct":0}],"explain":"Listen to the story, then answer the comprehension questions."}]}$json$::jsonb) on conflict (id) do update set title = excluded.title, content = excluded.content;
insert into public.lessons (id, unit_id, position, kind, title, content) values ('es-for-en.u2.timed', 'es-for-en.u2', 7, 'timed', 'Ramp Up', $json${"vocab":[],"exercises":[{"id":"es-for-en.u2.timed.e1","type":"TIMED_CHALLENGE","mode":"ramp_up","seconds":90,"pairs":[{"l":"arroz","r":"rice"},{"l":"agua","r":"water"},{"l":"té","r":"tea"},{"l":"leche","r":"milk"},{"l":"pan","r":"bread"},{"l":"casa","r":"house"},{"l":"puerta","r":"door"},{"l":"mesa","r":"table"},{"l":"silla","r":"chair"},{"l":"cocina","r":"kitchen"},{"l":"despertarse","r":"to wake up"},{"l":"comer","r":"to eat"},{"l":"ir","r":"to go"},{"l":"estudiar","r":"to study"},{"l":"dormir","r":"to sleep"},{"l":"hoy","r":"today"},{"l":"mañana","r":"tomorrow"},{"l":"lunes","r":"Monday"},{"l":"por la mañana","r":"in the morning"},{"l":"la noche","r":"night"},{"l":"tienda","r":"shop"},{"l":"dinero","r":"money"},{"l":"barato","r":"cheap"},{"l":"caro","r":"expensive"},{"l":"comprar","r":"to buy"}],"explain":"Match as many pairs as you can in 90 seconds. Wrong taps cost you time."}]}$json$::jsonb) on conflict (id) do update set title = excluded.title, content = excluded.content;
insert into public.units (id, course_id, position, title, content) values ('es-for-en.u3', 'es-for-en', 3, 'Out and About', $json${"subtitle":"Directions, transport, weather, health, work","section":"Section 3: The Real World","guidebook":{"intro":"Get around town, talk about the weather, see a doctor and chat about work.","tips":[{"title":"Directions use commands","body":"Use the tú command form: gira (turn), sigue (continue), cruza (cross).","examples":[{"t":"Gira a la izquierda","n":"Turn left"},{"t":"Sigue todo recto","n":"Go straight"}]},{"title":"Weather uses hacer","body":"Spanish says \"it makes heat\": hace calor. For rain use está lloviendo.","examples":[{"t":"Hace calor","n":"It is hot"},{"t":"Está lloviendo","n":"It is raining"}]},{"title":"The near future: ir a","body":"Use ir + a + infinitive to say what you are going to do.","examples":[{"t":"Voy a enviar un correo","n":"I am going to send an email"}]}]},"roleplayIds":["es-for-en.rp.bus","es-for-en.rp.hotel","es-for-en.rp.interview"]}$json$::jsonb) on conflict (id) do update set title = excluded.title, content = excluded.content;
insert into public.lessons (id, unit_id, position, kind, title, content) values ('es-for-en.u3.l1', 'es-for-en.u3', 1, 'lesson', 'Directions', $json${"vocab":[{"t":"izquierda","n":"left","e":"⬅️"},{"t":"derecha","n":"right","e":"➡️"},{"t":"recto","n":"straight","e":"⬆️"},{"t":"cerca","n":"near"},{"t":"lejos","n":"far"}],"exercises":[{"id":"es-for-en.u3.l1.e1","type":"MULTIPLE_CHOICE","prompt":"What does “izquierda” mean?","speak":"izquierda","options":[{"text":"three"},{"text":"tomorrow"},{"text":"left"},{"text":"shop"}],"correct":2,"focus":["izquierda"],"explain":"“izquierda” = “left”. Directions use commands: gira (turn), sigue (continue). \"Cerca de\" = near, \"lejos de\" = far from."},{"id":"es-for-en.u3.l1.e2","type":"MATCH_PAIRS","pairs":[{"l":"izquierda","r":"left"},{"l":"derecha","r":"right"},{"l":"recto","r":"straight"},{"l":"cerca","r":"near"},{"l":"lejos","r":"far"}],"focus":["izquierda","derecha","recto","cerca","lejos"],"explain":"Match each word with its meaning. Tap a word, then tap its partner."},{"id":"es-for-en.u3.l1.e3","type":"MULTIPLE_CHOICE","prompt":"Which one is “left”?","options":[{"text":"la noche","emoji":"🌃"},{"text":"dos","emoji":"2️⃣"},{"text":"izquierda","emoji":"⬅️"},{"text":"hola","emoji":"👋"}],"correct":2,"focus":["izquierda"],"explain":"“izquierda” means “left” ⬅️. Directions use commands: gira (turn), sigue (continue). \"Cerca de\" = near, \"lejos de\" = far from."},{"id":"es-for-en.u3.l1.e4","type":"WORD_BANK","prompt":"Turn left","dir":"toTarget","answer":"Gira a la izquierda","bank":["Gira","tren","izquierda","diez","la","médico","a"],"accept":[],"focus":["izquierda"],"explain":"Commands (tú form): gira = turn, sigue = continue."},{"id":"es-for-en.u3.l1.e5","type":"LISTENING_TAP","audio":"Dónde está la parada de autobús","answer":"Dónde está la parada de autobús","bank":["enviar","de","autobús","parada","está","Dónde","amable","la","el"],"translation":"Where is the bus stop?","accept":[],"focus":[],"explain":"Directions use commands: gira (turn), sigue (continue). \"Cerca de\" = near, \"lejos de\" = far from."},{"id":"es-for-en.u3.l1.e6","type":"MULTIPLE_CHOICE","prompt":"How do you say “right” in Spanish?","options":[{"text":"derecha"},{"text":"dinero"},{"text":"agua"},{"text":"trabajo"}],"correct":0,"focus":["derecha"],"explain":"“right” in Spanish is “derecha”."},{"id":"es-for-en.u3.l1.e7","type":"TYPE_TRANSLATION","prompt":"Go straight","dir":"toTarget","answer":"Sigue todo recto","accept":[],"focus":["recto"],"explain":"Directions use commands: gira (turn), sigue (continue). \"Cerca de\" = near, \"lejos de\" = far from."},{"id":"es-for-en.u3.l1.e8","type":"FILL_BLANK","before":"Gira a la","after":".","options":["izquierda","recto","lejos"],"correct":0,"translation":"Turn left.","explain":"Directions use commands: gira (turn), sigue (continue). \"Cerca de\" = near, \"lejos de\" = far from."},{"id":"es-for-en.u3.l1.e9","type":"SPEAKING_REPEAT","phrase":"Gira a la izquierda","translation":"Turn left","focus":["izquierda"],"explain":"Say it slowly first, then at normal speed. Commands (tú form): gira = turn, sigue = continue."},{"id":"es-for-en.u3.l1.e10","type":"DIALOGUE_COMPLETE","lines":[{"who":"A","text":"Perdone, ¿dónde está la estación?"}],"options":["Sigue todo recto y gira a la izquierda.","Estoy bien.","Es azul."],"correct":0,"translation":"Excuse me, where is the station?","explain":"Directions use commands: gira (turn), sigue (continue). \"Cerca de\" = near, \"lejos de\" = far from."},{"id":"es-for-en.u3.l1.e11","type":"WORD_BANK","prompt":"Está cerca de la estación","dir":"toNative","answer":"It is near the station","bank":["the","is","near","to","It","send","please","station"],"focus":["cerca"],"explain":"Directions use commands: gira (turn), sigue (continue). \"Cerca de\" = near, \"lejos de\" = far from."}]}$json$::jsonb) on conflict (id) do update set title = excluded.title, content = excluded.content;
insert into public.lessons (id, unit_id, position, kind, title, content) values ('es-for-en.u3.l2', 'es-for-en.u3', 2, 'lesson', 'Transport', $json${"vocab":[{"t":"autobús","n":"bus","e":"🚌"},{"t":"tren","n":"train","e":"🚆"},{"t":"billete","n":"ticket","e":"🎫"},{"t":"estación","n":"station","e":"🚉"},{"t":"aeropuerto","n":"airport","e":"✈️"}],"exercises":[{"id":"es-for-en.u3.l2.e1","type":"MULTIPLE_CHOICE","prompt":"What does “autobús” mean?","speak":"autobús","options":[{"text":"bus"},{"text":"station"},{"text":"you"},{"text":"left"}],"correct":0,"focus":["autobús"],"explain":"“autobús” = “bus”. Use \"tomar\" for taking transport: tomo el autobús. \"Llegar tarde\" = to be late (literally arrive late)."},{"id":"es-for-en.u3.l2.e2","type":"MATCH_PAIRS","pairs":[{"l":"autobús","r":"bus"},{"l":"tren","r":"train"},{"l":"billete","r":"ticket"},{"l":"estación","r":"station"},{"l":"aeropuerto","r":"airport"}],"focus":["autobús","tren","billete","estación","aeropuerto"],"explain":"Match each word with its meaning. Tap a word, then tap its partner."},{"id":"es-for-en.u3.l2.e3","type":"MULTIPLE_CHOICE","prompt":"Which one is “bus”?","options":[{"text":"buenas noches","emoji":"🌙"},{"text":"autobús","emoji":"🚌"},{"text":"amigo","emoji":"🧑‍🤝‍🧑"},{"text":"hoy","emoji":"📅"}],"correct":1,"focus":["autobús"],"explain":"“autobús” means “bus” 🚌. Use \"tomar\" for taking transport: tomo el autobús. \"Llegar tarde\" = to be late (literally arrive late)."},{"id":"es-for-en.u3.l2.e4","type":"WORD_BANK","prompt":"I take the bus to work","dir":"toTarget","answer":"Tomo el autobús al trabajo","bank":["el","autobús","al","tren","trabajo","calor","Tomo","sigue"],"accept":[],"focus":["autobús"],"explain":"Use \"tomar\" for taking transport: tomo el autobús. \"Llegar tarde\" = to be late (literally arrive late)."},{"id":"es-for-en.u3.l2.e5","type":"LISTENING_TAP","audio":"Un billete por favor","answer":"Un billete por favor","bank":["billete","favor","por","gira","toma","Un","mi"],"translation":"One ticket, please","accept":[],"focus":["billete"],"explain":"Use \"tomar\" for taking transport: tomo el autobús. \"Llegar tarde\" = to be late (literally arrive late)."},{"id":"es-for-en.u3.l2.e6","type":"MULTIPLE_CHOICE","prompt":"How do you say “train” in Spanish?","options":[{"text":"sol"},{"text":"mesa"},{"text":"autobús"},{"text":"tren"}],"correct":3,"focus":["tren"],"explain":"“train” in Spanish is “tren”."},{"id":"es-for-en.u3.l2.e7","type":"TYPE_TRANSLATION","prompt":"The train is late","dir":"toTarget","answer":"El tren llega tarde","accept":[],"focus":["tren"],"explain":"Spanish says \"arrives late\" (llega tarde), not \"is late\"."},{"id":"es-for-en.u3.l2.e8","type":"FILL_BLANK","before":"Un","after":", por favor.","options":["billete","casa","agua"],"correct":0,"translation":"One ticket, please.","explain":"Use \"tomar\" for taking transport: tomo el autobús. \"Llegar tarde\" = to be late (literally arrive late)."},{"id":"es-for-en.u3.l2.e9","type":"SPEAKING_REPEAT","phrase":"Tomo el autobús al trabajo","translation":"I take the bus to work","focus":["autobús"],"explain":"Say it slowly first, then at normal speed. Use \"tomar\" for taking transport: tomo el autobús. \"Llegar tarde\" = to be late (literally arrive late)."},{"id":"es-for-en.u3.l2.e10","type":"DIALOGUE_COMPLETE","lines":[{"who":"A","text":"¿Adónde quieres ir?"}],"options":["Quiero ir al aeropuerto.","Tengo diez años.","Ella bebe té."],"correct":0,"translation":"Where do you want to go?","explain":"Use \"tomar\" for taking transport: tomo el autobús. \"Llegar tarde\" = to be late (literally arrive late)."},{"id":"es-for-en.u3.l2.e11","type":"WORD_BANK","prompt":"¿Cuándo sale el tren?","dir":"toNative","answer":"When does the train leave","bank":["train","weather","When","rain","the","does","need","leave"],"focus":["tren"],"explain":"\"Salir\" (to leave) becomes \"sale\" for él / ella / it."}]}$json$::jsonb) on conflict (id) do update set title = excluded.title, content = excluded.content;
insert into public.lessons (id, unit_id, position, kind, title, content) values ('es-for-en.u3.l3', 'es-for-en.u3', 3, 'lesson', 'Weather', $json${"vocab":[{"t":"calor","n":"heat / hot","e":"🥵"},{"t":"lluvia","n":"rain","e":"🌧️"},{"t":"frío","n":"cold","e":"🥶"},{"t":"sol","n":"sun","e":"☀️"},{"t":"viento","n":"wind","e":"💨"}],"exercises":[{"id":"es-for-en.u3.l3.e1","type":"MULTIPLE_CHOICE","prompt":"What does “calor” mean?","speak":"calor","options":[{"text":"station"},{"text":"two"},{"text":"please"},{"text":"heat / hot"}],"correct":3,"focus":["calor"],"explain":"“calor” = “heat / hot”. For weather Spanish says \"hace\" + noun: hace calor (it makes heat), hace frío, hace viento. For rain use \"está lloviendo\"."},{"id":"es-for-en.u3.l3.e2","type":"MATCH_PAIRS","pairs":[{"l":"calor","r":"heat / hot"},{"l":"lluvia","r":"rain"},{"l":"frío","r":"cold"},{"l":"sol","r":"sun"},{"l":"viento","r":"wind"}],"focus":["calor","lluvia","frío","sol","viento"],"explain":"Match each word with its meaning. Tap a word, then tap its partner."},{"id":"es-for-en.u3.l3.e3","type":"MULTIPLE_CHOICE","prompt":"Which one is “heat / hot”?","options":[{"text":"calor","emoji":"🥵"},{"text":"fiebre","emoji":"🤒"},{"text":"hermano","emoji":"👦"},{"text":"dinero","emoji":"💰"}],"correct":0,"focus":["calor"],"explain":"“calor” means “heat / hot” 🥵. For weather Spanish says \"hace\" + noun: hace calor (it makes heat), hace frío, hace viento. For rain use \"está lloviendo\"."},{"id":"es-for-en.u3.l3.e4","type":"WORD_BANK","prompt":"It is hot today","dir":"toTarget","answer":"Hace calor hoy","bank":["calor","Hace","gira","estación","hoy"],"accept":[],"focus":["calor"],"explain":"Spanish uses \"hace\" (it makes) for weather: hace calor, hace frío, hace sol."},{"id":"es-for-en.u3.l3.e5","type":"LISTENING_TAP","audio":"Está lloviendo","answer":"Está lloviendo","bank":["favor","tomo","lloviendo","Está","un"],"translation":"It is raining","accept":[],"focus":[],"explain":"For weather Spanish says \"hace\" + noun: hace calor (it makes heat), hace frío, hace viento. For rain use \"está lloviendo\"."},{"id":"es-for-en.u3.l3.e6","type":"MULTIPLE_CHOICE","prompt":"How do you say “rain” in Spanish?","options":[{"text":"madre"},{"text":"profesor"},{"text":"dos"},{"text":"lluvia"}],"correct":3,"focus":["lluvia"],"explain":"“rain” in Spanish is “lluvia”."},{"id":"es-for-en.u3.l3.e7","type":"TYPE_TRANSLATION","prompt":"The weather is nice","dir":"toTarget","answer":"Hace buen tiempo","accept":[],"focus":[],"explain":"For weather Spanish says \"hace\" + noun: hace calor (it makes heat), hace frío, hace viento. For rain use \"está lloviendo\"."},{"id":"es-for-en.u3.l3.e8","type":"FILL_BLANK","before":"Hoy","after":" calor.","options":["hace","es","está"],"correct":0,"translation":"It is hot today.","explain":"For weather Spanish says \"hace\" + noun: hace calor (it makes heat), hace frío, hace viento. For rain use \"está lloviendo\"."},{"id":"es-for-en.u3.l3.e9","type":"SPEAKING_REPEAT","phrase":"Hace calor hoy","translation":"It is hot today","focus":["calor"],"explain":"Say it slowly first, then at normal speed. Spanish uses \"hace\" (it makes) for weather: hace calor, hace frío, hace sol."},{"id":"es-for-en.u3.l3.e10","type":"DIALOGUE_COMPLETE","lines":[{"who":"A","text":"¿Qué tiempo hace?"}],"options":["Hace calor.","Tengo dos libros.","Me llamo Ravi."],"correct":0,"translation":"How is the weather?","explain":"For weather Spanish says \"hace\" + noun: hace calor (it makes heat), hace frío, hace viento. For rain use \"está lloviendo\"."},{"id":"es-for-en.u3.l3.e11","type":"WORD_BANK","prompt":"Me gusta la lluvia","dir":"toNative","answer":"I like the rain","bank":["rain","medicine","I","like","doctor","email","the"],"focus":["lluvia"],"explain":"For weather Spanish says \"hace\" + noun: hace calor (it makes heat), hace frío, hace viento. For rain use \"está lloviendo\"."}]}$json$::jsonb) on conflict (id) do update set title = excluded.title, content = excluded.content;
insert into public.lessons (id, unit_id, position, kind, title, content) values ('es-for-en.u3.l4', 'es-for-en.u3', 4, 'lesson', 'Health', $json${"vocab":[{"t":"médico","n":"doctor","e":"🩺"},{"t":"medicina","n":"medicine","e":"💊"},{"t":"fiebre","n":"fever","e":"🤒"},{"t":"cabeza","n":"head"},{"t":"dolor","n":"pain","e":"😣"}],"exercises":[{"id":"es-for-en.u3.l4.e1","type":"MULTIPLE_CHOICE","prompt":"What does “médico” mean?","speak":"médico","options":[{"text":"expensive"},{"text":"doctor"},{"text":"I"},{"text":"cheap"}],"correct":1,"focus":["médico"],"explain":"“médico” = “doctor”. Pain uses \"doler\": me duele la cabeza (my head hurts). With plural body parts use \"duelen\": me duelen los pies."},{"id":"es-for-en.u3.l4.e2","type":"MATCH_PAIRS","pairs":[{"l":"médico","r":"doctor"},{"l":"medicina","r":"medicine"},{"l":"fiebre","r":"fever"},{"l":"cabeza","r":"head"},{"l":"dolor","r":"pain"}],"focus":["médico","medicina","fiebre","cabeza","dolor"],"explain":"Match each word with its meaning. Tap a word, then tap its partner."},{"id":"es-for-en.u3.l4.e3","type":"MULTIPLE_CHOICE","prompt":"Which one is “doctor”?","options":[{"text":"dinero","emoji":"💰"},{"text":"amigo","emoji":"🧑‍🤝‍🧑"},{"text":"médico","emoji":"🩺"},{"text":"aeropuerto","emoji":"✈️"}],"correct":2,"focus":["médico"],"explain":"“médico” means “doctor” 🩺. Pain uses \"doler\": me duele la cabeza (my head hurts). With plural body parts use \"duelen\": me duelen los pies."},{"id":"es-for-en.u3.l4.e4","type":"WORD_BANK","prompt":"I have a fever","dir":"toTarget","answer":"Tengo fiebre","bank":["mi","fiebre","por","Tengo"],"accept":[],"focus":["fiebre"],"explain":"Pain uses \"doler\": me duele la cabeza (my head hurts). With plural body parts use \"duelen\": me duelen los pies."},{"id":"es-for-en.u3.l4.e5","type":"LISTENING_TAP","audio":"Necesito un médico","answer":"Necesito un médico","bank":["mi","médico","correo","esta","Necesito","un"],"translation":"I need a doctor","accept":[],"focus":["médico"],"explain":"Pain uses \"doler\": me duele la cabeza (my head hurts). With plural body parts use \"duelen\": me duelen los pies."},{"id":"es-for-en.u3.l4.e6","type":"MULTIPLE_CHOICE","prompt":"How do you say “medicine” in Spanish?","options":[{"text":"buenas noches"},{"text":"yo"},{"text":"por la mañana"},{"text":"medicina"}],"correct":3,"focus":["medicina"],"explain":"“medicine” in Spanish is “medicina”."},{"id":"es-for-en.u3.l4.e7","type":"TYPE_TRANSLATION","prompt":"My head hurts","dir":"toTarget","answer":"Me duele la cabeza","accept":[],"focus":["cabeza"],"explain":"\"Doler\" works like \"gustar\": me duele la cabeza = the head hurts me."},{"id":"es-for-en.u3.l4.e8","type":"FILL_BLANK","before":"Me","after":" la cabeza.","options":["duele","duelen","tengo"],"correct":0,"translation":"My head hurts.","explain":"One head (singular) = duele. Several things = duelen."},{"id":"es-for-en.u3.l4.e9","type":"SPEAKING_REPEAT","phrase":"Tengo fiebre","translation":"I have a fever","focus":["fiebre"],"explain":"Say it slowly first, then at normal speed. Pain uses \"doler\": me duele la cabeza (my head hurts). With plural body parts use \"duelen\": me duelen los pies."},{"id":"es-for-en.u3.l4.e10","type":"DIALOGUE_COMPLETE","lines":[{"who":"A","text":"¿Cuál es el problema?"}],"options":["Tengo fiebre.","El tren llega tarde.","Es azul."],"correct":0,"translation":"What is the problem?","explain":"Pain uses \"doler\": me duele la cabeza (my head hurts). With plural body parts use \"duelen\": me duelen los pies."},{"id":"es-for-en.u3.l4.e11","type":"WORD_BANK","prompt":"Toma esta medicina","dir":"toNative","answer":"Take this medicine","bank":["Take","medicine","does","fever","this"],"focus":["medicina"],"explain":"Pain uses \"doler\": me duele la cabeza (my head hurts). With plural body parts use \"duelen\": me duelen los pies."}]}$json$::jsonb) on conflict (id) do update set title = excluded.title, content = excluded.content;
insert into public.lessons (id, unit_id, position, kind, title, content) values ('es-for-en.u3.l5', 'es-for-en.u3', 5, 'lesson', 'Work', $json${"vocab":[{"t":"oficina","n":"office","e":"🏢"},{"t":"trabajo","n":"job / work","e":"💼"},{"t":"jefe","n":"boss"},{"t":"reunión","n":"meeting","e":"🗓️"},{"t":"correo","n":"email","e":"📧"}],"exercises":[{"id":"es-for-en.u3.l5.e1","type":"MULTIPLE_CHOICE","prompt":"What does “oficina” mean?","speak":"oficina","options":[{"text":"far"},{"text":"office"},{"text":"Monday"},{"text":"fever"}],"correct":1,"focus":["oficina"],"explain":"“oficina” = “office”. Use \"ir a + infinitive\" for the future: voy a enviar un correo (I am going to send an email). Jobs: \"trabajo en ...\" = I work in ..."},{"id":"es-for-en.u3.l5.e2","type":"MATCH_PAIRS","pairs":[{"l":"oficina","r":"office"},{"l":"trabajo","r":"job / work"},{"l":"jefe","r":"boss"},{"l":"reunión","r":"meeting"},{"l":"correo","r":"email"}],"focus":["oficina","trabajo","jefe","reunión","correo"],"explain":"Match each word with its meaning. Tap a word, then tap its partner."},{"id":"es-for-en.u3.l5.e3","type":"MULTIPLE_CHOICE","prompt":"Which one is “office”?","options":[{"text":"oficina","emoji":"🏢"},{"text":"pan","emoji":"🍞"},{"text":"recto","emoji":"⬆️"},{"text":"tren","emoji":"🚆"}],"correct":0,"focus":["oficina"],"explain":"“oficina” means “office” 🏢. Use \"ir a + infinitive\" for the future: voy a enviar un correo (I am going to send an email). Jobs: \"trabajo en ...\" = I work in ..."},{"id":"es-for-en.u3.l5.e4","type":"WORD_BANK","prompt":"I work in an office","dir":"toTarget","answer":"Trabajo en una oficina","bank":["buen","voy","oficina","en","llega","una","Trabajo"],"accept":[],"focus":["oficina","trabajo"],"explain":"Use \"ir a + infinitive\" for the future: voy a enviar un correo (I am going to send an email). Jobs: \"trabajo en ...\" = I work in ..."},{"id":"es-for-en.u3.l5.e5","type":"LISTENING_TAP","audio":"Tengo una reunión a las diez","answer":"Tengo una reunión a las diez","bank":["una","Tengo","hace","jefe","a","las","diez","reunión","gira"],"translation":"I have a meeting at ten","accept":[],"focus":["reunión"],"explain":"Use \"ir a + infinitive\" for the future: voy a enviar un correo (I am going to send an email). Jobs: \"trabajo en ...\" = I work in ..."},{"id":"es-for-en.u3.l5.e6","type":"MULTIPLE_CHOICE","prompt":"How do you say “job / work” in Spanish?","options":[{"text":"oficina"},{"text":"lluvia"},{"text":"trabajo"},{"text":"estación"}],"correct":2,"focus":["trabajo"],"explain":"“job / work” in Spanish is “trabajo”."},{"id":"es-for-en.u3.l5.e7","type":"TYPE_TRANSLATION","prompt":"I will send an email","dir":"toTarget","answer":"Voy a enviar un correo","accept":[],"focus":["correo"],"explain":"Use \"ir a\" + verb for the near future: voy a enviar = I am going to send."},{"id":"es-for-en.u3.l5.e8","type":"FILL_BLANK","before":"Voy a","after":" un correo.","options":["enviar","envío","envías"],"correct":0,"translation":"I will send an email.","explain":"After \"voy a\" always use the infinitive (enviar)."},{"id":"es-for-en.u3.l5.e9","type":"SPEAKING_REPEAT","phrase":"Trabajo en una oficina","translation":"I work in an office","focus":["oficina","trabajo"],"explain":"Say it slowly first, then at normal speed. Use \"ir a + infinitive\" for the future: voy a enviar un correo (I am going to send an email). Jobs: \"trabajo en ...\" = I work in ..."},{"id":"es-for-en.u3.l5.e10","type":"DIALOGUE_COMPLETE","lines":[{"who":"A","text":"¿En qué trabajas?"}],"options":["Trabajo en una oficina.","Hace mucho frío.","Gira a la derecha."],"correct":0,"translation":"Where do you work?","explain":"Use \"ir a + infinitive\" for the future: voy a enviar un correo (I am going to send an email). Jobs: \"trabajo en ...\" = I work in ..."},{"id":"es-for-en.u3.l5.e11","type":"WORD_BANK","prompt":"Mi jefe es muy amable","dir":"toNative","answer":"My boss is very kind","bank":["meeting","is","boss","the","very","station","kind","My"],"focus":["jefe"],"explain":"Use \"ir a + infinitive\" for the future: voy a enviar un correo (I am going to send an email). Jobs: \"trabajo en ...\" = I work in ..."}]}$json$::jsonb) on conflict (id) do update set title = excluded.title, content = excluded.content;
insert into public.lessons (id, unit_id, position, kind, title, content) values ('es-for-en.u3.story', 'es-for-en.u3', 6, 'story', 'Tarde para el autobús', $json${"vocab":[],"exercises":[{"id":"es-for-en.u3.story.e1","type":"INTERACTIVE_STORY","title":"Tarde para el autobús","cast":[{"id":"sam","name":"Samuel","emoji":"🧑"},{"id":"ana","name":"Ana","emoji":"👩"}],"parts":[{"who":"sam","text":"Perdone, ¿dónde está la parada de autobús?","tr":"Excuse me, where is the bus stop?"},{"who":"ana","text":"Sigue todo recto y gira a la izquierda. Está cerca de la estación.","tr":"Go straight and turn left. It is near the station."},{"who":"sam","text":"¡Gracias! ¿El autobús llega tarde hoy?","tr":"Thanks! Is the bus late today?"},{"who":"ana","text":"Sí. Está lloviendo y el autobús llega tarde.","tr":"Yes. It is raining and the bus is late."},{"who":"sam","text":"Ay no. Tengo una reunión a las diez.","tr":"Oh no. I have a meeting at ten."},{"who":"ana","text":"Entonces toma un taxi. ¡Suerte!","tr":"Then take a taxi. Good luck!"}],"questions":[{"after":1,"q":"Where is the bus stop?","options":["Near the station","Far from the shop","In the kitchen"],"correct":0},{"after":4,"q":"Why is Samuel worried?","options":["He has a meeting at ten","He has no money","He is sick"],"correct":0}],"explain":"Listen to the story, then answer the comprehension questions."}]}$json$::jsonb) on conflict (id) do update set title = excluded.title, content = excluded.content;
insert into public.lessons (id, unit_id, position, kind, title, content) values ('es-for-en.u3.timed', 'es-for-en.u3', 7, 'timed', 'Match Madness', $json${"vocab":[],"exercises":[{"id":"es-for-en.u3.timed.e1","type":"TIMED_CHALLENGE","mode":"match_madness","seconds":90,"pairs":[{"l":"izquierda","r":"left"},{"l":"derecha","r":"right"},{"l":"recto","r":"straight"},{"l":"cerca","r":"near"},{"l":"lejos","r":"far"},{"l":"autobús","r":"bus"},{"l":"tren","r":"train"},{"l":"billete","r":"ticket"},{"l":"estación","r":"station"},{"l":"aeropuerto","r":"airport"},{"l":"calor","r":"heat / hot"},{"l":"lluvia","r":"rain"},{"l":"frío","r":"cold"},{"l":"sol","r":"sun"},{"l":"viento","r":"wind"},{"l":"médico","r":"doctor"},{"l":"medicina","r":"medicine"},{"l":"fiebre","r":"fever"},{"l":"cabeza","r":"head"},{"l":"dolor","r":"pain"},{"l":"oficina","r":"office"},{"l":"trabajo","r":"job / work"},{"l":"jefe","r":"boss"},{"l":"reunión","r":"meeting"},{"l":"correo","r":"email"}],"explain":"Match as many pairs as you can in 90 seconds. Wrong taps cost you time."}]}$json$::jsonb) on conflict (id) do update set title = excluded.title, content = excluded.content;
